pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);

    let mut score = pr - 12.0 * poly * cap;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + 3.0 * progress) * 8.0;

    // Penalize dead space: small residuals unlikely to be used
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * cap * (1.0 + progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size as f64 - pr).max(0.0) * 0.2;
        }
    }

    // Mild preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Deviation from mean residual
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to leftover after that
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - (two_step_waste as f64).min(100.0);
        } else {
            // dead space relative to next item: penalize unusable gap
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Penalize tiny unusable residuals (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer tight bins relative to mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bins are tight or item huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 150.0 - 300.0 * (1.0 - pressure);
        if item_size > 60 {
            score -= 100.0;
        }
    }

    // Early stream: slight preference to open bins and build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 20.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown)
    // can use are pure waste. Penalize small non-zero gaps super-linearly.
    if post_residual > 0 {
        // gaps below ~10 are almost certainly dead space (min historical size 10)
        if post_residual < 10 {
            score += 25.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 8.0 * (20.0 - post_residual as f64);
        }
        // gentle convex pressure on all remaining gaps
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // but penalize if it leaves a gap smaller than the next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Lookahead: leaving exactly room for the next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size as f64 as u32 {
        score -= 25.0;
    }
    // Leaving a gap that can't hold the next item but could hold nothing else is bad.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are still large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - progress) * 1.5;

    // Prefer bins whose residual is below the mean (consolidate small leftovers),
    // and keep large-residual bins available for large future items.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.3 * diff;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, reduced late in the stream
        score = bin_capacity as f64 - 15.0 + 20.0 * progress;
        // if a decent fitting bin exists, make new bin clearly worse
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers that no item (>=1) can use
    // are worthless; medium leftovers (1..=15) are likely dead space given
    // typical item sizes, so penalize them super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - pr) * 12.0; // dead-space spike
    } else if post_residual > 15 && post_residual <= 40 {
        score += pr * 0.35; // moderate waste penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    }

    // Reward tight fits relative to item size (small waste fraction).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (consolidation toward fuller bins).
    score += (pr - mean_residual) * 0.4;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (poor fit elsewhere likely) or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = item_frac * 30.0 + (open_bins_count as f64) * 0.8 + progress * 10.0;
        score += 45.0 - pressure; // default penalty, reduced under pressure
        // If lookahead item could use this bin's leftover, discourage new bin.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 8.0;
        }
    } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        // Leaving room for the next item is valuable.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space relative to the smallest possible item (1).
    // Small residuals that cannot hold even a mid-size item are wasteful.
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // Next item can't use leftover space: dead space likely.
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins unless the fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins tighter than average (good fits).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // New-bin candidate: only attractive when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced if many items remain and open bins are fragmented.
        score = 45.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can serve the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (size ~10) are unusable; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the lookahead item is also bad.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Sweet spot: post_residual exactly matching next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose" fits;
    // prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score -= 0.2 * mean_residual;

    // New-bin candidate: keep it attractive only when no open bin fits well,
    // i.e. when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins get worse (more attractive) as stream progresses if residuals are low.
        score = bin_capacity as f64 - 0.4 * mean_residual - 20.0 * progress;
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be sealed efficiently.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes: post_residual mod 10 buckets.
    let residue_class = (post_residual % 10) as f64;
    score -= 3.0 * residue_class / 10.0; // slight reward for round-ish leftovers

    // Integer-division thresholds on post_residual: classify leftover usability.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual <= eighth {
        // Tiny dead space: excellent, bin is nearly sealed.
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 15.0;
    } else if post_residual >= half {
        // Large leftover: still useful, but don't over-reward.
        score += 10.0;
    }

    // Coupling with next item: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward tight chained fits; penalize if chain leaves awkward residue.
            if next_post <= eighth {
                score -= 25.0;
            } else if next_post > half {
                score += 8.0;
            }
        } else {
            // Next item won't fit here: bin likely closes; small penalty for waste.
            score += 0.05 * post;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Fraction of capacity used by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac;

    // Progress-based mild adaptation: late in the stream, prefer sealing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / cap);

    // Prefer bins below mean residual (tighter bins first).
    score += 0.1 * (post - mean_residual);

    // New-bin candidate: penalize mildly so it only wins when fits are awful,
    // but allow it early when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest future item (size 1..100 unknown, but small gaps < 20 are
    // nearly unusable) get a heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the lookahead item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit: this creates dead space relative to lookahead.
        score += 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Encourage placing into bins with below-average residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only attractive when no
    // decent open bin exists. Penalize mildly so existing bins are preferred
    // unless dead-space penalties dominate.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item are pure waste — penalize them quadratically.
    if post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    } else if post_residual < 25 {
        // Small, likely-unusable gaps get a moderate nonlinear penalty.
        score += ((25 - post_residual) as f64).powi(2) * 0.35;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are still healthy; encourage closing out bins with small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (3.0 + 4.0 * progress);

    // Prefer bins whose residual deviates favorably from the mean: placing into
    // a bin with residual below mean reduces fragmentation of large gaps.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Lookahead: if the next item fits snugly in the post-residual, reward this
    // placement (leaves a useful gap); otherwise penalize blocking the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 12.0 {
                score -= 25.0; // next item nearly fills the gap: excellent
            } else {
                score -= 8.0;
            }
        } else {
            score += 12.0; // leaves a gap the next item cannot use
        }
    }

    // New-bin candidate handling: an empty bin is attractive early (builds
    // flexible capacity) but wasteful late or when a decent fit exists.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score = 55.0 + open_bins_count as f64 * 5.0 - early * 25.0;
        // If this bin is the last chance, opening a new bin is justified.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can realistically use are heavily penalized.
    let dead = if post_residual == 0 {
        0.0 // perfect fit: no dead space at all
    } else if post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 6.0 // tiny unusable gap
    } else if post_residual < 20 {
        18.0 // marginal gap, mostly wasted
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits (small useful residual) mildly.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // gap can't serve next item either
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing
    // bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: when average residual is small, existing bins are
    // nearly full — a new bin becomes relatively more attractive for large items.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual so it only wins when
        // existing fits are poor (large dead space).
        score = post_residual as f64 + mean_residual * 0.3 + open_bins_count as f64 * 0.3;
        if item_size >= 60 {
            score -= 10.0; // big items are hard to place later; open fresh bins
        }
    } else if mean_residual < 8.0 && post_residual > 20 {
