pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small residues are "dead space" classes.
    // Class 0: residue <= 10 (unusable for any item) -> strong penalty.
    // Class 1: residue 11..=20 (fits only tiny items) -> penalty unless next item fits.
    if post_residual <= 10 {
        score += 30.0;
    } else if post_residual <= 20 {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // lookahead rescues this class
        }
    }

    // Perfect / near-perfect fits get harmonic rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-class coupling: residue congruent to 0 mod 25 tends to host
    // common item sizes (multiples of 25 / half-capacity chunks) later.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division thresholds: how many "small items" (<=20) still fit.
    let small_slots = post_residual / 20;
    if small_slots >= 2 {
        score -= 6.0 * small_slots as f64;
    }

    // Next-item harmonic compatibility: reward if next item exactly divides residue class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 14.0; // next item creates near-perfect fit
        } else {
            score += gap as f64 * 0.25; // penalize leaving a bad class for next step
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New-bin candidate: only attractive when open bins are nearly all full
    // (mean residual small) or this item fits nowhere well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 15.0; // no open bin even fits well
        } else if mean_residual < 25.0 {
            score -= 5.0; // open bins are crowded; fresh bin fine
        } else {
            score += 25.0; // plenty of usable space elsewhere: avoid new bin
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual is already the base).

    // Perfect-fill bonus: waste nothing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead matching: if the next item fits exactly into this
    // bin's post_residual, this is a chain of two perfect placements.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mildly good, scaled by how much
            // slack remains after the hypothetical second placement.
            let second_residual = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - second_residual / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving a dead gap that
            // is smaller than the next item but too small to be useful.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 60.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already "used up"; finishing them off is good. Bins far above the
    // mean are fresh; wasting them on a loose fit is bad.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 40.0 * mean_gap;

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize new-bin candidates unless the current fit is very loose
    // (large post_residual) — a fresh empty bin should only win when the
    // item would leave big unusable slack in an existing bin.
    if bin_residual == bin_capacity {
        score += 200.0;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 250.0;
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // closing bins with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small waste -> graded reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Next item cannot use leftover: penalize dead space more strongly.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Reward tight fits (small post residual is generally good).
    if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // prefer filling them; bins above mean have more room, slight penalty.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, consolidate: prefer existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        score += 60.0 + 80.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) but avoid useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty: sliver unusable for min-size items
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or closely accommodates the next item (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            // Perfect two-item chain: strongly subtract.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score -= 30.0; // near-perfect chain bonus
            }
        } else {
            // Next item won't fit here afterwards: penalize proportionally.
            score += 15.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins
    // (consolidation), penalize dumping into already-loose bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 10.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 10.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // current item is large and would leave a well-usable residual, or when
    // open bins are nearly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Reward opening a bin for large items (good residual left).
        score -= 55.0 * item_frac;
        // Penalize opening bins when existing bins still have room.
        score += 45.0 * (mean_residual / bin_capacity as f64);
        // Slightly discourage proliferation late in the stream.
        score += 20.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));
    }

    // Mild preference for bins that are already well loaded.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_term = progress * progress;
    score += 12.0 * prog_term * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (low post_residual) more strongly later in the stream
    score -= (1.0 - progress) * (pr / cap) * 8.0;

    // Penalize dead space quadratically when residual becomes unusable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * ((nx - pr) / cap) * ((nx - pr) / cap) * 100.0;
        } else {
            // Smooth reward when next item fits this bin's post-residual
            score -= 5.0 * (1.0 - (nx / cap)) * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty proportional to post residual relative to mean residual
    if mean_residual > 0.0 {
        score += 2.0 * (norm_pr * cap - mean_residual) / cap;
    }

    // Smooth new-bin preference when current bin leaves a large awkward gap
    score += 3.0 * norm_pr * norm_pr * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress
    let mut score = post;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let poly = 2.0 * x * x - 1.5 * x * x * x;
    score += poly * (50.0 + 150.0 * progress);

    // Tight fits rewarded (small post_residual), amplified late in stream
    score -= (1.0 - x) * (1.0 - x) * 40.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 60.0 + 80.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 30.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth coupling
    score += 0.3 * (post - mean_residual).abs();

    // Mild penalty for many open bins, encouraging consolidation
    score += 2.0 * open_bins_count as f64 * progress;

    // New-bin candidate: make it unattractive unless post residual is large
    if bin_residual == bin_capacity {
        score = post + 25.0 + 100.0 * progress - 20.0 * x;
    }

    score
}

