        // If the item is large relative to capacity and mean residual is small,
        // a new bin is reasonable.
        if item_size as f64 > bin_capacity as f64 * 0.6 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling: as stream progresses, weight post_residual more heavily
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Smooth dead-space penalty: residual too small for typical future items
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (next - pr).max(0.0);
        score += 0.8 * gap * (1.0 - progress);
        // Reward if post_residual can still hold the lookahead item
        let fit_bonus = (pr / next).min(1.0);
        score -= 4.0 * fit_bonus * fit_bonus;
    }

    // Last-chance bin: smooth sigmoid-like reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress);
    }

    // Mild penalty when this bin's residual diverges from the mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // Slight preference to keep fewer open bins early on
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small item sizes) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit is always best
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 25 == 0 || pr % 20 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        4.0 // awkward leftover: penalize
    };
    score += class_bonus;

    // Dead-space penalty: tiny unusable remainders.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportionally to how well the next item fills the leftover.
            let fill = next_item_size as f64 / pr as f64;
            score -= 8.0 + 14.0 * fill;
        } else {
            // Next item cannot use the leftover: penalize by the gap.
            score += (next_item_size - pr) as f64 * 0.35;
        }
    } else {
        // Last item: only perfect closure matters.
        if pr > 0 {
            score += pr as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to residual or all open bins fit poorly.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Base cost of opening a new bin, discounted early in the stream
        // or when many bins are already open (consolidation phase over).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 22.0 - 10.0 * progress;
        if frac > 0.5 {
            new_bin_cost += 6.0; // big items tolerate fresh bins
        }
        if mean_residual < frac * cap * 0.5 {
            new_bin_cost -= 8.0; // open bins are nearly full anyway
        }
        score += new_bin_cost;
    } else {
        // Reward filling existing bins proportionally to utilization achieved.
        let used_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * used_frac;
    }

    // Mild pressure to close out bins when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible item (min size 1, but practically items <= 10 are rare) are
    // "dead". Penalize hard if post_residual lands in an unusable band.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver: worst outcome
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Perfect or near-perfect fit: big reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer it
    // over opening a new bin (opening a new bin costs a full bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; the more bins
    // already open, the stronger the incentive to fill an existing one.
    let pressure = (open_bins_count as f64).min(50.0) * 1.5;
    if bin_residual < bin_capacity {
        score -= pressure * 0.3;
    } else {
        // New-bin candidate: only attractive when item is large and would
        // leave a large, usable residual or a perfect fit in existing bins is
        // impossible.
        score += 55.0; // base cost of opening a new bin
        if item_size >= 70 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 35.0;
    }
    // If next item would NOT fit in post_residual but would fit a fresh bin,
    // slight penalty for blocking.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    let mean_r = mean_residual;
    if (post_residual as f64) < mean_r {
        score -= 5.0;
    }

    // Early-stream: allow slightly more liberal new-bin opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily penalize dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let size = item_size as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 15 {
        score -= 30.0;
    }

    // === 2-step lookahead: does next_item_size fit into post_residual? ===
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Excellent: the next item chains perfectly into this bin.
            let slack = post - next;
            if slack == 0.0 {
                score -= 150.0; // perfect 2-item chain
            } else if slack <= 10.0 {
                score -= 60.0;
            } else {
                score -= 20.0 * (1.0 - slack / cap);
            }
        } else {
            // Next item won't fit here; penalize residual that is close-but-not-fitting
            // (unusable dead space for the known next item).
            let gap = next - post;
            if gap <= 10.0 {
                score += 40.0; // tantalizing near-miss: bad dead space
            }
            // Favor bins whose post_residual matches nothing upcoming less harshly
            // if the residual is large and generally useful.
            score += 5.0;
        }
    } else {
        // Last item: just minimize post_residual (already base score).
        score -= 10.0;
    }

    // Relative-to-mean-residual term: prefer bins tighter than average (best-fit flavor).
    score += (post - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin offers a good chain for the next item.
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity; encourage only late in stream
        // or when many bins are open (diversification) — otherwise discourage.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * progress;
        if next_item_size > 0 && (next_item_size as u32) <= bin_residual {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Mild pressure to consolidate: fewer open bins is better.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space (dead space is quadratic bad).
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward;
    // if this bin's post-residual would strand the next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0 * (1.0 - nxt / 100.0);
        } else if (post_residual as f64) > 0.0 {
            // stranded dead space relative to the known future demand
            score += 0.25 * (post_residual as f64).min(nxt);
        }
    }

    // New-bin candidate handling: opening a new bin is expensive early when few
    // bins exist; late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let new_bin_cost = 30.0 + 40.0 * (1.0 - progress) + 0.8 * open_bins_count as f64;
        score += new_bin_cost;
    } else {
        // Mild preference for filling bins that are already relatively empty
        // (consolidate waste into few bins) when many bins are open.
        score += 0.15 * (bin_residual as f64 - mean_residual) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Global balance: penalize bins far below mean residual late in the stream
    // (they fragment remaining capacity), reward bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev * (0.5 + progress);

    // Time-horizon term: as the stream ends, waste matters more than bin count.
    score -= 8.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 + progress);

    // Tight fits reward: cubic decay of penalty as post_residual shrinks
    let tight = -2.5 * (1.0 - norm_pr).powi(3) * (0.6 + 0.4 * progress);

    // Penalize residual that cannot fit a plausible next item (smooth gate)
    let next_gate = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        1.8 * gap * gap * (0.5 + progress)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -3.0 * (1.0 + progress) } else { 0.0 };

    // New-bin candidate: neutral-to-slightly-penalized early, more penalized late
    let new_bin = if bin_residual == bin_capacity {
        0.8 + 2.5 * progress * progress
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins below mean (consolidation)
    let dev = 0.4 * (mean_residual - pr) / cap;

    let score = pr + 4.0 * poly + tight + next_gate + last_chance + new_bin + dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Classes via integer division into coarse capacity fractions.
    let class = post_residual / 10; // 0..=10 harmonic class
    // Dead space penalty: residuals in awkward classes get extra cost.
    // Class 0 = perfect fit (great). Classes 1..3 (1-39) = awkward dead space.
    // Classes 7..9 (70-99) = still roomy, fine.
    if class == 0 {
        score -= 60.0; // perfect fit, heavily reward
    } else if class <= 3 {
        score += 15.0 + (3 - class) as f64 * 5.0; // penalize awkward small leftovers
    } else if class >= 7 {
        score -= 5.0;
    }

    // Modulo-10 harmonic: residuals that are multiples of 10 align with
    // typical item granularity, making them easier to fill later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            score += leftover2 as f64 * 0.3;
            if leftover2 <= 10 {
                score -= 10.0; // near-perfect chain
            }
        } else {
            // next item won't fit here; mildly penalize if we burn a scarce bin
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    // rather than opening a new one, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: baseline so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // Many open bins: opening another is wasteful.
        score += open_bins_count as f64 * 1.5;
    }

    // Tightness reward: filling a bin that is already mostly full.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Mean residual divergence: prefer bins whose residual is below average
    // (close them out) when the item fits well.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold any
    // plausible item (min size 1..100 unknown, assume worst-case small
    // threshold ~10) are dead space. Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // gap too small for next item: likely dead
    }

    // Tightness reward: fraction of the bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 0.8 * open_bins_count as f64 * (1.0 - tightness);

    // Mean residual coupling: prefer bins whose residual is already below average
    // (closing out small bins rather than fragmenting large ones).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists; make the empty
    // bin costly so it is chosen only when open bins would waste space badly.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Late in the stream, consolidate: penalize opening space in fresh bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can be packed here: reward, scaled by how tight the
            // two-item packing is (small leftover after both items is best).
            let two_step_leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 - two_step_leftover.min(60.0);
        } else {
            // Next item cannot follow here: penalize leaving dead space that
            // is too small for the upcoming item.
            let dead = post_residual as f64;
            score += 20.0 + dead * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual here equals capacity - item_size).
    if bin_residual == bin_capacity {
        score += 120.0 + (item_size as f64) * 0.5;
    }

    // Early in the stream, slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Lookahead: reward if next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use leftover: penalize large dead space
            score += 0.15 * (post_residual as f64 - if post_residual >= next_item_size {0.0} else {(post_residual as f64).min(next_item_size as f64)});
            if post_residual < 10 {
                score += 5.0; // tiny unusable sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += 0.3 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: later in the stream, be more conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New empty bin candidate: usually undesirable unless residual would be huge waste.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 60.0 + waste;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: must open new bin
        }
        if item_size >= 70 {
            score -= 20.0; // large items deserve a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: penalize post residual, but non-linearly (quadratic waste growth).
    let mut score = pr * (1.0 + fit_frac * fit_frac);

    // Smooth stream-progress coupling: later in the stream, waste matters more
    // (compounding), so amplify the residual penalty polynomially in progress.
    let progress_coupling = 1.0 + 0.6 * progress * progress + 0.4 * progress;
    score *= progress_coupling;

    // Interaction: residual relative to mean residual across open bins.
    // A bin with residual well below mean is a tight fit -> reward it.
    let mean_dev = (pr - mean_residual) / cap;
    score += 25.0 * mean_dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin for a poor fit). Smooth via inverse count.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 40.0 * last_chance * (1.0 - fit_frac) * (1.0 + progress);

    // Lookahead coupling: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= pr;
        let slack_ratio = (pr - next_item_size as f64).abs() / cap;
        if next_fits {
            score -= 15.0 * (1.0 - slack_ratio) * (1.0 + progress);
        } else {
            // Penalize leaving residual that is just slightly too small for next item
            // (near-miss dead space), smoothly via sigmoid-like term.
            let near_miss = 1.0 / (1.0 + ((pr - next_item_size as f64) / 8.0).exp());
            score += 20.0 * near_miss * (1.0 + progress);
        }
    }

    // New-bin candidate: residual == capacity. Penalize mildly early, more later,
    // unless current bins are very full (mean residual low) — then opening is fine.
    if bin_residual == bin_capacity {
        let open_pressure = 1.0 / (1.0 + mean_residual / cap);
        score += 10.0 + 30.0 * progress * open_pressure;
    }

    // Tiny tie-break toward tighter fits overall.
    score += 0.01 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: reward residuals that are "useful"
    // (large enough to hold common small items), penalize dead zones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Dead-space classes via integer division thresholds
        if pr <= 5 {
            score -= 40.0; // near-perfect, effectively sealed
        } else if pr <= 15 {
            score += 25.0; // awkward sliver: can hold almost nothing
        } else if pr <= 30 {
            score += 8.0; // mediocre
        } else if pr <= 50 {
            score -= 10.0; // still useful
        } else {
            score -= 20.0; // roomy leftover
        }
        // Modulo arithmetic: residuals that align with typical item granularities
        // (multiples of 10) are easier to fill later.
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        // Fractional capacity classes: post residual in (0.2C, 0.35C) is worst zone
        let frac = pr as f64 / cap;
        if frac > 0.2 && frac < 0.35 {
            score += 12.0;
        }
    }

    // Lookahead: if the next item fits exactly/nicely into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // perfect chained fill
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 - slack * 0.2; // tighter follow-up fit is better
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a new bin is generally wasteful unless the
    // current item is huge and would leave a nasty residual elsewhere.
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.3 * open_bins_count as f64;
        // large items pair poorly with existing residuals; allow new bin then
        let item_frac = item_size as f64 / cap;
        score = base - 30.0 * (item_frac - 0.5).max(0.0);
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if many bins fit the item, opening new bin is clearly bad
        if fitting_bins_count > 2 {
            score += 30.0;
        }
    }

    // Slight preference for tighter bins when residuals are similar
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    // Anything below the minimum plausible future item size is a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard penalty for creating a sliver that likely never fits
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is the ideal outcome
    }

    // Penalize post_residual quadratically when it falls into the "hard to fill"
    // band (too small for most items, too big to ignore): band [10, 30].
    let pr = post_residual as f64;
    if pr >= 10.0 && pr < 30.0 {
        score += (30.0 - pr) * 2.5; // the smaller the leftover in this band, the worse
    }

    // Reward tight fits: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins (especially near-full ones); with few bins, new bins are cheaper.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item could exactly fill this bin's post_residual,
    // reward the placement; if next item clearly cannot use the leftover, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() < 1.0 {
            score -= 35.0; // next item completes this bin perfectly
        } else if nx > pr && pr > 0.0 {
            score += 8.0; // next item cannot use the leftover at all
        } else if nx <= pr {
            score -= 5.0; // leftover remains usable by next item
        }
    }

    // Mild global pressure: as the stream progresses, discourage leaving many
    // moderately-filled bins around; keep mean residual as a tiebreaker signal.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr) * 0.15 * progress;

    // New-bin candidate calibration: an empty bin has residual == capacity;
    // make it attractive only when it would beat a very poor fit.
    if bin_residual == bin_capacity {
        score += 12.0; // slight default bias toward existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 18.0 - gap;
            } else {
                // Next item leaves large unusable slack: mild penalty.
                score += gap * 0.15;
            }
        } else {
            // Next item cannot fit here; the smaller the leftover, the better
            // since we'd otherwise strand dead space.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.25;
        }
    } else {
        // Last item: close bins aggressively.
        score -= 30.0;
    }

    // Compare against the mean residual: placing into a bin with residual
    // well below mean concentrates waste, which is good; placing into an
    // outlier-large residual bin is discouraged slightly.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // the stream is early. Penalize opening new bins otherwise.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_pressure = if next_item_size > 0 && next_item_size > post_residual { 0.0 } else { 35.0 };
        score += 40.0 + waste_pressure + progress * 15.0
            - (post_residual as f64 - item_size as f64).abs() * 0.1;
        // Empty-bin residual equals capacity; keep its base score high so
        // it only wins when open bins score poorly.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins with larger residuals when item is large.
    if item_size > 50 {
        score -= (bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that likely cannot be reused.
    let next_fits = (next_item_size as f64) <= post_residual as f64 && next_item_size > 0;
    if !next_fits && post_residual > 0 {
        score += post_residual as f64 * 0.8;
    } else if next_fits {
        // Lookahead bonus: placing here leaves room for the next item.
        score -= 12.0;
    }

    // Last-chance bonus: avoid opening a new bin when only this bin fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for bins far from mean residual (prefer typical bins).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Prefer fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * progress * 0.3;

    // Slight penalty proportional to number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 && post_residual < 20 {
            score += 60.0; // existing bins give tight fit; keep them
        } else if fitting_bins_count == 0 {
            score -= 30.0; // must open new bin
        } else {
            score += 10.0 + 20.0 * (1.0 - tightness);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let t = progress;
    let poly = pr_norm * (1.0 + 2.0 * t + 3.0 * t * t + 1.5 * t * t * t);
    score += 4.0 * poly;

    // Penalize wasted space more sharply late in the stream (smooth cubic).
    score += 6.0 * pr_norm * pr_norm * (0.5 + t * t);

    // Reward tight fits: small post residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * (1.0 - t);

    // Last-chance bonus: only one bin fits, smooth reward.
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * t;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let n = next_item_size as f64;
        score -= 2.0 + 3.0 * (n / 100.0) * (1.0 + t);
    }

    // Prefer bins below mean residual slightly (use larger leftover space).
    score += 0.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Mild penalty for proliferating open bins, smoothed by progress.
    score += 0.3 * open_bins_count as f64 * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (high utilization) are rewarded.
    let cap_f = bin_capacity as f64;

    // Reward tight fits: exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Integer-division thresholds: leftover <= 10 is nearly dead space of no
    // loss (any item is >= 1), so reward it strongly.
    if post_residual <= 10 && post_residual > 0 {
        score -= 60.0;
    }

    // Harmonic class via modulo: leftover divisible into large chunks is
    // reusable. Class by post_residual % 25 (quarter-capacity harmonic).
    let quarter = post_residual % 25;
    score -= (25 - quarter) as f64 * 0.4;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward small chained leftover, harmonic classes of 10
            score -= (nxt_post % 10) as f64 * 0.8;
            if nxt_post <= 10 {
                score -= 40.0;
            }
        } else {
            // next item cannot use this leftover: penalize large wasted space
            score += 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has neutral-ish score, but
    // should only win when all open bins have poor fits (large post_residual).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits beat it.
        score = cap_f * 0.75 + 30.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
        // If many bins already open, prefer filling them.
        score += open_bins_count as f64 * 2.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it is already tight), reward selecting it.
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fill is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals below the minimum item size (1) can never
    // be used, but residuals in the "awkward small gap" band (1..=15) are highly
    // likely to be dead space for typical streams. Penalize them heavily.
    if post_residual >= 1 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64);
    } else if post_residual <= 25 {
        // Moderately awkward gap.
        score += 15.0;
    }

    // Reward bins whose residual can still fit the lookahead item exactly well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead cannot use this bin's remainder: mild penalty unless residual is 0.
        if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 5.0 * open_bins_count as f64 * (0.5 + progress);
        // But if the current item is large relative to mean residual, new bin
        // may be preferable; relax the penalty a bit.
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Slight preference for tighter existing bins (waste minimization).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: post_residual that cannot fit the next item is wasted
    // until the stream ends, so weight it more heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact 2-step packing: post_residual == next_item_size is perfect.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: dead space penalty.
            score += 25.0;
        }
    }

    // Reward using bins that are already nearly full (small residual before placement),
    // i.e., best-fit behavior: favor small bin_residual among fitting bins.
    score += 0.5 * bin_residual as f64;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly
    // prefer placing here over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild preference for reducing the number of open bins when many are open.
    score += 0.1 * open_bins_count as f64;

    // Slight reward when this bin's residual is below the mean residual
    // (i.e., we are filling the emptier-relative bins first... actually prefer
    // filling the fullest bins: penalize if bin_residual > mean_residual).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // New-bin candidate: give it a neutral-to-slightly-high baseline so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed: early phases favor bin consolidation,
    // late phases favor keeping residuals flexible for the tail.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight packing (small post_residual).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 6.0 * tightness;

    // Penalize leaving awkward dead space that few item sizes could ever fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver under minimum size
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the ONLY bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to wasted potential.
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // New-bin candidate handling: empty bin starts at full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many items remain and open bins are fragmented,
        // expensive when the stream is nearly done or few bins fit the item.
        let horizon = 1.0 - progress;
        score += 18.0 * (1.0 - horizon) + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 5.0; // nothing else fits; new bin is fine
        }
        if fitting_bins_count >= 3 {
            score += 12.0; // plenty of alternatives; discourage sprawl
        }
        // If next item is large, a fresh bin is attractive for pairing.
        if next_item_size >= 50 && item_size <= 50 {
            score -= 6.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, prefer filling
    // existing bins rather than adding dead space anywhere.
    score += 0.05 * mean_residual * (1.0 - tightness.min(1.0));

    // Late-stream conservatism: as the stream ends, minimize new bins strongly.
    if progress > 0.8 {
        score += 10.0 * progress * (bin_residual == bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover residual, with non-linear (quadratic/cubic) coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 30.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Coupling with item size: large items into large residuals preferred; smooth interaction.
    score += 12.0 * norm_item * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 18.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty scaled by how much dead space is created.
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // Penalize bins whose residual deviates strongly from the mean (imbalance), smoothly.
    score += 6.0 * ((pr - mean_residual) / cap).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate: keep it attractive early, discourage opening bins late.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.4 * progress) + 10.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands.
    let post = post_residual;
    let class = post % 10;
    let quot = post / 10;

    // Dead-space penalty: residuals in (0,10) are nearly unusable (min item ~1).
    if post > 0 && post < 10 {
        score += 25.0;
    }
    // Perfect fit reward.
    if post == 0 {
        score -= 30.0;
    }

    // Harmonic compatibility: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Reward proportional to how snugly next item nests.
            let slack = (post - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
            // Bonus if next item exactly fills the residual (perfect chain).
            if next_item_size == post {
                score -= 20.0;
            }
            // Harmonic alignment: next_item_size class matches residual class.
            if next_item_size % 10 == class {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's residual: penalize large residuals wasted.
            score += 6.0 + (post as f64) * 0.05;
        }
    } else {
        // Last item: prefer zero residual strongly.
        score += (post as f64) * 0.5;
    }

    // Integer-division thresholds on post_residual: encourage residuals that
    // remain "harmonic" multiples of common item sizes.
    let harmonic = (post % 25 == 0) || (post % 20 == 0) || (post % 50 == 0);
    if harmonic {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bin; relax penalty if existing residuals are small or stream is late.
        score += 40.0 * (1.0 - pressure) * (1.0 - 0.5 * progress);
        if next_item_size > 0 && next_item_size > post {
            score -= 5.0; // next item won't fit crowded bins anyway
        }
    } else {
        // Mild preference for tighter existing bins (smaller residual).
        score += (bin_residual as f64) * 0.02;
        // Prefer bins below mean residual (better-than-average fill).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Scale-aware coupling: large items prefer large residuals.
    if item_size > bin_capacity / 2 && bin_residual >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit bonus relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it is chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.2;
    }

    // Lookahead coupling: penalize leaving a gap that neither this nor the next item can use well.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size > post_residual) && post_residual < next_item_size {
            score += 5.0; // dead gap relative to lookahead
        }
        if post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 6.0; // gap perfectly seeds the next item
        }
    }

    // Deviation from mean residual: prefer bins below mean (more filled).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is exponentially cheaper).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // Penalize leaving residual that is slightly too small for the next item
        // (unusable wedge relative to the lookahead).
        if post_residual < next_item_size && next_item_size - post_residual <= 10 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Penalize new-bin usage unless this is the only fitting bin (avoid bin sprawl).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 30.0; // forced: must open a bin
        } else if fitting_bins_count == 1 {
            score += 5.0; // mild preference to use the last-chance bin
        } else {
            score += 25.0; // plenty of fitting bins; discourage opening new ones
        }
    } else if fitting_bins_count == 1 {
        // This open bin is the last chance before opening a new bin: reward using it.
        score -= 12.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // especially early in the stream when consolidation matters most.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rel = post_residual as f64 - mean_residual;
    score += rel * (0.4 + 0.4 * (1.0 - progress));

    // Mild penalty for leaving large residuals that nothing small can exploit later.
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (but not 0, which is perfect).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // dead-space penalty grows super-linearly for tiny leftovers
        let dead = pr / cap;
        score += 45.0 * dead * dead;
        // penalty if leftover is too small for any plausible future item
        if pr < 10.0 { score += 25.0; }
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 30.0 + 0.25 * (next_item_size as f64);
        } else {
            // next item won't fit here: mild penalty, worse late in stream
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 + 10.0 * progress;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer emptier ones (spread waste)
        score += 0.05 * (fitting_bins_count as f64);
    }

    // Prefer bins whose residual deviates below the mean (concentrate small residuals).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Time horizon: late in the stream, favor closing bins tightly (avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins open or late in stream
        score += 35.0 + 20.0 * progress + 2.0 * (open_bins_count as f64);
        // but if nothing else fits (fitting_bins_count == 1 includes only this?), handled above
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0; // open bins are too full; new bin is reasonable
        }
    } else {
        // using existing bins is good late in the stream
        score -= 10.0 * progress;
    }

    // Slight preference to fill bins with larger residual first (best-fit-like).
    score -= 0.05 * (bin_residual as f64);

    // Coupling: reward using a bin when item is large relative to capacity
    score -= 0.1 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = pr * pr / cap;                       // quadratic dead-space penalty
    let coupling = fit * fit * (1.0 - progress);     // early: prefer tight fits less strongly
    let late_coupling = fit * progress * progress;  // late: reward low post-residual more

    let mut score = base - 8.0 * coupling + 10.0 * late_coupling;

    // Lookahead: reward bins whose post-residual fits the next item (smooth kernel).
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - gap * gap);
    }

    // Last-chance bonus: smooth in scarcity of fitting bins.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - fit);
    }

    // Mild penalty for deviating from mean residual (keeps bin pool homogeneous).
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: smooth penalty growing with stream progress / open bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Perfect fit: strongly reward closing the bin.
    if pr == 0 {
        score -= 60.0;
    }

    // Dead-space classes: residuals too small to hold the minimum item (1..10)
    // are likely wasted; penalize modulo-harmonic "awkward" classes.
    if pr > 0 && pr < 10 {
        score += 10.0;
    }
    score += (pr % 10) as f64 * 0.35;

    // Integer-division thresholds: bins whose post_residual leaves a large
    // divisible slack are more reusable.
    if pr >= 20 {
        score -= 3.0;
    }
    if pr >= 50 {
        score -= 3.0;
    }

    // Lookahead coupling (k=2): reward if the next item fits in the slack,
    // with a harmonic bonus when next_item_size divides pr cleanly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let n = next_item_size.max(1);
            score -= 7.0 + ((pr % n) as f64) * 0.25;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Prefer bins tighter than the current mean residual (better fill balance).
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.12 * diff;
    } else {
        score -= 0.05 * (-diff);
    }

    // New-bin candidate: penalize opening a fresh bin unless necessary.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 12.0 * (1.0 - progress);
        // If the next item would pair perfectly with this item in a fresh bin,
        // soften the penalty slightly (harmonic pairing check).
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest future item are waste.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect or near-perfect fill: strong reward.
        score -= 40.0;
    } else if post_residual > bin_capacity as f64 as u32 / 2 {
        // Large leftover is flexible, mild bonus.
        score -= 5.0;
    } else {
        // Mid-range leftover: penalize proportionally to how "unusable" it is
        // (unlikely a typical item fits well).
        let awkwardness = 1.0 - (post_residual as f64 / (bin_capacity as f64 / 2.0));
        score += 15.0 * awkwardness * awkwardness;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's leftover anyway; neutral.
        score += 2.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average is good).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Progress-aware tightening: later in the stream, be stricter about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: next item fills post_residual perfectly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect chain fit gets a big bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual that next item can't use at all
        if next_item_size > post_residual {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 5.0;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Penalize large dead space that nothing typical can fill
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // small leftover is fine
    }
    if post_residual > 60 {
        score += 8.0; // large residual = wasteful unless lookahead matches
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Slight preference for keeping number of open bins low
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless residual would be perfectly reusable
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 45.0; // opening fresh bin to chain next item is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is wasteful by default; give it a high base cost
        // that shrinks when we're desperate (only one fitting bin = this bin)
        // or when the item fits very poorly everywhere else.
        let mut nb = 60.0;
        if fitting_bins_count <= 1 {
            nb -= 45.0;
        }
        // Late in the stream, prefer closing out open bins rather than spawning
        nb += progress * 15.0;
        // Many open bins with slack => discourage new bins
        nb += (open_bins_count as f64).sqrt() * 2.0;
        // If next item is huge, having a fresh bin may help
        if next_item_size >= 60 {
            nb -= 10.0;
        }
        return nb;
    }

    // Tight fit reward: strongly favor small post_residual
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Dead-space penalty: if the lookahead item cannot fit in the post residual,
    // the leftover is likely dead space -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 {
        // Reward when the next item fits exactly into the leftover
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With many alternatives, mild tie-breaking toward tighter fits
        score += fitting_bins_count as f64 * 0.5;
    }

    // Global slack coupling: if mean residual is high, prefer filling
    // below-average-residual bins (compact usage); score -= when this bin
    // is tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Time horizon: late in the stream, be aggressive about closing bins,
    // i.e., favor bins whose post residual becomes tiny.
    score -= progress * (bin_capacity - post_residual) as f64 * 0.2;

    // Perfect-fit explosion
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr / cap;

    // Smooth polynomial coupling: residual value decays with progress
    let decay = 1.0 - 0.5 * t * t - 0.25 * t * t * t;
    score *= decay;

    // Reward tight fits more strongly later in the stream (quadratic in fill ratio)
    let fill = 1.0 - pr / cap;
    score -= 0.6 * fill * fill * (0.5 + 0.5 * t);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 0.4 * (nxt - pr) / cap * (1.0 + t);
        } else if pr >= nxt {
            score -= 0.2 * (nxt / cap) * (1.0 - t);
        }
    }

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 0.5 * (1.0 + t * t);
    }

    // Mild penalty for spreading across many open bins
    score += 0.02 * (open_bins_count as f64).powi(2) / (cap + 10.0);

    // Alignment with mean residual: prefer bins deviating below mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.15 * dev * dev - 0.1 * dev;

    // New-bin candidate: make it attractive only when item is large relative to capacity
    if bin_residual == bin_capacity {
        let big = item_size as f64 / cap;
        score += 0.3 - 0.9 * big * big - 0.3 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space is bad, but small
    // "harmonically reusable" residuals (multiples of common item classes)
    // are less bad than arbitrary fragments.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class the residual by integer division into harmonic bands (capacity/8).
    let band = post_residual / (bin_capacity / 8).max(1);
    let band_penalty: f64 = match band {
        0 => -6.0,                       // near-perfect fit
        1 => 0.0,                        // small usable gap
        2 => 4.0,                        // awkward mid gap
        3 => 2.0,                        // half-full residual, still reusable
        4 => 5.0,
        5 => 7.0,
        6 => 3.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Modulo-10 class: residuals divisible by 10 (and by 5) are more likely
    // to be exactly filled by future integer-sized items.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 1.0; // non-round fragment: penalize
    }

    // Lookahead coupling: reward residuals that exactly (or harmonically)
    // accommodate the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 8.0; // perfect two-item chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing residuals are large
    // (item would waste a lot of an open bin) or no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, discounted late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 25.0 - 10.0 * progress;
        // If the item leaves a harmonically nice residual in a fresh bin
        // (e.g. residual divisible by 10), opening is more attractive.
        if post_residual % 10 == 0 {
            new_bin_score -= 4.0;
        }
        // If many open bins fit, opening a new bin is rarely needed.
        new_bin_score += 3.0 * (fitting_bins_count as f64).min(5.0);
        // If mean residual is high, open bins are crowded -> new bin ok.
        new_bin_score -= (mean_residual / cap).min(1.0) * 2.0;
        score += new_bin_score;
    }

    // Mild preference for bins with below-mean residual (tighter packing).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight tie-break toward larger items filling big residuals.
    score -= 0.02 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Very tight fits (near-perfect packing) get a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Open-bins pressure: prefer already-open bins over opening new ones,
    // with pressure growing as more bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 5.0 + 0.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    }
    // Penalize leaving a gap that the next item almost-but-doesn't fit into
    // (wasted potential dead space).
    if next_item_size > post_residual && next_item_size > 0 && (next_item_size as u32 - post_residual) <= 8 {
        score += 8.0;
    }

    // Slight preference for filling bins that are already relatively full
    // (low residual relative to mean) to consolidate space.
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late in the stream, tighten up: penalize new bins more, reward tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize small post_residual (lower score = better).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: reward proportional to match quality.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += 30.0 * (shortfall / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins with below-mean residual are more "loaded",
    // prefer packing into them to keep many bins usable.
    score -= 15.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with small residual relative to open-bin count (consolidation).
    score += 5.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: post-residual too small to be useful later.
    let dead_threshold = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty for wasting large residual
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins with residual close to item (best-fit style) scaled by global mean.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.10;

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // late in stream, favor using existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.8;
    score -= progress * 2.0;

    // Global residual balance: prefer bins whose residual is near mean residual
    // (keeps pool homogeneous, easier future packing), unless it's a new bin.
    if bin_residual != bin_capacity {
        let mean_gap = (bin_residual as f64 - mean_residual).abs();
        score += mean_gap * 0.05;
    } else {
        // New bin candidate: only attractive when current bins are quite full
        // or the item is large relative to mean residual.
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 6.0 - avg_fullness * 10.0 + item_size as f64 * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (wasted space), scaled by stream progress
    let mut score = pr * (1.0 + progress * (1.0 - norm_pr) * 2.0);

    // Smooth cubic interaction: small residuals are worse late in the stream
    let small_res = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 60.0 * small_res * progress;

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 12.0 * snug * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // next item won't fit: penalize dead space mildly
        score += 8.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Slight preference for filling bins below mean residual (consolidation)
    score -= 0.15 * (mean_residual - pr);

    // New empty bin candidate: penalize unless it's early or residual would be tiny
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score += 20.0 * (1.0 - early * 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: quantize post_residual into capacity-fraction classes.
    // Residuals in the lowest class (0..=10) are near-perfect fits -> reward strongly.
    // Residuals in the "dead zone" (1..9) are unusable for most items -> penalize.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries via integer division thresholds (harmonic fractions of C).
    let quarter = bin_capacity / 4;   // 25
    let fifth = bin_capacity / 5;     // 20
    let tenth = bin_capacity / 10;    // 10

    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= tenth {
        // Dead-space class: tiny residual that likely can't fit anything (min item 1,
        // but typical items are large). Penalize proportionally to how "wasted" it is.
        score += (tenth as f64 - pr) * 1.5;
    } else if post_residual <= fifth {
        // Low class: still useful for small items.
        score -= 5.0;
    } else if post_residual <= quarter {
        // Mid class: neutral, slight reward for keeping usable slack.
        score -= 2.0;
    }

    // Modulo harmonic class: residuals congruent to small values mod 10 pair well
    // with lookahead items; reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain fit: next item perfectly fills this bin
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 15.0 - (leftover as f64) * 0.4; // prefer tight follow-up fits
            // Harmonic bonus: leftover in a "clean" class (multiple of 10)
            if leftover % 10 == 0 && leftover > 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this bin's residual; if this bin is the only
            // fitting bin, we may strand the next item -> penalize.
            if fitting_bins_count == 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // using it avoids opening a new bin -> strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has fixed residual == capacity.
    // Only prefer it when existing residuals are poor fits (large post_residual
    // would remain) or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: capacity of fresh slack.
        score = cap * 0.9;
        // If the item would leave a very tight residual in an open bin elsewhere,
        // opening a new bin is fine; otherwise discourage.
        if post_residual as f64 <= tenth as f64 {
            score += 40.0; // some open bin fits nearly perfectly; don't open new
        }
        if mean_residual < 0.5 * cap && fitting_bins_count >= 1 {
            score += 25.0; // existing bins have room; discourage new bin
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Mild preference to fill bins that are already mostly full relative to fleet.
    if bin_residual < bin_capacity {
        let fill_ratio = 1.0 - (bin_residual as f64) / cap;
        score -= fill_ratio * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min size 1..100 unknown; assume items >= 10 typical) are
    // heavily penalized, especially small unusable gaps.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 30.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Small residuals that still fit a common small item are mildly favored
    // (tight packing), but large leftovers are also fine (flexible bins).
    // Penalize mid-range waste quadratically.
    let pr = post_residual as f64;
    if pr > dead_threshold && pr < 25.0 {
        score += (25.0 - pr) * 0.8;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, favor filling existing
    // bins over opening new ones.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + obp * 2.0;
    } else {
        score -= obp.min(10.0) * 1.5;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 - gap.min(20.0);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0; // next item won't reuse this bin's leftover
    }

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    } else {
        score += (1.0 - progress) * 5.0;
    }

    // Mean residual coupling: if this bin is far below the mean residual,
    // prefer filling it (it's the "worst" bin and using it balances state).
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += dev * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 1-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Partial lookahead credit: how well post_residual covers next item
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap <= 20.0 {
            score -= 40.0 - 2.0 * gap; // near-miss bonus decaying with gap
        } else if gap < 0.0 {
            score += 15.0; // next item won't fit here; slight penalty
        }
    }

    // Penalize unusable dead space relative to the smallest possible item (1)
    if post_residual < 10 {
        score += 30.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average when they still fit well
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 25.0; // default penalty for opening new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score += 30.0; // avoid wasting the last-chance bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin keeps room for lookahead item
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    // Prefer bins with less residual overall (tight packing) scaled by open bins
    score += 0.1 * post_residual as f64 * (open_bins_count as f64 / 10.0).min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward bins that can also host the lookahead item.
            score -= 2.5;
        }
        // Exact pairing bonus: item + next item fills bin nearly perfectly.
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() <= 2.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Discourage spreading across many open bins when mean residual is low.
    score += open_bins_count as f64 * 0.15;

    // Slight bias toward bins with residuals near the global mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in the stream, be conservative (prefer good fits,
    // open bins freely); late in the stream, pack aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    if progress > 0.7 && post_residual <= 10 {
        score -= 8.0; // near-perfect closure late in the stream
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large dead space otherwise) or there are few alternatives.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = (post_residual as f64) >= 0.0; // base comparison
        let penalty = 12.0 - progress * 6.0;
        score += if poor_fit_elsewhere { penalty.max(0.0) } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = step_index;
    let _ = total_items;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = post_residual;
    let _ = fitting_bins_count;
    0.0
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into buckets of 10.
    // Small post_residual classes (tight fits) are strongly rewarded.
    let class = post_residual / 10;
    let class_bonus: f64 = match class {
        0 => 60.0,                      // near-perfect fit
        1 => 25.0,                      // leaves a 10-slush slot
        2 => 12.0,                      // fits a size<=20 next item
        3 => 4.0,
        4 => 0.0,
        5 => -3.0,                      // half-full: mediocre
        6 => -6.0,
        7 => -9.0,
        _ => -12.0,                     // large dead space
    };
    score -= class_bonus;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;              // perfect chained fit
        } else if next_item_size <= post_residual {
            // harmonic ratio: next item consumes a large fraction of what's left
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.7 {
                score -= 30.0 * frac;
            } else if frac > 0.4 {
                score -= 12.0 * frac;
            } else {
                score -= 3.0 * frac;
            }
        } else {
            // next item cannot fit here: penalize leaving awkward leftovers
            // (post_residual that is large but unusable for the known next item)
            if post_residual >= 30 {
                score += 8.0;
            }
            if next_item_size > bin_residual {
                score -= 5.0; // next item needs a new bin anyway; keep this bin flexible
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Modulo-3 harmonic penalty on post_residual: residues 0 (clean multiples)
    // combine well with common item sizes.
    let m = post_residual % 3;
    if m == 0 {
        score -= 3.0;
    } else if m == 2 {
        score += 1.0;
    }

    // Discourage opening new bins when decent existing bins exist.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost of opening a bin
        score += 55.0;
        // cheaper to open early when few bins are open (spread items out)
        score -= (open_bins_count as f64).sqrt() * 4.0;
        // late in the stream, consolidating matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // but if the next item is huge, a fresh bin is safer
        if next_item_size >= 60 && post_residual == bin_capacity {
            score -= 25.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Tiny tie-break toward larger items consuming big residual bins.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual <= 10 {
            // tiny sliver: almost certainly dead space
            score += (11 - post_residual as f64) * 60.0;
        } else if post_residual < 25 {
            // medium-small gap: risky, may only fit small items
            score += (25.0 - post_residual as f64) * 6.0;
        }
        // large leftover space is naturally penalized by base score
    } else {
        // perfect fit: strong reward
        score -= 200.0;
    }

    // Reward filling a bin completely-ish (post_residual small relative to capacity)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage scattering across many bins,
    // but relax pressure as the stream progresses (future items still coming).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = 8.0 * (1.0 - 0.5 * progress);
    score += open_bins_count as f64 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins would create dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 150.0;
        // but if current bins are crowded (high mean residual spread / many bins),
        // opening fresh is more attractive
        score -= mean_residual * 0.4;
        if fitting_bins_count == 0 {
            score -= 300.0; // no alternative anyway
        }
    } else {
        // existing bin: compare against mean residual — prefer bins that are
        // tighter than average (better consolidated)
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.5;
        } else {
            score += (bin_residual as f64 - mean_residual) * 0.3;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 90.0;
    }
    // If next item cannot fit anywhere after this placement (post_residual too small
    // but nonzero), mild penalty for blocking
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward near-perfect match of post_residual with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // perfect match bonus
        if post_residual == next_item_size {
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item still fits after this placement: mild reward, tighter gap is better
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize wasted potential
            score += 10.0 + diff * 0.3;
        }
    }

    // Penalize creating unusable dead space (very small leftover that few items can use)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward leaving space consistent with the average bin slack (balance residuals)
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (10.0 + 20.0 * progress);
        score += 15.0 + 10.0 * crowding;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // new bin is attractive if the leftover after placement matches the next item well
        if next_item_size > 0 && (bin_capacity - next_item_size) == item_size {
            score -= 55.0;
        }
    }

    // Mild preference for tighter fits overall
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size is wasted — penalize it extra.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Best-fit style: prefer bins whose residual matches item closely.
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if the next item fits into the post_residual, reward;
    // otherwise penalize leaving residual that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // exact chaining is excellent
            if next_item_size == post_residual {
                score -= 10.0;
            }
        } else {
            // leftover smaller than next item becomes dead space
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // New-bin candidate handling: an empty bin is attractive when open bins
    // are mostly full or fragmented (low mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln().max(1.0);
        // open a new bin when existing bins are tight/fragmented,
        // but not when there is plenty of slack (early stream).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= fragmentation * 40.0 * pressure * (0.4 + 0.6 * progress);
        // discourage hoarding new bins when mean residual is large
        score += mean_residual * 0.2;
    }

    // Prefer filling bins with large residual gaps when many bins are open
    // (consolidation): penalize bins far below mean residual.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.1 * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Late-stream: favor compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, residual dead space is heavily penalized.
    let waste_weight = 0.5 + 2.0 * progress * progress;
    score += waste_weight * (pr / cap) * (pr / cap) * 20.0;

    // Smooth tightness reward: strongly prefer small post-residual via cubic term.
    let tight = 1.0 - pr / cap;
    score -= 15.0 * tight * tight * tight;

    // Lookahead coupling: smooth interaction between post_residual and next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = ((pr - nx).max(0.0)) / cap;
        let gap = ((pr - nx).abs()) / cap;
        score += 10.0 * fit_next * fit_next + 5.0 * gap * gap * (1.0 - progress);
    }

    // Last-chance bonus: smooth sigmoid-like reward when this bin is the only fitter.
    if fitting_bins_count == 1 {
        score -= 25.0 / (1.0 + (open_bins_count as f64) * 0.3);
    }

    // Penalize bins far from mean residual (smooth dispersion penalty).
    score += 0.05 * (pr - mean_residual).abs() * (1.0 + progress);

    // Mild pressure against opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.5 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common item
    // granularity (10) are "clean" and reusable; odd residues create dead space.
    let pr = post_residual;
    if pr > 0 {
        let clean = (pr % 10 == 0) as f64;
        score -= 12.0 * clean;                    // reward perfectly divisible leftovers
        let half_clean = (pr % 5 == 0) as f64;
        score -= 4.0 * half_clean;                // partially reusable class
        if pr < 10 {
            score += 25.0;                        // sub-granular dead space penalty
        }
    } else {
        score -= 40.0;                            // perfect fill is ideal
    }

    // Fraction-of-capacity harmonic bands for post_residual.
    let frac = post_residual as f64 / cap;
    if frac <= 0.1 && pr > 0 {
        score += 15.0;                            // tiny unusable sliver
    } else if frac <= 0.3 {
        score += 3.0;
    } else if frac <= 0.6 {
        score -= 6.0;                             // sweet spot: fits half-class items
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item divides into leftover cleanly
            if pr % next_item_size == 0 {
                score -= 20.0;
            } else {
                score -= 8.0 * (next_item_size as f64 / cap);
            }
        } else {
            // Next item won't fit here; leftover becomes dead unless clean class
            if pr % 10 != 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits (post_residual already does).
        score += 2.0 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; discounted late in the stream or when
        // mean residual across open bins is already fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 30.0 + 20.0 * progress;
        if mean_residual < 25.0 {
            open_cost -= 15.0;                    // open bins are cluttered; fresh bin helps
        }
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            open_cost -= 8.0;                     // next item needs fresh space anyway
        }
        score += open_cost;
    }

    // Mild tie-break toward bins below mean residual (keeps large holes available).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor dense packing.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 2.0 * pressure;

    // Lookahead: if next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that is almost-but-not-quite the next item.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless it is genuinely needed
    // (no fitting open bins) or current bins are very full.
    if bin_residual == bin_capacity {
        let base_penalty = 55.0;
        let fullness_relief = if mean_residual < 25.0 { 70.0 } else { 0.0 };
        let last_chance_relief = if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        score += base_penalty - fullness_relief - last_chance_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item packing: residual fully consumed by lookahead
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fit_ratio; // partial lookahead fit, scaled by tightness
        } else {
            // next item does not fit: penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(30.0);
        }
    } else {
        // Last item: residual is pure waste; penalize any leftover.
        score += post_residual as f64 * 0.5;
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual near the mean keeps flexibility; extreme small residuals are dead space.
    let pr = post_residual as f64;
    if pr < 10.0 {
        score += 25.0; // unusable sliver of space
    } else if pr > mean_residual * 1.5 && mean_residual > 0.0 {
        score += 5.0; // much larger than typical residual: hoarding capacity
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else. Neutral base for empty bin; discourage early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress); // prefer open bins early, allow new bins later
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item: fresh bin preserves large contiguous space
        }
    }

    // Mild penalty for fragmenting when many bins are already open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0 * (30.0 - post_residual as f64) / 20.0; // moderately wasteful
    }

    // Lookahead coupling: if next item fits in post_residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize proportionally to how much we block it.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bonus: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only if item fits poorly everywhere else or few open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 20.0;
        // Base penalty keeps open bins preferred unless compensated.
        score += 30.0 + 5.0 * crowding - 20.0 * progress;
        // Perfect fit of item into fresh bin is attractive early.
        if item_size as f64 / bin_capacity as f64 > 0.9 {
            score -= 15.0;
        }
    } else {
        // Reward using bins whose residual is already small (consolidation).
        let residual_frac = bin_residual as f64 / bin_capacity as f64;
        score -= 8.0 * (1.0 - residual_frac);
    }

    // Global state: many open bins with high mean residual -> prefer packing into existing bins.
    let mean_res_frac = mean_residual / bin_capacity as f64;
    score -= 5.0 * mean_res_frac * (open_bins_count as f64).ln().max(0.0);

    // Mild time decay: late in stream, be more conservative (favor exact fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // smooth polynomial base: reward tight fits (low post_residual)
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // non-linear coupling with stream progress: later in stream, penalize wasted space more
    let progress_term = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * progress_term * norm_post * norm_post;

    // lookahead coupling: if next item fits the post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = nxt / (post + 1.0);
        if fit_ratio <= 1.0 {
            score -= 8.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
        } else {
            score += 3.0 * (fit_ratio - 1.0).min(2.0);
        }
    }

    // last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // mean residual coupling: prefer bins close to mean residual (balanced packing)
    let dev = (mean_residual - post) / cap;
    score += 4.0 * dev * dev;

    // new-bin candidate: penalize mildly so it's chosen only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress + 0.15 * item;
    }

    // slight preference for fuller bins
    score -= 0.05 * item * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c * 0.25;
    let half = c * 0.5;

    // Perfect fit: reward strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else {
        // Harmonic class penalty: residual in (0,10] is gold, (10, quarter] ok,
        // (quarter, half] poor, > half wasteful
        if post_residual <= 10 {
            score -= 50.0;
        } else if pr <= quarter {
            score += 0.5 * (post_residual as f64);
        } else if pr <= half {
            score += 1.0 * (post_residual as f64);
        } else {
            score += 2.0 * (post_residual as f64);
        }
    }

    // Modulo-class coupling: does post_residual + next_item_size land on a
    // "harmonic" residue (divisible into capacity evenly)?
    if next_item_size > 0 && next_item_size <= post_residual {
        let sum = post_residual + next_item_size;
        // sum that is 0 mod 25 or 0 mod 20 => clean future packing
        if sum % 25 == 0 || sum % 20 == 0 || sum % 50 == 0 {
            score -= 40.0;
        }
        // next item exactly fills bin afterwards
        if next_item_size == post_residual {
            score -= 500.0;
        }
    } else if next_item_size > post_residual {
        // dead space that the lookahead cannot use: penalize more in later stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 40.0 * progress;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive if item is large and no open bin fits well
    if bin_residual == bin_capacity {
        let large = item_size as f64 > 0.6 * c;
        let poor_fit = fitting_bins_count == 0 || (mean_residual < item_size as f64 * 0.9);
        if large && poor_fit {
            score -= 80.0;
        } else {
            score += 120.0;
        }
    }

    // Slight preference for tighter bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps that cannot fit the known next item.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
        } else {
            // Reward keeping room for the lookahead item.
            score -= 8.0;
        }
        // Perfect fit for next item: strong reward.
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    if fitting_bins_count > 1 {
        score -= 6.0;
    }
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 12.0;
        // But if the best alternative leaves a tiny dead gap, allow opening a new bin.
        if post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size as f64) {
            score -= 35.0;
        }
    }

    // Mild pressure coupling with number of open bins: consolidate when many bins open.
    score += open_bins_count as f64 * 0.4;

    // Slight progression-aware adjustment: late in stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    // Mean-residual coupling: if mean residual is high, favor filling this bin more.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize wasted residual non-linearly.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Strong bonus for exact or near-exact closure of the bin.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item exactly fills the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to how much room is left after that.
            score -= 10.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item won't fit here: penalize bins that leave awkward mid-size gaps.
            score += 8.0;
        }
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing residuals are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, grows with number of open bins and stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 10.0 * open_bins_count as f64 * (0.3 + progress);
        // If the item is small and some open bin has a comparable residual, opening is wasteful.
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // If next item is large, a fresh bin may be valuable as a staging area.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 18.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight packing).
        let tightness = 1.0 - (post_residual as f64 / bin_residual as f64);
        score -= 15.0 * tightness;
        // Prefer bins with residual below the mean (consolidate waste into few bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be conservative (penalize large residuals slightly);
    // late in the stream, prioritize closing bins aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.8 {
            score -= 12.0 * (1.0 - waste_frac);
        } else if progress < 0.2 {
            score += 5.0 * waste_frac;
        }
    }

    // Mild preference for using more-open bins rather than accumulating many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth base: reward small post_residual via non-linear (quadratic) coupling.
    let mut score = pr * (1.0 + 0.008 * pr) / cap;

    // Normalized dead-space penalty, smoothly amplified with stream progress.
    let dead_frac = pr / cap;
    score += 12.0 * dead_frac * dead_frac * (0.5 + progress);

    // Tight-fit bonus: smooth interaction between item size and residual.
    let fill = item_size as f64 / cap;
    score -= 3.0 * fill * fill * (1.0 - dead_frac);

    // Last-chance bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - dead_frac);
    }

    // Crowd penalty: many open bins favor consolidation.
    score += 0.05 * (open_bins_count as f64).sqrt() * dead_frac;

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.02 * gap * gap / cap;
        score -= 1.5 * (1.0 - gap / cap).max(0.0);
    }

    // Mild drift toward bins below mean residual (smooth coupling).
    score += 0.3 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual into capacity-fraction buckets.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..=9 decile of residual

    // Dead-space penalty: residuals that few item sizes can use.
    // Small residuals (< 10) are dead; residual in (50,60) etc. also awkward.
    if post_residual < 10 {
        score += 50.0; // unusable sliver
    }
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (exact fill is perfect).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Integer-division threshold: can next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chainable: subtract proportional bonus, extra if exact chain
            score -= 10.0;
            if post_residual == next_item_size {
                score -= 40.0;
            }
            // harmonic coupling: post_residual / next_item_size ratio near 1 is best
            let ratio = post_residual as f64 / next_item_size as f64;
            if ratio < 2.0 {
                score -= 5.0 * (2.0 - ratio);
            }
        } else {
            // next item cannot chain here: penalize by the gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where this item is a better fraction
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin starts with score == capacity.
    // Make it attractive only when current bin would leave large dead space
    // or when bins are getting crowded.
    if bin_residual == bin_capacity {
        // base: fresh bin is neutral-good
        score = 0.5 * bin_capacity as f64;
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // many open bins with big mean residual -> don't open more
        score += 0.4 * mean_residual + 2.0 * open_bins_count as f64;
        // if next item is huge, fresh bin gives flexibility
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Prefer fuller bins (best-fit bias beyond raw post_residual):
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
    }

    // Mild global pressure: as stream progresses, discourage waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.15);

    // Class-based coupling: mid-range deciles (4..6) are the most reusable
    // residual classes for typical item sizes.
    if class >= 4 && class <= 6 {
        score -= 6.0;
    } else if class >= 1 && class <= 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible future item (size 1..100 unknown, but small gaps < 10 are
    // almost certainly dead) get a heavy nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 0 && post_residual < 25 {
        // Moderately risky small gaps: penalize quadratically.
        let r = post_residual as f64;
        score += 0.8 * (25.0 - r) * (25.0 - r) / 10.0;
    }

    // Reward tight fits strongly (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space avoidance must account for lookahead: if the next item
    // fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use this gap: penalize proportionally.
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // more bins; encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: bins far below the mean residual leave more
    // room elsewhere; slightly favor bins with residual near/above mean.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.15 * diff;

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Give it a moderate base penalty so
    // last-chance / tight-fit open bins beat it, but keep it competitive
    // when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is cheaper (fewer future
        // items to strand), so ease the penalty.
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain completion: perfect pair
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += 20.0 + 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive for very large items or no good fit
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the lookahead rewards may override
        score += 120.0;
        if item_size >= 60 {
            score -= 100.0; // big items are fine in fresh bins
        }
    }

    // Slight preference for filling bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no existing bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let t = step_index as f64 / total_items.max(1) as f64;
        let urgency = (0.35 + 0.65 * t) * (item_size as f64 / bin_capacity as f64).powi(2);
        let new_score = bin_capacity as f64 * 0.55 - urgency * 40.0 * pressure
            - if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.5 { 8.0 } else { 0.0 };
        return new_score;
    }

    // Reward near-perfect fits (small post residual) super-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - fit_ratio).powi(4);
    }

    // Dead-space penalty: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits the post-residual, reward heavily.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 6.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer bins where this item is a tighter fit.
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Prefer filling bins that are already relatively full (low residual).
    score += 8.0 * (bin_residual as f64 / bin_capacity as f64 - mean_residual / bin_capacity as f64).max(-1.0).min(1.0);

    // Global fragmentation control: penalize opening spread when many bins open.
    let t = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count as f64 > 2.0 + 8.0 * t {
        score += 2.5 * (open_bins_count as f64 - 2.0 - 8.0 * t);
    }

    // Mild preference to consolidate into bins below mean residual early on.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post_residual, with non-linear (quadratic) coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth interaction: prefer tight fits more strongly later in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize bins whose residual deviates from the mean residual (non-linearly).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward residual that cannot fit the next item (dead space is fine if next item is large),
    // but penalize leaving residual that awkwardly fits the next item with big waste.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let waste = pr - next_item_size as f64;
        score += 0.15 * waste * (1.0 + progress);
    } else if next_item_size > 0 {
        score -= 3.0; // next item can't use this residual anyway; keep bin attractive
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bin moderately attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer small post_residual, but with diminishing returns (harmonic-ish).
    score = post * (1.0 + 0.15 * (post / cap));

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: penalize if next item fits into post_residual (waste of a good gap),
    // reward if next item would NOT fit (gap is dead anyway, so use it now).
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 25.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 15.0;
        }
    } else {
        // Last item: any bin that fits is fine; prefer tightest.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: gaps in low residue classes are hard to fill.
    let cls = post_residual % 10;
    score += match cls {
        0 => -20.0,          // round gap, easy to reuse
        1 | 2 => 18.0,       // nearly-full slivers, likely dead
        3..=6 => 6.0,        // awkward mid classes
        _ => -5.0,
    };

    // Integer-division thresholds on post_residual: quarter/half capacity classes.
    if post_residual >= bin_capacity / 2 {
        score += 30.0; // bin still half empty: poor placement choice
    } else if post_residual >= bin_capacity / 4 {
        score += 5.0;
    } else {
        score -= 10.0; // tight fit into mostly-full bin is good
    }

    // Prefer bins with below-mean residual (more filled bins) slightly.
    score += 0.2 * (post - mean_residual);

    // Early in stream: be more willing to open new bins (score new empty bin lower);
    // late in stream: consolidate into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 40.0 - 80.0 * progress; // new-bin candidate: cheap early, expensive late
    } else {
        score -= 40.0 * progress; // favor existing bins as stream progresses
    }

    // Slight penalty for proliferation of open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is too small for the smallest plausible item (1..100).
    // Use a superlinear penalty for tiny gaps, strongest for gaps < ~15.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    } else {
        // Mild superlinear component to prefer tighter fits generally
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Perfect fit bonus: strongly reward leaving exactly 0 residual.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 5 {
            score -= 25.0; // chain fit: next item nearly fills the bin
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover gap: penalize proportional to gap size
        score += (post_residual as f64) * 0.3;
    }

    // Open bins pressure: penalize bins with large residuals when many bins are open,
    // pushing toward consolidating into fuller bins.
    let open_pressure = (open_bins_count as f64).ln().max(1.0);
    score += (post_residual as f64) * open_pressure * 0.05;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: empty bin should only win when no open bin offers a decent fit.
    // Penalize opening a new bin when it wastes potential (residual == capacity means post_residual = capacity - item).
    if bin_residual == bin_capacity {
        // Opening new bin: strong penalty scaled by how many open bins could have fit.
        if fitting_bins_count > 0 {
            score += 55.0 + (post_residual as f64) * 0.2;
        } else {
            // No alternative: new bin is necessary, small penalty only.
            score += 5.0;
        }
        // Late in stream, opening new bins is more acceptable (bins get committed).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    // Mean residual coupling: if mean residual is low, prefer tighter fills (penalize leaving slack).
    if (post_residual as f64) > mean_residual {
        score += ((post_residual as f64) - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - (post_residual as f64)) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: place item so next item exactly fills the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize dead space the next item cannot use (post_residual < next_item_size).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Mild reward for leaving room the next item can still fit into.
        if post_residual > next_item_size {
            score -= 2.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: only one bin fits the item, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 12.0;
        }
    }

    // Late in the stream, consolidate: favor tightest fits more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale waste by relative fill of the bin.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (item_size as f64) * 0.9;

    // Penalize dead space that is too small to hold any plausible item (min size 1).
    if post_residual > 0 && post_residual < 4 {
        score += 25.0; // nearly-full bin is fine, but tiny slivers are wasted
    }

    // Lookahead: penalize if post-residual can't fit the next item but bin_residual could
    // (i.e., placing here destroys a useful slot for the upcoming item).
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += next_item_size as f64 * 0.6;
        }
        // Reward if post-residual exactly accommodates the next item (chain packing).
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Reward if post-residual still fits the next item comfortably.
        else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.3;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or mean residual is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins when a decent-fit option exists elsewhere.
        score += 18.0
            + open_bins_count as f64 * 1.5
            - mean_residual * 0.35
            - progress * 5.0;
        // Late in the stream, opening fresh bins is less useful; discourage more.
        if progress > 0.8 {
            score += 10.0;
        }
        // If next item is large, an empty bin gives flexibility.
        if next_item_size > 60 {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += gap * gap * 0.02;
        // Slight preference for consolidating into bins with low mean residual spread.
        if (bin_residual as f64 - mean_residual).abs() < 5.0 {
            score -= 2.0;
        }
    }

    // Dynamic time horizon: early stream, be tolerant of imperfect fits to keep options open;
    // late stream, prioritize filling existing bins to the brim.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 {
        score -= post_residual as f64 * 0.25 * progress;
    } else {
        score += post_residual as f64 * 0.05 * (1.0 - progress);
    }

    // Avoid leaving many bins with medium residuals: reward balancing against mean.
    if !is_new_bin && bin_residual as f64 > mean_residual + 20.0 {
        score += 4.0; // this bin is unusually roomy; using it for a small item may be wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let coupling = pr_norm * (1.0 + 2.0 * progress * progress) * (1.0 + 0.5 * (1.0 - progress));

    let mut score = pr * (1.0 + 0.4 * progress) + 20.0 * coupling;

    // Penalize dead space that no plausible item can use (smooth ramp near small residuals).
    let dead = if pr_norm < 0.1 { (0.1 - pr_norm) / 0.1 } else { 0.0 };
    score += 15.0 * dead * dead;

    // Reward bins whose leftover can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when bin deviates from mean residual (encourage balanced fills).
    score += 0.15 * (pr - mean_residual).abs();

    // Encourage tighter fills as bins accumulate.
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets reward "clean" residuals
    let post = post_residual;
    let class = post % 10;
    match class {
        0 => score -= 12.0,            // perfectly divisible residual: reusable slot
        5 => score -= 6.0,             // half-class residual: still flexible
        2 | 4 | 6 | 8 => score -= 3.0, // even residuals pair well
        1 | 3 | 7 | 9 => score += 4.0, // odd residuals: awkward dead space
        _ => {}
    }

    // Reward residuals in ranges that match common item size classes (1..100)
    if post >= 50 {
        score -= 5.0; // can still host a large item
    } else if post >= 25 {
        score -= 2.0;
    } else if post > 0 && post < 10 {
        score += 6.0; // tiny dead space
    }

    // Integer-division thresholds: post_residual / next_item_size
    if next_item_size > 0 && post >= next_item_size {
        // if next item fits exactly, big bonus
        if post % next_item_size == 0 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > post {
        // next item won't fit here; penalize mildly, less if post is near-zero waste
        score += 3.0;
        if post == 0 {
            score -= 8.0; // perfect closure
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly worse than a tight good fit
        score = (bin_capacity - post) as f64 * 0.9 + 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Stream progression: early on, prefer consolidation (fewer bins); later, allow spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity as f64).ln().exp().min(2.0);

    // Penalize bins far from mean residual (outliers create fragmentation)
    score += ((post as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: favor bins where the next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make opening a new bin moderately expensive,
    // but viable if the item would leave a tiny dead gap in every existing bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual < 10 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this placement is excellent (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves further waste: mild penalty on slack.
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.35 * slack_after_next;
        } else {
            // Next item will NOT fit here: post residual becomes dead space
            // relative to the lookahead. Penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.9 * gap;
        }
    }

    // Penalize residuals too small to ever be useful (items >= 10 assumed,
    // but be safe for sizes 1..100): tiny unusable slivers are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far below mean concentrates waste; prefer bins with larger residuals
    // for small items (best-fit within a family of similar bins).
    if post_residual as f64 > mean_residual {
        score -= 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score += 0.25 * (mean_residual - post_residual as f64);
    }

    // Last chance: if this is the ONLY bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Make the empty bin moderately costly
    // so it wins only when open-bin scores are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, or when many bins are open, slightly favor
        // consolidating instead of spreading.
        if open_bins_count > 0 {
            score += 2.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Late in the stream, avoid opening new bins (no future to amortize).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 8.0 * tightness * tightness;

    // Perfect-fit jackpot.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            post_residual < next_item_size
        } else {
            post_residual < 10
        };
        if dead {
            score += 6.0 + 0.15 * post_residual as f64;
        }
    }

    // Lookahead coupling: reward bins whose leftover fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 5.0 * chain_fit;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in the stream, keep bins flexible (prefer larger leftovers);
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0 * tightness;

    // Crowding: when many bins are open, discourage spreading; favor using existing bins.
    if bin_residual < bin_capacity {
        score -= 0.05 * open_bins_count as f64 * (1.0 - progress);
    }

    // Relative-to-mean residual shaping: bins tighter than average get slight preference.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score += 1.5 * (rel - 1.0).clamp(-1.5, 1.5);

    // New-bin candidate: opening a fresh bin is only attractive when the item is large
    // or the stream is young and no good fits exist.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let openness = 1.0 - progress;
        score += 10.0 - 8.0 * item_frac - 4.0 * openness * item_frac;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild preference for tight fits.
    // Later (progress ~ 1): strong preference for minimizing post_residual.
    let progress_coupling = 1.0 + 3.0 * progress * progress;

    let mut score = pr * progress_coupling;

    // Non-linear penalty for large post-residuals (quartic dead-space term).
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * cap;

    // Reward near-perfect fits smoothly (bell-shaped bonus around small residual).
    let tightness = (-norm_pr * 12.0).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.4 + 0.6 * progress);
    } else if next_item_size > 0 {
        // Penalize leaving a gap that the next item cannot use.
        score += 8.0 * norm_pr * progress;
    }

    // Mild pressure toward consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = pr / cap; // for empty bin, pr = cap - item_size
        score += 10.0 + 30.0 * (1.0 - fit_quality) * (0.5 + progress);
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: small dead space classes get bonuses.
        let pr = post_residual;
        if pr <= 10 {
            score -= 60.0; // nearly-perfect residual, likely reusable
        } else if pr <= 20 {
            score -= 25.0;
        } else if pr <= 30 {
            score -= 8.0;
        }

        // Modulo classes: residuals congruent to small values mod 10 pair
        // well with typical item sizes (items are multiples of 10 in classic streams).
        let m = pr % 10;
        if m == 0 {
            score -= 15.0; // clean class, likely to be filled exactly later
        } else if m >= 5 {
            score += 5.0; // awkward class
        }

        // Integer-division thresholds on post_residual.
        let q = pr / 25; // quarter-capacity classes
        score += q as f64 * 12.0; // prefer bins whose leftover is under a quarter
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
            // reward if next item leaves a further small remainder
            let npr = post_residual - next_item_size;
            if npr <= 10 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin; relax late in the stream.
        score = 300.0 - 150.0 * progress;
        // If the current item is large, a fresh bin is safer.
        if item_size >= 60 {
            score -= 60.0;
        }
        // If no open bin fits well (all residuals far from item), new bin wins.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 80.0;
        }
        // Lookahead: fresh bin accommodates a big next item.
        if next_item_size >= 50 && item_size + next_item_size > bin_capacity {
            score -= 50.0;
        }
    }

    // Mild pressure: spreading load over many open bins is bad; prefer
    // filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates from the mean in a useful way
    // (tighter than average bins get priority).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A post_residual below the minimum item size (1..100 range, min observed ~10)
    // is "dead space" — waste it only if unavoidable.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over opening new ones; penalize new-bin candidate (residual == capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * open_bins_count as f64 + 10.0 * progress;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits, but leaves further residual: mild reward scaled by tightness
        let tight = 1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64;
        score -= 10.0 * tight;
    }

    // Prefer bins tighter than average (below-mean residual = good candidate).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too: mild reward proportional to leftover after that
            let two_step_waste = post_residual - next_item_size;
            score -= 100.0 - (two_step_waste as f64).min(100.0);
        } else {
            // dead space relative to next item: penalize unusable gap
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Penalize tiny unusable residuals (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer tight bins relative to mean residual (best-fit flavor).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bins are tight or item huge.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 150.0 - 300.0 * (1.0 - pressure);
        if item_size > 60 {
            score -= 100.0;
        }
    }

    // Early stream: slight preference to open bins and build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 20.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: residuals too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; mild penalty scaled by how close it was.
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.3 * gap;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // good fitting alternatives exist or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 * 2.0;
        let fit_pressure = if fitting_bins_count > 0 { 20.0 } else { 0.0 };
        score += 35.0 + open_pressure + fit_pressure + 20.0 * progress;
        // But if the item is huge and mean residual is low, a new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Discourage placements that leave residual far from mean (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for using emptier bins early (balance residuals).
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr;

    // Smooth non-linear coupling of post residual with stream progress.
    // Early stream: prefer tight fits (penalize large post residual quadratically).
    // Late stream: prefer filling bins aggressively (reward small post residual more).
    let tightness = 1.0 - x;
    score += 30.0 * (1.0 - progress) * (x * x) * (1.0 - x);
    score -= 20.0 * progress * tightness * tightness;

    // Penalize post residual that cannot fit the next item (smooth sigmoid-like gate).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let gate = 1.0 / (1.0 + (-gap / 15.0).exp());
        score -= 25.0 * gate * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only one fitting bin, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mild penalty unless residuals across open bins are large.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress) - mean_residual * 0.2;
    }

    // Coupling with mean residual: avoid bins far from the fleet mean early on.
    score += 0.1 * (mean_residual - pr).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "coarse" classes (multiples of 10) tend to host future items better.
    let class = post_residual % 10;
    score += class as f64 * 0.8; // ragged leftovers are penalized

    // Big leftover chunks (>= 50) are valuable; reward keeping them.
    if post_residual >= bin_capacity / 2 {
        score -= 6.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 2.0;
    } else if post_residual > 0 {
        score += 4.0; // tiny dead space penalty
    }

    // Perfect-ish fits: post_residual divisible by 4 or 5 keeps classes reusable.
    if post_residual % 4 == 0 { score -= 1.5; }
    if post_residual % 5 == 0 { score -= 1.5; }

    // Lookahead coupling: does the next item fit into the resulting space?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item leaves another class-0-ish remainder
            if (post_residual - next_item_size) % 10 == 0 { score -= 5.0; }
            else { score -= 2.0; }
        } else {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the current item is large relative to capacity and few bins fit it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 > bin_capacity as f64 * 0.6;
        if large_item || fitting_bins_count <= 1 {
            score -= 4.0 + 3.0 * progress;
        } else {
            score += 10.0; // prefer existing bins for small/medium items
        }
    }

    // Mild pressure toward consolidating into bins below mean residual
    // (tighter bins first keeps loose bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    // Integer-division threshold: items larger than half capacity pair best
    // with bins whose residual is in [item, 2*item).
    if item_size > bin_capacity / 2 {
        if bin_residual < item_size * 2 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste. Penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual <= 20 {
        // Small gap zone: mildly risky, may become dead space later.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    } else {
        // Comfortable residual: reward proportionally.
        score -= 8.0 * ((post_residual as f64 - 20.0) / (bin_capacity as f64 - 20.0));
    }

    // Tight fit bonus: the smaller the post_residual relative to the item,
    // the better the packing density.
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a decent fit, or when all fits would create dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bins count.
        score += 45.0 + 2.5 * open_bins_count as f64;
        // But if mean residual across open bins is too small to fit the item,
        // opening a new bin is justified: reduce the penalty.
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
        // If the next item is large and mean residual can't hold it either,
        // a fresh bin gives flexibility.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Late in the stream: prefer tighter packing to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small waste -> graded reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Next item cannot use leftover: penalize dead space more strongly.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0;
    }

    // Reward tight fits (small post residual is generally good).
    if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter",
    // prefer filling them; bins above mean have more room, slight penalty.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, consolidate: prefer existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when other bins fit.
        score += 60.0 + 80.0 * progress;
    } else {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fills: the fuller the bin becomes relative to capacity, the better.
    score -= 14.0 * (1.0 - post / cap) * (item / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin,
    // unless it would create a large dead zone.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        if post > 20.0 {
            score += 0.25 * (post - 20.0);
        }
    }

    // Lookahead: penalize placements that strand residual space too large to be
    // useful for the next item, but reward when residual is near-zero (dead space minimal).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            score += 0.35 * (nxt - post);
        } else if nxt <= post && post > 0.0 {
            // next item could fit here later only if we skip; slight bonus for compatible residual
            score -= 2.0 * (1.0 - (post - nxt).abs() / cap);
        }
    }

    // Time horizon: early in the stream be more conservative about fragmenting space;
    // late in the stream, just pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 3.0;

    // Mild penalty for proliferating open bins (encourage consolidation).
    score += 0.06 * open_bins_count as f64;

    // If average residual across bins is high, prefer reusing existing bins.
    score += 0.10 * mean_residual;

    // New-bin candidate: apply a premium so it is chosen only when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 26.0 + 0.15 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = x * x; // quadratic dead-space penalty

    // Smooth non-linear coupling: dead space hurts more as stream progresses
    score += 0.6 * x * x * (progress * progress);

    // Cubic interaction: mid-range residuals slightly favored early, penalized late
    score += 0.3 * x * (1.0 - x) * (1.0 - 2.0 * progress);

    // Mean residual deviation coupling
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev * (1.0 + progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 0.35 * fits * (1.0 - (nx - x).abs());
        // penalize leaving residual just below next item size (near-miss dead space)
        let gap = (pr - next_item_size as f64) / cap;
        if gap < 0.0 && gap > -0.2 {
            score += 0.4 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Mild pressure against hoarding many open bins late in stream
    score += 0.02 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 measure "wasted" space
    // since item sizes are multiples of 10 in the classic regime; penalize
    // residues that are unlikely to be filled by future items.
    let residue = post_residual % 10;
    score += (residue as f64) * 0.75;

    // Harmonic quarter classes of the capacity fraction: bins whose residual
    // falls in "nice" fractions of capacity are more reusable.
    let frac = post_residual as f64 / bin_capacity as f64;
    let quarter = (frac * 4.0).floor() as i32;
    score += match quarter {
        0 => -6.0,   // nearly full bin: excellent, almost no waste
        1 => -2.0,   // <= 25% free: still good
        2 => 1.0,    // half free: neutral
        3 => 3.0,    // 50-75% free: mediocre
        _ => 0.0,
    };

    // Integer-division threshold: does the next item fit exactly into the
    // post-residual? Perfect chaining reward (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward tight fits scaled by how close next item fills the bin
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * tightness;
        } else {
            // next item cannot follow into this bin: mild penalty proportional
            // to leftover size modulo the next item's harmonic class
            let dead = post_residual % next_item_size.max(1);
            score += (dead as f64) * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist, unless
    // the item is large relative to residual (poor fit case handled above).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of consuming fresh capacity
        score += 8.0;
        // but if many open bins are nearly full (low mean residual), a new
        // bin is fine; discount the penalty.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
        // early in the stream, opening bins is cheaper (future items unknown)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Prefer bins whose residual is below the mean (consolidating waste).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= (diff / bin_capacity as f64) * 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical items are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small gap: penalize more if no known next item can use it.
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 12.0;
        } else {
            score += 4.0;
        }
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: favor bins whose post_residual accommodates the next item.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit creates severe dead space).
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual < 10 && post_residual > 0 {
            score += 10.0; // dampen reward if it creates dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);
    score += pressure;

    // New-bin candidate: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.15;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: opening new bin is required
        }
        if next_item_size > 0 && (next_item_size as u32) >= bin_capacity - item_size {
            score -= 5.0; // new bin can serve the next item too
        }
    }

    // Mild bonus for keeping residual near the mean (balanced bin loads).
    score -= (post_residual as f64 - mean_residual).abs() * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer bins that end up tightly packed.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2-step lookahead: reward if the NEXT item fits exactly / well into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match is ideal: subtract a big bonus.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize leaving awkward space.
            score += 8.0;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 5.0;
    }

    // Penalize dead space relative to mean residual (avoid stranding large residuals).
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && next_item_size > 0 && post_residual < next_item_size;
        if poor_fit {
            score -= 12.0; // opening fresh bin is better than creating dead space
        } else {
            score += 20.0; // otherwise discourage wasting a fresh bin
        }
    }

    // Slight preference for consolidating when many bins are open.
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already rewarded by base).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving awkward residual.
            score += 3.0;
        }
    }

    // New-bin candidate logic: empty bin gets a mild penalty so we prefer
    // filling existing bins, unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * open_bins_count as f64;
        // If mean residual is large, existing bins have room: discourage new bin more.
        score += 0.05 * mean_residual;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;
    if progress > 0.8 && fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with residual below mean (denser bins) to consolidate.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening bins when many are open (encourage packing).
    if bin_residual == bin_capacity && open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (small post_residual) strongly.
    // Late stream: relax slightly, weight dead space super-linearly.
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * (1.0 - progress);
    score += 20.0 * poly;

    // Perfect-fit reward, amplified as stream progresses.
    if post_residual == 0 {
        score -= 30.0 + 20.0 * progress;
    } else if post_residual < 10 {
        score -= 10.0 * (1.0 - norm_post) * (1.0 + progress);
    }

    // Penalize unusable dead space: post_residual smaller than any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation).
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * norm_post * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-high unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity-fraction bands.
    let quarter = bin_capacity / 4;          // 25
    let eighth = bin_capacity / 8;           // 12
    let pr = post_residual;

    // Class 0: dead space (post_residual < eighth) -> heavily penalize
    if pr < eighth {
        score += 30.0;
    } else if pr < quarter {
        // Class 1: small leftover, mildly penalize unless perfectly tight
        score += 6.0;
    } else if pr < 2 * quarter {
        // Class 2: half-ish leftover, neutral to good
        score -= 4.0;
    } else {
        // Class 3: large leftover, good bin choice
        score -= 8.0;
    }

    // Perfect fit bonus: post_residual is an exact multiple of eighth
    if pr % eighth == 0 && pr > 0 {
        score -= 5.0;
    }
    // Exact fill is ideal
    if pr == 0 {
        score -= 20.0;
    }

    // Modulo coupling with next item: reward residuals that can host
    // the lookahead item, especially when they match its harmonic class.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 3.0;
            // bonus if leftover after lookahead item falls in a good class
            let pr2 = pr - next_item_size;
            if pr2 % quarter == 0 {
                score -= 4.0;
            }
            if pr2 < eighth && pr2 > 0 {
                score += 4.0; // lookahead would create dead space
            }
        } else {
            // next item cannot fit here; penalize if this bin is the
            // only fitting one (last-chance bin)
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin before opening a new one: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    // (large item relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.2;
        let early = (step_index as f64) / (total_items.max(1) as f64) < 0.15;
        if tight || early {
            score -= 10.0;
        } else {
            score += 15.0;
        }
    }

    // Prefer reusing bins when many are open (reduce bin proliferation)
    score += (open_bins_count as f64) * 0.15;

    // Mild progress coupling: later in the stream, be more conservative
    // about leaving awkward mid-range leftovers.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if pr >= eighth && pr < quarter {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are worthless gaps.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual <= 5 {
        // Tiny gap: almost as bad as wasted space; heavily penalize.
        score += 45.0;
    } else if post_residual <= 15 {
        score += 20.0;
    } else if post_residual >= next_item_size as f64 && next_item_size > 0 {
        // Gap can host the lookahead item: mild reward.
        score -= 8.0;
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 0 && post_residual < 5 {
            score += 30.0; // but not if it creates a dead gap
        }
    }

    // New-bin candidate: make empty bins moderately unattractive so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * open_bins_count as f64;
        // If the item nearly fills a fresh bin, opening is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Tightness reward: the fuller the bin becomes, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this leftover: penalize dead space, more so if tiny
        if post_residual > 0 {
            score += (1.0 - post_residual as f64 / 20.0).max(0.0) * 40.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when no decent fit exists
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0
            && (next_item_size == 0 || next_item_size > post_residual)
            && post_residual < item_size as f64;
        if poor_fit {
            // opening a new bin is better than wasting a nearly-full bin
            score -= 150.0;
        } else {
            // discourage opening new bins when open bins fit reasonably
            score += 250.0;
            if fitting_bins_count > 0 {
                score += 100.0;
            }
        }
    }

    // Slight progression bias: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly.
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here: mild penalty for wasting space next item can't use.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Global state: with many open bins and high mean residual, prefer consolidating into bins with above-average residual.
    let res_gap = bin_residual as f64 - mean_residual;
    score += 0.08 * res_gap * (1.0 + open_bins_count as f64 / 20.0);

    // Time horizon: early in stream, be conservative (favor new bins for big items to keep flexibility);
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * fit_ratio;
    score += (1.0 - progress) * 4.0 * (bin_residual == bin_capacity) as i32 as f64 * -1.0;

    // New-bin candidate: prefer it when item is large and few bins fit it, penalize otherwise.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - item_frac);
        if fitting_bins_count > 3 {
            score += 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big items coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap; // 0 = perfect fit

    // Core: quadratic penalty on wasted space (favor tight fits strongly)
    let mut score = pr * (1.0 + fit_ratio * fit_ratio * 3.0);

    // Cubic coupling with stream progress: waste matters more later in the stream
    let late = progress * progress * progress;
    score += fit_ratio * fit_ratio * cap * late * 2.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 0.75;
    } else if fitting_bins_count > 2 {
        // many alternatives: be pickier about slack
        score += pr * 0.15 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits into the post-residual, reward leaving that space
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + 0.1 * pr;
    } else if next_item_size > 0 {
        // next item won't fit here: slight penalty proportional to stranded slack
        score += fit_ratio * 4.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, opening is cheap
    let openness = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += openness * fit_ratio * 2.0;

    // Mean-residual coupling: if this bin is drier than average, prefer filling it
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.05;

    // New-bin candidate handling: fresh bin has residual == capacity (fit_ratio == 1)
    if bin_residual == bin_capacity {
        // attractive early when item is large; penalized later to consolidate
        let item_frac = item_size as f64 / cap;
        score = cap * (0.35 + 0.65 * (1.0 - item_frac)) + late * cap * 0.5;
        if fitting_bins_count <= 1 && fitting_bins_count >= 1 {
            // some bin fits but it's the only one: still allow new bin only if fit is awful
            score += 0.0;
        }
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, must open
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 8.0; // room for lookahead in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fractions (integer division)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = post_residual / (bin_capacity / 4); // quarter classes: 0..4
    let next = next_item_size as f64;

    // Reward post_residual classes that are "harmonically useful"
    match class {
        0 => score -= 8.0,          // near-perfect fit
        1 => score -= 2.0,          // quarter left: many items (1..25) fit
        2 => score -= 3.0,          // half left: very reusable
        3 => score -= 1.0,          // three quarters left
        _ => {}                      // empty-ish, neutral
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = next_item_size / (bin_capacity / 4);
        score -= 4.0 + next_class as f64;
        // Exact harmonic match: post_residual is a multiple of next_item_size
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize dead space proportional to gap
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bonus: only this bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin attractive only if current bin would leave awkward residue
        let awkward = post_residual > 0 && post_residual < 10.0 && post > 0.0;
        if awkward {
            score -= 5.0; // prefer fresh bin over tiny dead space? no: penalize
        }
        // baseline: new bin costs one bin; make it slightly unattractive
        score += 6.0;
        // but if mean residual across open bins is tiny, new bin is fine
        if mean_residual < 8.0 {
            score -= 10.0;
        }
    }

    // Stream progression: later in stream, waste matters more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.05 * progress;

    // Modulo harmonic penalty: residues coprime-ish to common item sizes are dead
    let gcd_like = |a: u32, b: u32| -> u32 { if b == 0 { a } else { gcd_like(b, a % b) } };
    if post_residual > 0 {
        let g = gcd_like(post_residual, bin_capacity);
        if g <= 2 { score += 2.0; } else { score -= g as f64 * 0.3; }
    }

    // Tie-break: prefer fuller bins (smaller residual before placement)
    score += (bin_capacity - bin_residual) as f64 * (-0.02);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // item (size ~10) are unusable; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the lookahead item is also bad.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Sweet spot: post_residual exactly matching next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose" fits;
    // prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score -= 0.2 * mean_residual;

    // New-bin candidate: keep it attractive only when no open bin fits well,
    // i.e. when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins get worse (more attractive) as stream progresses if residuals are low.
        score = bin_capacity as f64 - 0.4 * mean_residual - 20.0 * progress;
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty dominates.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits
    // the post-residual (chain packing), scaled by how snugly it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 60.0 - 0.5 * slack_after_next as f64;
        if slack_after_next == 0 {
            score -= 150.0; // perfect two-item chain
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving a small unusable gap
        // that no typical item could use.
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Relative-to-mean coupling: bins with above-average residual are
    // better candidates for absorbing this item.
    score -= 0.8 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * post_residual as f64;
    }

    // New-bin candidate handling: make empty bins attractive only when the
    // item is large relative to capacity or fits are poor elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty: prefer reusing open bins in general.
        score += 45.0;
        // Large items are worth a fresh bin (avoids fragmentation).
        if fill_ratio > 0.6 {
            score -= 55.0 * fill_ratio;
        }
        // Late in the stream, opening bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // Many open bins with high mean residual: reuse is easy, penalize new bin.
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space, especially small post-residuals that can never be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual, reward it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size <= bin_residual {
            // Next item would have fit now but won't after placement: penalize.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Time horizon: early in the stream, prefer consolidating into few bins
    // (penalize opening new bins); late, be more tolerant of new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, less later.
        score += 20.0 * (1.0 - 0.7 * progress);
        // Opening a new bin is attractive if open bins are already tight on average.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins more when few bins are open.
        score -= 5.0 / (1.0 + open_bins_count as f64 * 0.1);
    }

    // Mild preference for bins below the mean residual (balance utilization).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1)
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: penalize wasted post residual, with a smooth non-linear (quartic) shaping
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Polynomial coupling of post residual with stream progress:
    // later in the stream, tight fills matter more; early on, be lenient.
    let progress_coupling = 1.0 + 2.0 * progress * progress * (1.0 - progress);
    score *= progress_coupling;

    // Smooth interaction: reward small post residual more strongly as progress grows
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits the post residual, reward this bin smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score -= (1.0 - gap_norm) * (1.0 - gap_norm) * 4.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open and residual is far from mean (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 2.0 * (0.5 + 0.5 * progress);

    // Penalize opening a new bin when open bins exist and could fit (encourage packing)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 8.0 * progress + 5.0 * fit;
    }

    // Slight preference for bins with larger fill already (smaller residual) — smooth term
    score += (1.0 - bin_residual as f64 / cap) * -1.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small residues are "dead space" classes.
    // Class 0: residue <= 10 (unusable for any item) -> strong penalty.
    // Class 1: residue 11..=20 (fits only tiny items) -> penalty unless next item fits.
    if post_residual <= 10 {
        score += 30.0;
    } else if post_residual <= 20 {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // lookahead rescues this class
        }
    }

    // Perfect / near-perfect fits get harmonic rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modulo-class coupling: residue congruent to 0 mod 25 tends to host
    // common item sizes (multiples of 25 / half-capacity chunks) later.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division thresholds: how many "small items" (<=20) still fit.
    let small_slots = post_residual / 20;
    if small_slots >= 2 {
        score -= 6.0 * small_slots as f64;
    }

    // Next-item harmonic compatibility: reward if next item exactly divides residue class.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 14.0; // next item creates near-perfect fit
        } else {
            score += gap as f64 * 0.25; // penalize leaving a bad class for next step
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // New-bin candidate: only attractive when open bins are nearly all full
    // (mean residual small) or this item fits nowhere well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 15.0; // no open bin even fits well
        } else if mean_residual < 25.0 {
            score -= 5.0; // open bins are crowded; fresh bin fine
        } else {
            score += 25.0; // plenty of usable space elsewhere: avoid new bin
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins when mean residual is large.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: discourage opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Dead space in a fresh bin is just the residual; make it competitive only
        // when the alternative leaves a very poor gap.
        score += 30.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // gap unlikely to be usable by the next item
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps the bin pool homogeneous and gap-friendly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post-residual can still host the next item: partial reward scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards: penalize dead space creation.
        score += 15.0;
    }

    // Reward tight fits relative to capacity (small post_residual is good).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from the mean residual (fragmentation signal).
    score += 0.5 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for opening new bins when many bins are already open and fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Allow new bin early in the stream to build a diverse residual pool.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more aggressively.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight_fit * tight_fit;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0 * (1.0 - post_residual as f64 / 80.0);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer new bins over bad fits);
    // late in the stream, squeeze existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * tight_fit;

    // Global state: many open bins with slack -> prefer filling them.
    let mean_resid_norm = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score += 10.0 * mean_resid_norm; // penalize when this bin is above-average slack? invert below
        score -= (bin_residual as f64 / bin_capacity as f64) * 10.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin should only win when fit is poor
    // and there is plenty of time left; otherwise bias it against.
    if bin_residual == bin_capacity {
        let poor_fit = tight_fit < 0.35;
        if poor_fit && progress < 0.8 {
            score -= 20.0 * (1.0 - tight_fit);
        } else {
            score += 35.0;
        }
    }

    // Small bonus for preferring bins with smaller residual overall (best-fit flavor).
    score += 0.15 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_term = progress * progress;
    score += 12.0 * prog_term * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (low post_residual) more strongly later in the stream
    score -= (1.0 - progress) * (pr / cap) * 8.0;

    // Penalize dead space quadratically when residual becomes unusable
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 6.0 * ((nx - pr) / cap) * ((nx - pr) / cap) * 100.0;
        } else {
            // Smooth reward when next item fits this bin's post-residual
            score -= 5.0 * (1.0 - (nx / cap)) * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty proportional to post residual relative to mean residual
    if mean_residual > 0.0 {
        score += 2.0 * (norm_pr * cap - mean_residual) / cap;
    }

    // Smooth new-bin preference when current bin leaves a large awkward gap
    score += 3.0 * norm_pr * norm_pr * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 buckets.
    // Small post_residual = tight fit = good; but residual < 10 is dead space.
    let r = post_residual;
    if r > 0 && r < 10 {
        // Unusable dead space: strong penalty.
        score += 25.0;
    } else if r == 0 {
        // Perfect closure: big reward.
        score -= 60.0;
    } else {
        // Harmonic class: residuals that are multiples of 5 or 10 are more reusable
        // since item sizes 1..=100 include many sizes matching those classes.
        let cls = r % 10;
        if cls == 0 {
            score -= 12.0;
        } else if cls == 5 {
            score -= 7.0;
        } else if cls <= 2 || cls >= 8 {
            score += 5.0; // awkward class
        }
    }

    // Last chance bin: only this bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 50.0;
        } else if next_item_size < r {
            let slack = r - next_item_size;
            if slack <= 10 {
                score -= 15.0;
            } else {
                score += slack as f64 * 0.15;
            }
        } else {
            // next item cannot fit here; a very small residual wastes the lookahead.
            if r < next_item_size && r > 0 {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = 45.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
        return score;
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 20.0;

    // Late-stream pressure: fewer open bins relative to progress favors consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;
    score += open_bins_count as f64 * 0.3;

    // Mean residual coupling: placing into a bin far below mean residual is wasteful.
    if (bin_residual as f64) > mean_residual + 30.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the
    // smallest future item (size 1..100 unknown, but small gaps < 20 are
    // nearly unusable) get a heavy penalty.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the lookahead item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit: this creates dead space relative to lookahead.
        score += 10.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are already small; encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Encourage placing into bins with below-average residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutral-ish baseline; only attractive when no
    // decent open bin exists. Penalize mildly so existing bins are preferred
    // unless dead-space penalties dominate.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (superlinear dead-space penalty).
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    if fit_ratio > 0.9 {
        score -= 30.0 * (fit_ratio - 0.9);
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item exactly fills the post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it fills
            let next_fill = (next_item_size as f64) / (post_residual as f64);
            score -= 15.0 * next_fill;
        } else {
            // next item cannot fit here: penalize small dead space that blocks the future item
            let waste = (post_residual as f64) / (next_item_size as f64);
            if waste < 1.0 {
                score += 10.0 * (1.0 - waste);
            }
        }
    }

    // Compare against mean residual: prefer bins below-average residual (tighter bins),
    // keep loose bins available for large future items.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no good fit exists (keep new-bin option only for poor fits).
    if bin_residual == bin_capacity {
        score += 25.0;
        // Allow new bin when item is huge relative to capacity and fit is bad.
        if fit_ratio < 0.5 {
            score -= 30.0;
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for keeping number of open bins stable.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small to likely fit anything
    if post_residual < 10 {
        score -= 5.0; // fully-closed-like bin is fine
    } else if post_residual < 20 {
        score += 12.0; // awkward dead zone
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is large and would need this residual
    if next_item_size > post_residual && next_item_size > 50 {
        score += 8.0;
    }

    // Time horizon: early in stream, prefer consolidating into fewer bins;
    // late in stream, prefer tight packing regardless
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (mean_residual / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening new
    let open_pressure = open_bins_count as f64;
    if bin_residual < bin_capacity {
        score -= 0.8 * open_pressure;
    } else {
        // new bin candidate: penalize mildly, more when open bins exist
        score += 2.0 + 1.5 * open_pressure;
        // but if mean residual is large and item is big, new bin may be better
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth progress coupling: late in stream, penalize wasted space more strongly
    score += 12.0 * progress * (x * (1.0 - x)) * cap * 0.2;

    // Reward tight fits smoothly (quadratic in item/capacity)
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    // Last chance bin: strong smooth reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x);
    }

    // New bin candidate: penalize mildly unless current bin would leave awkward residue
    if bin_residual == bin_capacity {
        let awkward = ((pr as i64 - 20) as f64).abs() / cap;
        score += 15.0 - 20.0 * awkward * (0.5 + progress);
    }

    // Next item lookahead: smooth bonus if next item fits post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 8.0 * (1.0 - (nx / cap));
        } else {
            score += 5.0 * ((nx - pr as f64) / cap);
        }
    }

    // Mean residual dispersion coupling
    score += 0.3 * (mean_residual - pr as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes mod 10 and mod 25
    let r10 = post_residual % 10;
    let r25 = post_residual % 25;

    // Penalize dead space in awkward residue classes (hard to fill later)
    if r10 != 0 {
        score += (10 - r10) as f64 * 0.8;
    }
    if r25 == 0 {
        score -= 6.0; // clean quarter-capacity residual is reusable
    }

    // Reward tight fits: post_residual small relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Harmonic coupling with next item: can next item fit exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect follow-up fill
        } else if next_item_size <= post_residual {
            // fraction of next item absorbed; reward high absorption
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * frac;
            // bonus if post_residual is an integer multiple class of next size
            if post_residual % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot fit here; penalize more if residual is large dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; discourage unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        score = 55.0 - 0.3 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    // Stream progression: later in stream, prefer consolidating (favor existing bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Prefer bins below mean residual (balance load, keep big residuals together)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can realistically use are heavily penalized.
    let dead = if post_residual == 0 {
        0.0 // perfect fit: no dead space at all
    } else if post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 6.0 // tiny unusable gap
    } else if post_residual < 20 {
        18.0 // marginal gap, mostly wasted
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits (small useful residual) mildly.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0; // gap can't serve next item either
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into existing
    // bins rather than opening new ones.
    score += open_bins_count as f64 * 0.5;

    // Mean-residual coupling: when average residual is small, existing bins are
    // nearly full — a new bin becomes relatively more attractive for large items.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near mean residual so it only wins when
        // existing fits are poor (large dead space).
        score = post_residual as f64 + mean_residual * 0.3 + open_bins_count as f64 * 0.3;
        if item_size >= 60 {
            score -= 10.0; // big items are hard to place later; open fresh bins
        }
    } else if mean_residual < 8.0 && post_residual > 20 {
        score += 6.0; // avoid wasting one of the few remaining roomy bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let match_val = post_residual as f64 - next_item_size as f64;
        if match_val == 0.0 {
            // Perfect two-item completion: heavily reward.
            score -= 60.0;
        } else if next_item_size as u32 <= post_residual {
            // Next item still fits in this bin afterwards: reward proportionally
            // to how snugly it fits (small leftover after both placements).
            let after_two = post_residual - next_item_size;
            score -= 40.0 - (after_two as f64) * 0.8;
        } else {
            // Next item cannot use the residual: penalize large dead space
            // relative to next item size.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Penalize leaving tiny unusable fragments (dead space < 10 is hard to fill).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // gently scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - bin_residual as f64) * (0.1 + 0.15 * progress);

    // Late in the stream, avoid opening new bins: penalize the empty-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that is
    // too small to ever be useful is doubly bad.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly
    // favor this bin; if next item cannot fit post_residual, mild penalty
    // unless post_residual is already dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Last chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large or fits poorly everywhere. Make the empty bin expensive
    // by default, discounted when the item is big relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 60.0 * frac;
        // If existing bins are nearly full on average, new bin is cheaper.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Prefer filling bins with larger residuals when many bins are open
    // (consolidation pressure grows with open_bins_count).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0) * 2.0;

    // Late in the stream, avoid opening new bins even more (tail effect).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early on, prefer tight fills (small post_residual); later, tolerate larger residuals
    let progress_weight = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += progress_weight * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize large dead space quadratically relative to capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 10.0;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    score -= 20.0 * (-post_residual as f64 / 5.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // mild penalty when many bins compete, scaled by openness
        score += (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 8.0 * fit_quality;
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host next item, smoothly
        score += 4.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Coupling with mean residual: prefer bins whose residual deviates smoothly from mean
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a smooth progress-dependent penalty
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 12.0 + 10.0 * openness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that fall into "dead" classes: too small for typical items (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward residuals that are harmonic multiples likely to be exactly filled later
    let harmonic_bonus = match post_residual {
        0 => 80.0,                 // perfect fit
        r if r % 10 == 0 => 25.0,  // decile-aligned residual
        r if r % 25 == 0 => 20.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size <= post_residual {
            let nxt_frac = next_item_size as f64 / post_residual as f64;
            // reward high fill ratio of the next item into this residual
            score -= 30.0 * nxt_frac;
            // penalize leaving awkward gap after next placement
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 10 {
                score += 20.0;
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by leftover
            score += 5.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when existing residuals are poor
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual / bin_capacity as f64;
        score = 45.0 + 40.0 * avg_dead;
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size + item_size <= bin_capacity {
            score -= 30.0; // room for lookahead pair
        }
    }

    // Progress-based tie-breaking: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * frac;

    // Mild penalty proportional to deviation from mean residual (avoid fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 unknown,
    // assume ~10 as conservative floor for typical streams).
    let dead_threshold = 9.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= dead_threshold {
        score += (dead_threshold - pr + 1.0) * 25.0; // gap of 1..9 is nearly worthless
    } else if pr > dead_threshold && pr < 20.0 {
        score += (20.0 - pr) * 3.0; // mildly discourage marginal gaps
    }

    // Perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (item fills most of the bin) rewarded proportionally.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and penalize opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: empty bin gets a baseline handicap so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if current bin would be the only fitting bin and the fit is poor,
        // opening a new bin may be better; reduce handicap slightly when next item
        // is large and would combine well with a fresh bin.
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Early in the stream, allow more bins to spread items; later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 - progress * 5.0;

    // Prefer bins with residuals close to the item (minimal waste) relative to mean.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual closely matches next_item_size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);
        // Perfect chain: post_residual exactly fits next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Penalize leaving tiny unusable dead space (below minimum item size 1..=10 -> use 10 as heuristic floor)
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Last-chance bonus: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.3;
    } else {
        // Reward tight fits relative to mean residual of open bins
        let tightness = (bin_residual as f64 - post_residual as f64) / bin_residual.max(1) as f64;
        score -= 20.0 * tightness;
        // Penalize bins with residual far above mean (fragmentation hoarding)
        if post_residual as f64 > mean_residual * 1.5 {
            score += (post_residual as f64 - mean_residual * 1.5) * 0.4;
        }
    }

    // Early stream: be more conservative about opening new bins (favor reuse)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress / 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Strong reward for near-perfect fits (post_residual small relative to item).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if next item can exactly fill post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial credit proportional to how well next item uses leftover
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover too small for next item: penalize dead space
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 8.0 * (10.0 - dead);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when it is
    // genuinely attractive (large residual capacity for future items) and the
    // current fit is poor.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral-ish, slightly penalized so tight
        // existing fits win, but competitive with bad fits.
        score += 35.0;
        // as stream progresses, opening bins becomes slightly less attractive
        // (consolidation phase); early on, keep it cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // many open bins with slack: discourage opening yet another
        score += 2.0 * (open_bins_count as f64).sqrt();
        // if mean residual across open bins is large, new bin less needed
        score += 0.3 * mean_residual;
        // if next item is large and existing fit is poor, new bin more attractive
        if next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Penalize leaving residuals that are awkward (e.g., in 60..70 zone where
    // only small items fit): mild shaping around typical dead zones.
    let pr = post_residual as f64;
    if pr > 50.0 && pr < 60.0 {
        score += 5.0;
    }

    // Global state: when many bins are open relative to items seen, prefer
    // consolidating into existing bins.
    let avg_load = open_bins_count.max(1);
    let _ = avg_load;
    if open_bins_count as f64 > (step_index as f64 * 0.5).max(1.0) {
        score += 6.0;
    }

    // Mild preference for bins whose residual is close to mean residual
    // (keeps bin sizes homogeneous, easier future packing).
    score += 0.05 * (residual - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual), non-linearly.
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * cap * (1.0 + 0.5 * progress);

    // Smooth interaction: post_residual^2 scaled by item size (large items deserve tight fits more).
    score += 0.02 * (pr * pr) / (item + 10.0);

    // Penalize leaving residual that no plausible next item fits well:
    // gap between post_residual and next item size, smoothly weighted by progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.05 * gap * (0.5 + progress);
        // Reward if next item fits exactly-ish in this bin.
        let fit_quality = (nx / (pr + 1.0)).min(1.0);
        score -= 8.0 * fit_quality * fit_quality;
    }

    // Last-chance bonus: if only this bin fits, strongly discourage opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly, more so late in stream when consolidation matters.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 12.0 + 10.0 * progress + 0.05 * mean_residual;
    } else {
        // Reward using existing bins, scaled by how many bins are open (fragmentation pressure).
        score -= 2.0 + 0.3 * open_bins_count as f64;
    }

    // Mean-residual coupling: if mean residual is small, keep bins tight (discourage waste).
    score += 0.1 * (mean_residual / cap) * pr;

    // Mild smooth progress tilt toward consolidating into fewest bins.
    score += 3.0 * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo buckets of 10 (capacity fractions).
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty: residuals in awkward classes (1..9 mod 10) are harder to fill.
    if class != 0 && pr > 0 {
        score += (10 - class) as f64 * 0.8;
        // Harmonic resonance: exact quarter/half/three-quarter residuals are prime targets.
        if pr == bin_capacity / 4 || pr == bin_capacity / 2 || pr == (bin_capacity * 3) / 4 {
            score -= 15.0;
        }
    }
    // Zero residual is perfect closure.
    if pr == 0 {
        score -= 40.0;
    }

    // Next-item harmonic compatibility: does next_item_size divide the post_residual class?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            // Next item fits exactly leaving another harmonic class boundary.
            if (pr - next_item_size) % 10 == 0 {
                score -= 12.0;
            }
            // Next item fills post_residual exactly -> chain closure.
            if next_item_size == pr {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to waste.
            score += (next_item_size - pr).min(30) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals across open bins are tight
    // (mean residual small) or item is large relative to capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / bin_capacity as f64) < 0.15;
        if tight && next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // fresh bin for a big follower
        }
        // Late in stream, prefer consolidating: penalize new bins mildly.
        score += progress * 10.0;
        // Base new-bin penalty so it only wins when open bins are truly bad fits.
        score += 8.0;
    }

    // Integer-division threshold: bins whose residual floor(pr/10) is small are nearly full.
    score += (pr / 10) as f64 * 0.3;

    // Slight preference for bins below mean residual (balance load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0_f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // creating a tiny useless gap is very bad
    } else if (post_residual as f64) < 20.0 {
        score += 25.0; // risky small gap
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness;
    }

    // Penalize leaving a gap that exactly blocks the lookahead item barely
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0.0 && pr < n {
            score += 12.0; // gap cannot host next item: fragmented
        } else if pr >= n {
            score -= 10.0 * (n / 100.0); // keeps lookahead feasible
        }
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate more when open_bins_count is high).
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // moderately attractive only when few bins are open or fit is poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Mean residual coupling: if average residual across bins is small,
    // existing bins are nearly full, so opening a new bin is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (mean_residual / bin_capacity as f64) < 0.15 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward post_residual that matches next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = (post_residual as f64 - nx).abs();
        score += 0.8 * match_term;
        // Perfect chain fit bonus
        if post_residual as f64 == nx {
            score -= 40.0;
        } else if (post_residual as f64 - nx).abs() <= 5.0 {
            score -= 15.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if (post_residual as f64) < nx && post_residual > 0 {
            score += 0.5 * (nx - post_residual as f64);
        }
    } else {
        // Last item: minimize waste directly
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins with residual above mean (use loose bins first)
    if bin_residual as f64 > mean_residual {
        score -= 0.4 * (bin_residual as f64 - mean_residual);
    } else {
        score += 0.4 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let waste = (bin_capacity - item_size) as f64;
        // Opening a new bin is only attractive if all existing fits are poor
        // and the new bin offers good future flexibility (large post_residual)
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin anyway
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // new bin can chain with next item
        }
        let _ = waste;
    }

    // Slight preference for consolidating into fewer bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space below smallest plausible item (threshold ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
        // If next item exactly fills this bin's post residual, big bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: prefer filling existing bins over opening new ones
    score += open_bins_count as f64 * 0.8;

    // Prefer bins with residual below mean (consolidate large holes)
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 4.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: early in stream, allow new bins; late, squeeze harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    // New-bin candidate: open only when it's a really bad fit elsewhere
    if bin_residual == bin_capacity {
        score += 18.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 15.0; // big item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let res = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual waste, with a convex penalty so small leftovers are heavily discouraged
    let mut score = post + (post / cap).powi(3) * 40.0;

    // Tightness reward: fraction of bin consumed by this placement
    let fill = item / cap;
    score -= fill * 30.0 * (1.0 + 0.5 * progress);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on tolerate leftover space; late in stream demand near-zero leftovers
    let progress_waste_weight = 0.5 + 1.5 * progress * progress;
    score += (post / cap) * 30.0 * progress_waste_weight;

    // Interaction term: post_residual vs mean residual deviation (smooth polynomial)
    let dev = (res - mean_residual) / cap;
    score += 8.0 * dev * dev - 6.0 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving room
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - (nxt / post.max(1.0)).abs() - 0.5).abs() * (1.0 - progress);
        } else {
            // penalize leaving a gap that the next item cannot use
            score += 4.0 * (post / cap) * (1.0 - progress);
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only when fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * (1.0 - progress) - 10.0 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let quarter = bin_capacity / 4;                 // 25 units
    let eighth = bin_capacity / 8;                  // 12 units
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space penalty grows super-linearly for tiny leftovers that few items can use.
    if post_residual < eighth {
        score += 40.0 * (eighth as f64 - post) / eighth as f64;
    } else if post_residual < quarter {
        // sweet spot: leftover in [12,25) is reusable by most items (10..80)
        score -= 12.0;
    } else if post_residual < bin_capacity / 2 {
        score -= 6.0;
    }

    // Modulo-class coupling: leftover divisible by small harmonics pairs well with
    // typical item sizes, giving future exact fits.
    if post_residual % 10 == 0 {
        score -= 8.0;                               // multiple of 10 matches item granularity
    } else if post_residual % 5 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual exactly or well?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;                          // perfect follow-up fit
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 10.0 * (nxt_post as f64 / cap);
            if nxt_post % 10 == 0 { score -= 6.0; }
        } else {
            // next item won't fit here; penalize more if leftover is small (stranded)
            score += 5.0 + 15.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // allow fresh bin early in stream or when open bins are nearly full on average
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < 15.0 && progress > 0.1 {
            score -= 35.0;
        }
    }

    // Mild pressure to consolidate into fuller bins when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if no plausible future item (>= 1, but realistically
    // small items are rare) can exploit it. Penalize residuals below 10 harshly,
    // and residuals in the awkward band [10, 20) moderately.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable dead space below minimum item size.
        score += 30.0;
    } else if post_residual < 20 {
        // Awkward gap: only tiny items fit.
        score += 8.0;
    } else if post_residual < 30 {
        score += 2.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next < 10 {
            // Next item will perfectly seal this bin: big reward.
            score -= 25.0;
        } else {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits in this bin only if we DON'T place the current item here
        // (or fits better elsewhere): slight penalty for consuming the needed space.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across too many bins when few items remain,
    // encourage consolidation early when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    score += open_pressure * 3.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual < 40 {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing),
    // penalize outliers that would become fragmented.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when the current item is large relative to capacity and no
    // good fit exists (post_residual would be huge elsewhere), or when the item
    // would leave a very awkward gap in every open bin.
    if bin_residual == bin_capacity {
        // Baseline: neutral-ish score so good existing fits win.
        score = 45.0;
        if item_size >= 60 {
            // Large items are fine to start a fresh bin.
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            // Pairing large items together in a fresh bin is attractive.
            score -= 10.0;
        }
        // Late in the stream, opening new bins is less costly than dead space.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a perfect match between the
    // leftover space and the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Perfect match (diff == 0) gets a big bonus; decays quickly.
        score -= 45.0 * (-diff / 12.0).exp();
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize wasted lookahead space.
        let shortfall = (next_item_size - post_residual) as f64;
        score += 0.35 * shortfall;
    }

    // Penalize tiny unusable dead space (fragmentation risk), scaled by progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (1.0 - progress);
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average is good (tight packing), leaving more is wasteful.
    let mean_post = mean_residual - item_size as f64;
    score += 0.25 * (post_residual as f64 - mean_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild bias against opening a new bin while several bins are open,
    // unless the fit is perfect (post_residual small).
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * post_residual as f64 - 40.0 * (-(post_residual as f64) / 15.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good, but keep a
    // nonlinear penalty for "awkward" residuals that are too small to be
    // useful yet not zero (dead space between 1 and ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 - (post_residual as f64) * 1.2;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // slack that can host next item is mildly good
            score -= 3.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(2.0);
        } else {
            // post residual too small for next item: penalize proportionally
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: neutral residual = capacity. Make it attractive
    // only when current fit is poor (large post_residual) or mean residual
    // across bins is low (bins are nearly full).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score -= 6.0 * poor_fit;             // slight attraction always
        if post_residual > 25 {
            score -= 10.0;                   // bad fits -> prefer fresh bin
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 8.0;                    // open bins nearly exhausted
        }
        // late in the stream, avoid opening bins with tiny leftover work
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 && post_residual > 60 {
            score += 15.0;
        }
    }

    // Mild global pressure: prefer filling bins with below-average residual
    // (balance-aware packing keeps more usable mid-size bins available).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // Penalize wasting a large bin on a tiny item when many bins are open.
    if item_size < 20 && bin_residual > 80 && open_bins_count > 3 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < f64::EPSILON;

    // Base: prefer small post residual (tight fit), smoothly squashed.
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, mild preference for tight fits; later, stronger.
    let tightness = 1.0 - (post / cap);
    let progress_coupling = tightness * tightness * (0.5 + 2.0 * progress) * cap * 0.5;
    score -= progress_coupling;

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let nx = next_item_size as f64;
        score -= 8.0 * (nx / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        // penalize dead space that can't fit the lookahead, scaled by progress
        let nx = next_item_size as f64;
        let gap = (nx - post).max(0.0);
        score += 2.0 * (gap / cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-worse unless residual
    // of open bins is very fragmented (mean residual high relative to item).
    if is_new_bin {
        let frag = mean_residual / cap;
        // open new bin only when existing bins are fragmented or late in stream
        score += 10.0 - 12.0 * frag * (1.0 + progress);
        // avoid opening new bins when plenty of bins fit the item
        score += 2.0 * fitting_bins_count as f64;
    }

    // Mild penalty for spreading across many bins when residuals are large.
    score += 0.5 * (mean_residual / cap) * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 bands.
    let band = (post_residual * 5) / bin_capacity; // 0..4
    // Penalize dead space in awkward bands (too small for typical items).
    match band {
        0 => score += 40.0,          // nearly full: excellent
        1 => score -= 10.0,          // 20-40% left: usable
        2 => score += 5.0,           // mid: mediocre
        3 => score += 12.0,          // 60-80% left: wasteful
        _ => score += 0.0,           // empty-ish bin: fine
    }

    // Perfect fit reward via modular arithmetic on post_residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual % 10 == 0 {
        score -= 15.0; // residue in harmonic decade class
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely; reward proportionally.
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to lookahead: penalize by gap size class.
            let gap = post_residual.min(next_item_size);
            score += 8.0 + (gap % 7) as f64 * 2.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it attractive only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.3 {
            score -= 18.0; // open bins too full -> prefer new bin
        } else {
            score += 15.0 + open_bins_count as f64 * 1.5; // discourage bin proliferation
        }
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits / exact closure.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual >= 10 {
        // Usable gap: mild reward proportional to fill efficiency.
        score -= 0.5 * (bin_residual as f64 - post_residual as f64);
    } else {
        // Unusable dead space (1..=9): heavily penalize.
        score += 60.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // blocks the next item in a nearly-dead gap
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins,
    // and mildly prefer bins below mean residual (balancing).
    score += 0.3 * open_bins_count as f64;
    if bin_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 2.0;
    }

    // New-bin candidate: penalize slightly unless current bins are very full,
    // so a fresh bin is only chosen when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Late-stream pressure: near the end, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving a gap that neither fits next item nor is "clean"
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // dead space relative to lookahead
        }
        // Reward small post-residuals (tight packing)
        score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;
    } else {
        // Last item: prefer minimal waste
        score += 0.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count <= 1;
        let large_mean_gap = mean_residual - post_residual as f64; // mean residual minus post fit
        if poor_fits {
            score -= 8.0 + large_mean_gap.max(0.0) * 0.3;
        } else {
            score += 15.0; // discourage opening new bins when decent fits exist
        }
        // Early in stream, opening bins is cheaper; late, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Mild alignment with mean residual: prefer bins near the average fill state
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * fit_ratio * fit_ratio;

    // Penalize bins whose residual deviates from the mean (prefer balanced usage),
    // unless this bin fits the item much better than average.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a fresh bin is attractive only when the
    // lookahead item would fit well in the resulting residual, or when no good
    // fit exists among open bins.
    if bin_residual == bin_capacity {
        let lookahead_waste = if next_item_size > 0 && next_item_size <= post_residual {
            (post_residual - next_item_size) as f64
        } else {
            post_residual as f64
        };
        // Base cost of opening a new bin, discounted by how well the next item fits.
        score = 25.0 + 0.6 * lookahead_waste;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Many open bins: discourage fragmentation.
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead synergy: if placing here leaves a residual that perfectly hosts
    // the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 / (1.0 + slack * 0.1);
    }

    // Dead-space penalty: residuals too small for the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - progress) * 2.0;
    score += 12.0 * poly;

    // Penalize tight fits less as stream progresses (want compact closures)
    let tight = 1.0 - norm_pr;
    score -= 6.0 * tight * tight * (0.5 + 0.5 * progress);

    // Dead-space penalty: residual too small to be useful later
    if next_item_size > 0.0 as u32 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt.max(1.0)) * (1.0 - 0.5 * progress);
        } else {
            score -= 4.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        }
    } else {
        // last item: strongly reward near-zero residual
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: reward using it when alternatives are scarce
    if fitting_bins_count == 1 {
        score -= 7.0 * (1.0 - 0.5 * progress);
    }

    // Mean residual divergence: prefer bins close to mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64) * 0.15 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless residual is huge
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) - 8.0 * (fitting_bins_count.min(3) as f64 / 3.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    let post_class = post_residual / 10; // classes 0..=10
    // Harmonic class of next item size
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size + 9) / 10 };

    // Penalize leftover space that no plausible item can use:
    // dead space is worst when post_residual is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Reward exact fills (perfect packing)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward when the next item fits exactly into post_residual (harmonic match)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }

    // Reward when next item fits into post_residual at all (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // Extra reward when next item divides post_residual evenly (harmonic class match)
        if post_residual % next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Penalize if next item cannot fit: leftover likely becomes dead space
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Class coupling: prefer bins whose post class aligns with typical item classes
    // (items are multiples of 10 in classic streams; reward multiples of 10)
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 40.0;
        // But if open bins would leave lots of dead space, new bin is attractive:
        // compare mean residual with item size
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // If many bins already open, discourage proliferation
        score += open_bins_count as f64 * 1.5;
        // If the next item is large, a fresh bin is more valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit core)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers that nothing can use are heavily penalized.
    // Residuals below the minimum plausible item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64; // tiny gaps are the worst
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Penalize residuals that are unusable for the lookahead item: if the next item
    // cannot fit into post_residual, this placement creates stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward when the leftover can still host the next item (keeps bin usable).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another;
    // make the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    } else {
        // Slight bonus for using existing bins when open-bin count is high.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, its space
    // is scarcer; prefer placing into bins with below-average residual to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Late in the stream, waste matters more (less chance to fill gaps later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot follow here; penalize proportionally to overflow needed
        let over = (next_item_size - post_residual) as f64;
        score += 0.5 * over;
    }

    // Reward tight fits (small dead space)
    score -= 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (fill the emptiest-but-fitting bins)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0; // large item followed by smaller: new bin still viable
        }
    }

    // Late in stream: consolidate harder, avoid opening new bins
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: post_residual close to 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Penalize unusable dead space relative to smallest possible item (1..100 unknown, use 10 as soft floor)
        let dead = post_residual as f64;
        if dead < 10.0 {
            score -= 20.0 * (10.0 - dead) / 10.0;
        } else {
            // Larger leftover wastes capacity; quadratic penalty scaled by fill ratio
            let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
            score += (1.0 - fill) * (1.0 - fill) * 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (next_item_size as f64 / post_residual as f64) * 10.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            // sealed bin right before a big item is fine
            score -= 5.0;
        } else {
            // leftover too small for next item: mild penalty if leftover is dead space
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline that reflects stream progress.
    if bin_residual == bin_capacity {
        // Early in stream: opening new bins is cheap (keeps options open).
        // Late in stream: prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * progress;

        // If many open bins already, discourage yet another new bin.
        score += open_bins_count as f64 * 4.0;

        // But if no open bin fits well (fitting_bins_count small) and item is large,
        // a new bin may be right: soften the penalty.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Global state: if mean residual is high, we should consolidate into existing space.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        // Prefer bins with residual below mean (tighter bins get filled first)
        score += (bin_residual as f64 - mean_r) * 0.3;
    }

    // Mild preference for filling bins that are already well-loaded (reduce bin count pressure)
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= load_frac * load_frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
