    // Non-linear decay of residual value with stream progress:
    // late in the stream, leftover space is worth less (favor tight fits more).
    let decay = 1.0 - 0.35 * progress * progress;
    score *= decay;

    // Smooth dead-space penalty: residual that is too small to hold even the
    // smallest plausible item is wasted; penalize quadratically.
    let min_item = 1.0f64;
    if pr < min_item {
        score += 1000.0;
    } else {
        let waste = (pr / cap).powi(2);
        score += 8.0 * waste * (1.0 + progress);
