    // Lookahead coupling: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let fit_quality = 1.0 - ((pr - ni) / cap);
            score -= 6.0 * fit_quality * (1.0 - progress);
        } else {
            // residual too small for next item: smooth penalty
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild penalty scaled by abundance of alternatives
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // Prefer bins below mean residual (consolidate space into fuller bins).
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.5 * (pr - mean) * (0.5 + 0.5 * progress);

    // Slight aversion to opening new bins when many bins already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.05 * open_bins_count as f64;
    }

    score
}

