        }
    }

    // Time horizon: early in stream, be picky about tight fits (many items remain);
    // late in stream, just fill bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins with below-mean residual (pack small-residual bins first).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 18.0 - desperation
            + (open_bins_count as f64) * 0.5
            - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with smooth polynomial shaping
    let mut score = 2.0 * x * x - 2.0 * x; // negative valley at x=0.5, low near 0

    // Strong reward for exact/near-exact fits
    score += 1.5 * x.powi(6);

    // Non-linear coupling with stream progress: early on, keep flexibility (penalize tight fits mildly);
    // later, tighten aggressively.
    let flex = (1.0 - progress).powf(1.7);
    score += flex * 0.8 * (1.0 - x).powi(3);

    // Penalize leaving residuals that are too small to be useful (dead space) — smooth bump
    let dead = (x - 0.08).powi(2);
    score += 0.6 * (-dead * 40.0).exp();

    // Lookahead: reward bins whose post residual can fit the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = (x - nx).max(0.0);
        score -= 1.2 * (1.0 - (fits / (0.25 + x)).powi(2));
        // penalize if post residual just barely misses next item (smooth)
        let miss = (x - nx).abs();
        score += 0.5 * (-((x - nx).abs() - 0.0).powi(2) * 0.0) + 0.5 * (-(miss * 60.0)).exp() * (x < nx) as i32 as f64;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * progress;
    }

    // Many open bins: mild pressure to fill existing ones rather than spread
    let ob = open_bins_count as f64;
    score += 0.05 * (ob / (ob + 5.0)) * x;

    // Mean residual coupling: prefer bins below mean residual (fill emptier? no — fill bins closer to full)
    score += 0.3 * ((mean_residual / cap) - x).abs().powi(2) * 0.5;

    // New bin candidate: penalize moderately so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 2.5 + 1.5 * (1.0 - progress) + 0.4 * (fitting_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of 10) pair better with typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // penalty for odd/awkward residues; reward multiples of 10
        score += match cls {
            0 => -8.0,
            5 => -3.0,
            _ => (cls as f64) * 0.6,
        };
        // dead-space cliff: residuals that are too small for any item (1..100
        // range, but typical min ~10) are pure waste
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
        // integer-division threshold: residual bucket via pr/10
        let bucket = pr / 10;
        score -= (bucket as f64) * 1.2;
    } else {
        // perfect fill: heavily reward
        score -= 40.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            // harmonic: (post_residual / next_item_size) integer division
            let fits = pr / next_item_size;
            score -= (fits.min(3) as f64) * 6.0;
            let rem = pr % next_item_size;
            if rem == 0 {
                score -= 12.0; // exact chain fill
            } else if rem < 10 {
                score += rem as f64 * 1.5; // leaves near-dead space
            }
        } else {
            // next item won't fit here regardless; slight neutralization
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or this is a large item early in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - bin_residual as f64).abs();
        // penalize new bins by default, scaled by how many bins could fit
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
        // but if existing bins are highly fragmented (mean residual low while
        // item is big), opening fresh is fine
        score -= fragmentation * 0.4;
        score -= progress * 10.0;
        // large items relative to capacity benefit from fresh bins
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 18.0 * (frac - 0.6) * 5.0;
        }
    }

    // mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.15;

    // tie-break: prefer bins whose residual is close to item size (tight fit)
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    }

    // Prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.4;

    // Open-bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strong reward to use it instead of opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if lookahead item is large, new bin is attractive
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 12.0;
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 8.0;
        } else if post_residual as u32 > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Slight progress-aware scaling of dead-space penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Partial lookahead reward: next item fits with little waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot fit in the remainder
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer bins whose residual is already small relative to mean (tight packing)
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin fits well
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0; // new bin still allows perfect lookahead match
        } else {
            score += 50.0;
        }
    }

    // Late in the stream, consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post-residual is good, but only if it's not "dead space"
    // too small for typical future items (min item size 1..100 unknown,
    // so weight small leftovers mildly).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 120.0 * fill;
        } else {
            // next item cannot use leftover: penalize dead space
            score += 25.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        score -= 8.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early on, be more willing to open new bins (keep flexibility);
    // later, pack tighter.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: cost grows with progress
        score += 60.0 * (1.0 - progress);
        // but if all fitting bins are poor fits, allow new bin late
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 30.0 * progress;
        }
    } else {
        score -= 30.0 * progress;
    }

    // Global mean residual coupling: prefer bins near the mean (balanced packing),
    // penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Reward using bins that are already relatively full.
    let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 50.0 * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, smoothly warped
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - progress));

    // Non-linear polynomial coupling with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.6 * p2 + 0.4 * p3) * (mean_residual / cap);

    // Dead-space penalty: small post residual is bad if nothing else fits
    if pr > 0.0 && pr < next_item_size as f64 && next_item_size > 0 {
        score += 12.0 * (1.0 - pr / cap) * (1.0 - progress * 0.5);
    }

    // Perfect fit reward (smooth)
    score -= 15.0 * (1.0 - norm_pr).powi(6) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + p2);
    }

    // Prefer reusing crowded-bin sets over opening new bins as stream advances
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress - 0.3 * open_bins_count as f64;
        // New bin attractive if lookahead fits well
        if next_item_size > 0 {
            let look_fit = 1.0 - (next_item_size as f64 / cap);
            score -= 10.0 * look_fit * look_fit;
        }
    }

    // Tight packing incentive when many bins open
    score += 0.05 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: bins whose residual falls into
    // "useful" classes (divisible into common item sizes) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction

    // Penalize small-but-nonzero dead space quadratically (unusable slivers).
    if post_residual > 0 {
        let sliver = (post_residual < 10) as f64;
        score += sliver * 40.0;
        score += 8.0 / (1.0 + pr); // mild bonus for larger usable leftovers
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well it fills the leftover
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 60.0 * fill;
        } else {
            // next item cannot use this bin's leftover: penalize leftovers
            // that fall into dead classes relative to the next item.
            score += 15.0 * (frac - 0.1).max(0.0);
        }
    }

    // Integer-division thresholds on post_residual: classify leftover into
    // harmonic buckets (multiples of capacity fractions).
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == quarter || post_residual == half || post_residual == 3 * quarter {
        score -= 20.0;
    }
    if post_residual > 0 && post_residual < quarter {
        score += 12.0; // small leftover class is risky
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current bin would leave a
    // very awkward leftover or no bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so we prefer filling open bins
        score += 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin preserves flexibility for big items
        }
    }

    // Stream progression: late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += 0.1 * (mean_residual - pr);

    // Many open bins: mild pressure to close out nearly-full bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize moderate gaps that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward gaps that can accommodate the next item (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many open bins
    // when few bins fit the item (last-chance bin gets priority).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // Penalize opening new bins when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Mild penalty proportional to how far post_residual deviates below mean residual,
    // encouraging balanced residual usage across bins.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (chained near-perfect fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize small dead space that no item (min size 1..100) can use well:
    // post_residual below next item size is stranded unless tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // fill them first; loose bins should absorb awkward items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: mildly discourage opening fresh bins when any
    // reasonable fit exists; encourage it only when this bin would be
    // left with unusable sliver.
    if bin_residual == bin_capacity {
        score += 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin perfectly chains with next item
        }
    }

    // Late in the stream, minimize waste more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += 2.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), shrinking the horizon late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (low post residual is good, but reward exact/near-exact).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is wasted space
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= (1.0 - gap as f64 / bin_capacity as f64) * 25.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0; // next item won't chain here
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more when early
    // (long stream left to amortize) and when many bins are already open.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(1.0);
        score += 40.0 + 10.0 * (1.0 - progress) + open_pressure * 5.0;
        // But if no open bin fits, new bin is the only option: cancel penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large relative to item, opening fresh may pay off.
        if next_item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Global state: prefer bins with residual far from mean (balance usage),
    // slightly, only among open bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Late-stream: consolidate aggressively, avoid spreading.
    if progress > 0.8 && bin_residual >= item_size {
        score -= 8.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
