    let x = pr / cap; // in [0,1)

    // Base: penalize dead space non-linearly (quartic-ish growth)
    let mut score = x * x * (1.0 + 2.0 * x * x) * 60.0;

    // Reward tight fits: smooth polynomial coupling of post_residual with item size
    let tightness = 1.0 - x; // fraction of bin filled by this placement
    score -= tightness * tightness * (it / cap) * 40.0;

    // Stream progress coupling: as stream progresses, tolerate less dead space
    score += x * x * progress * 30.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item could fit into post_residual, reward leaving useful space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= (1.0 - gap) * 18.0 * (1.0 - progress * 0.5);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (nxt - pr) / cap * 15.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * 10.0;

    // New-bin candidate: penalize opening a new bin smoothly, scaled by open bins and progress
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0) + 1.0;
        score += 35.0 + 10.0 * openness + 20.0 * progress;
        // but if item is huge relative to capacity, opening fresh is less bad
        score -= (it / cap) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of bin left after placement

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    }

    // Dead-space penalty: residuals in awkward harmonic classes (just above
    // small item sizes 1..=10) are unusable; penalize via integer division bands.
    let band = post_residual / 10; // harmonic band index 0..10
    let band_mid = band * 10 + 5;
    if post_residual > 0 && post_residual < 10 {
        score += 250.0; // too small for any item
    } else if (band_mid as i32 - post_residual as i32).abs() <= 2 && post_residual < 50 {
        score += 60.0; // near band edges -> hard to fill exactly
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or penalize residuals that waste the next item's class.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain fit
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 120.0; // near-exact chain
            }
            // harmonic class match: same band as next item
            if (post_residual / 10) == (next_item_size / 10) {
                score -= 40.0;
            }
        } else {
            // next item won't fit here; if this is the last fitting bin,
            // penalize more (item may be stranded with dead space)
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: neutral-ish baseline; discourage opening new bins
    // when many open bins exist and mean residual is large, but allow it
    // when open bins are nearly full.
    if bin_residual == bin_capacity {
        score = cap * 0.5 + mean_residual * 0.3 + (open_bins_count as f64) * 5.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 80.0; // big item coming, fresh bin useful
        }
    }

    // Mild global pressure: as stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 20.0 * (1.0 - progress);

    // Prefer bins whose residual deviates from mean (consolidate slack).
    score -= (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 6.0; // dead space penalty, worse the smaller the gap
    }

    // Reward very tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // when the new-bin candidate (residual == capacity) is scored, penalize it
    // proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with residuals below the mean (consolidate fuller bins).
    score += (pr - mean_residual) * 0.4;

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; mildly penalize leaving a gap that's close but unusable
        let gap = (next_item_size - post_residual) as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * 1.5;
        }
    }

    // Slight preference for early consolidation vs late stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes what's left.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Partial fit reward, scaled by how snugly the next item nests.
                let nest = next_item_size as f64 / post_residual as f64;
                score -= 10.0 + 40.0 * nest;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space growth,
            // worse when the leftover is small (unusable sliver).
            let waste = post_residual as f64;
            let sliver = if post_residual < 10 { 25.0 } else { 0.0 };
            score += 8.0 + 0.25 * waste + sliver;
        }
    }

    // Tightness of current placement: reward snug fits.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Relative to mean residual: prefer bins tighter than average (fill dense bins first).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the best fit more strongly.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin is attractive early (few open bins)
    // but should not be chosen over a decent fit in existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // next item needs a fresh bin anyway
        }
    }

    // Late in the stream, be more conservative with new bins and wasteful leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // nearly unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this bin becomes extra valuable.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here after placement; mild penalty scaled
            // by how badly it misses.
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fit_quality;
    }

    // Time horizon: early in the stream, be conservative (prefer new bins to
    // keep flexibility); late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (open_bins_count as f64).sqrt() / 4.0;
    score -= progress * 5.0;

    // Global residual pressure: if mean residual across open bins is high,
    // prefer filling existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // Penalize opening a new bin when many bins could fit the item.
    if bin_residual == bin_capacity {
        let fit_bonus = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln().max(0.0) };
        score += 5.0 + 4.0 * fit_bonus;
        // But if item is huge relative to typical residual, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 2.0; // pair large items in fresh bins
        }
    }

    // Mild reward for bins whose residual matches item size modulo structure
    // (fragment-friendly residuals like 50, 33, 25...).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty on residual waste: dead space that nothing can fill
    let dead = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
    score += 40.0 * dead * dead * (0.5 + progress);

    // Tight fit reward (small post residual relative to item) — smooth coupling
    let tight = 1.0 - (pr / (item_size as f64 + 1.0)).min(1.0);
    score -= 10.0 * tight * tight;

    // Last-chance bonus: only one fitting bin, avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Prefer filling bins with high residual when many bins are open
    score -= 3.0 * (bin_residual as f64 / cap) * (open_bins_count as f64).ln().max(0.0);

    // Lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap * (1.0 - progress);
    }

    // Mild attraction toward mean residual (balance bin states)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "closed" residuals.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division thresholds on post_residual (harmonic buckets of 10).
        let bucket = post_residual / 10;
        score += match bucket {
            0 => -8.0,           // residual < 10: nearly dead space, but usable for tiny items
            1 => 2.0,            // 10..19
            2 => 6.0,            // 20..29
            3 => 10.0,           // 30..39
            4 => 14.0,           // 40..49
            _ => 18.0,           // large residual: wasteful placement
        };
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain a perfect follow-up fit
        } else if next_item_size < post_residual {
            // reward proportional closeness (harmonic fraction)
            let frac = next_item_size as f64 / post_residual as f64;
            if frac > 0.6 { score -= 10.0 * frac; }
            else { score += 5.0 * (1.0 - frac); }
        } else {
            // next item cannot use this residual -> penalize leftover
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously;
        // waived when existing bins have poor residual structure.
        let poor_fits = mean_residual > 40.0 && post_residual == bin_capacity as u32;
        score = if poor_fits { 5.0 } else { 55.0 + mean_residual * 0.2 };
    } else {
        // Slight preference for tighter bins (small residual before placement).
        score += (bin_residual as f64) * 0.05;
    }

    // Mild pressure against proliferating many open bins late in stream.
    score += (open_bins_count as f64) * 0.05;

    // Progress term: later in stream, be slightly greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next_f).abs();

        if next_f <= post {
            // Next item fits exactly: strong reward, tighter match = bigger bonus.
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            score += 0.5 * diff;
        }

        // Bonus if this bin can absorb both current and next item.
        if (item_size + next_item_size) <= bin_residual {
            score -= 15.0;
        }
    } else {
        // Last item: minimize leftover directly (already in base score).
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average.
    let mean = mean_residual;
    if (bin_residual as f64) < mean {
        score -= 4.0 * (mean - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * (bin_residual as f64 - mean) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin on a small item.
    if item_size < post_residual && post_residual > bin_capacity / 2 {
        score += 6.0;
    }

    // Mild preference for filling bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Slight penalty when many bins fit (prefer tighter bins)
        score += (fitting_bins_count as f64) * 1.5;
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Global state: penalize opening new bins when many open bins have slack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded
        score += 15.0 + mean_residual * 0.3;
        if fitting_bins_count <= 2 {
            score -= 20.0;
        }
        score += progress * 10.0;
    } else {
        score -= mean_residual * 0.1;
    }

    // Time horizon: early on, be flexible; later, pack tightly
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = post / cap; // normalized post-residual in [0,1]
    let p = progress;

    // Base: quadratic in x, modulated by progress polynomial.
    let mut score = 100.0 * (x * x * (1.0 - p) + x * (0.5 + p));

    // Smooth cubic progress interaction: penalize large post-residual more later in stream.
    score += 40.0 * p * p * (1.0 - p) * x;

    // Reward tight fits smoothly: subtract when post_residual is small.
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.5 + p);

    // Dead-space penalty: post-residual too small for typical next items.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 15.0 * (nxt - post) / cap;
        } else {
            score -= 10.0 * (1.0 - (nxt - post).abs() / cap);
        }
    }

    // Last-chance bin: smooth reward when few fitting bins.
    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - p * 0.5);
    }

    // Mild penalty when bin diverges from mean residual (balance pressure).
    score += 5.0 * ((post - mean_residual) / cap).abs();

    // Slight new-bin penalty so opening bins is used sparingly.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect-fit residues are prized.
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if post_residual < 10 {
        score -= 60.0; // near-perfect, dead space negligible
    } else {
        // Penalize residues in "dead zones": too small for typical small items (1..=10 min)
        // but too fragmented to be reliably reusable.
        let min_item = 1u32;
        if post_residual < min_item * 5 {
            score += 0.0;
        }
        // Modulo classes on post_residual: residues divisible by common item sizes
        // (10, 20, 25, 50) are more likely to be filled exactly later.
        if post_residual % 10 == 0 { score -= 25.0; }
        if post_residual % 20 == 0 { score -= 15.0; }
        if post_residual % 25 == 0 { score -= 12.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
        // Harmonic fraction thresholds: quarter/half-full leftovers
        if frac > 0.5 { score -= 20.0; }      // bin still half empty -> good candidate
        else if frac > 0.25 { score += 5.0; } // moderate leftover
        else { score += 30.0; }               // mostly full, risky dead space
    }

    // Lookahead coupling: can the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match is excellent
            if next_item_size == post_residual { score -= 80.0; }
            else { score -= 20.0 * (post_residual as f64 - next_item_size as f64) / 100.0; }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is huge
    // relative to capacity or stream is early (exploration phase).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        if big_item && mean_residual < item_size as f64 {
            score -= 30.0; // justified new bin
        } else {
            score += 40.0 + 60.0 * (1.0 - progress); // early stream: prefer reusing bins
        }
        // If many bins already open and mean residual high, opening fresh is fine.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 25.0;
        }
    }

    // Mild pressure to keep number of open bins low.
    score += 0.5 * open_bins_count as f64;

    // Tie-break with mean residual alignment: prefer bins close to the mean
    // (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 15.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize slightly more.
        score += 8.0;
    }

    // Mild preference for bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if !new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.8;

        // If next item fits exactly, heavily reward this bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item cannot fit after this placement, penalize slightly.
        else if post_residual < next_item_size {
            score += 6.0;
        }
        // If next item fits with small slack, mild reward.
        else if post_residual - next_item_size <= 10 {
            score -= 4.0;
        }
    }

    // Tight fit reward: very small post residual means minimal dead space.
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    }

    // Penalize bins whose residual deviates strongly below mean (unusual slack usage).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin early in the stream when open bins are still roomy.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it's only chosen when open bins fit poorly.
        score += 20.0;
        // If the item fits tightly in a fresh bin (item near capacity), allow it.
        if post_residual <= 15 {
            score -= 30.0;
        }
        // If no open bin fits (this call only happens for fitting bins otherwise),
        // the +20 baseline already discourages wasteful new bins.
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for filling bins that are already partially used as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tight_bonus = ((post_residual as f64) / bin_capacity as f64).powi(3) * 40.0;
    score += tight_bonus;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Perfect-fit lookahead chain bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Progress in stream: early on, be more willing to open new bins
    // (penalize using existing bins slightly less as stream advances).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, less as stream progresses.
        score += 10.0 - 6.0 * progress;
    } else {
        // Using existing bins becomes more attractive later in stream.
        score -= 4.0 * progress;
    }

    // Global residual pressure: if mean residual is high, prefer filling
    // bins that are below the mean (consolidate).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Many open bins: encourage consolidation by penalizing high-residual bins less.
    if open_bins_count > 3 {
        score -= ((open_bins_count as f64 - 3.0) * 0.5).min(5.0);
    }

    // Large items: prefer bins with small residual (avoid wasting big items on big gaps).
    if item_size > 50 {
        score += (bin_residual as f64 - item_size as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    let tightness = 1.0 - base;
    let poly = base * base * (1.0 - base) * (1.0 - base);
    let mut score = pr as f64;
    score -= 30.0 * poly * (1.0 + progress);
    score -= 10.0 * tightness * tightness * progress;
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).min(5.0) * (1.0 - progress);
    }
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste = pr - nxt;
            score -= 15.0 * (1.0 - waste / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }
    score += 6.0 * (base - mean_residual / cap).abs();
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of small denominators) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        // classify residual by gcd-style harmonic buckets
        let class: f64 = if pr % 10 == 0 {
            -6.0 // perfectly divisible leftover, reusable by typical sizes
        } else if pr % 5 == 0 {
            -3.0
        } else if pr % 3 == 0 {
            -1.5
        } else if pr < 10 {
            4.0 // dead space: tiny unusable sliver
        } else {
            0.0
        };
        score += class;

        // integer-division threshold: leftover >= 25 (quarter bin) is valuable
        if pr / 25 >= 1 {
            score -= 2.0 * ((pr / 25) as f64);
        }
        // leftover in awkward band (10..20) wastes capacity
        if pr >= 10 && pr < 20 {
            score += 3.0;
        }
        if pr == 0 {
            score -= 10.0; // perfect fill
        }
    } else {
        score -= 12.0;
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr as f64) >= ni {
            // next item fits here — strong reward, scaled by tightness
            score -= 4.0 + 3.0 * (ni / cap);
            // harmonic bonus if leftover after next item is a clean class
            let pr2 = pr as u32 - next_item_size;
            if pr2 % 10 == 0 || pr2 == 0 {
                score -= 2.0;
            }
        } else if pr > 0 {
            // next item won't fit here; penalize leaving medium dead space
            score += 1.0 + 2.0 * (ni / cap);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening fresh bin should only win when the
    // current bin would leave a bad harmonic residual.
    if bin_residual == bin_capacity {
        // fresh bin baseline: attractive only if item is large
        score = cap - item_size as f64; // post_residual of fresh bin
        score += 5.0; // mild bias toward filling existing bins
        if item_size >= 60 {
            score -= 6.0; // big items prefer fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // pair potential in a fresh bin
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio;

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / cap.max(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps (10..=20) are moderately risky: only next items <= gap can use them.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > post_residual {
            // Next item cannot use leftover: dead space likely; penalize proportionally.
            score += 6.0 * (post_residual as f64 / 100.0);
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: prefer using existing bins when many are open; encourage
    // consolidation, discourage opening new bins unless residual is large enough
    // to serve future items.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate (bin_residual == bin_capacity): only attractive when the
    // current item is large and leaves a useful residual, otherwise penalize.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 70 {
            score -= 45.0;
        } else if item_size >= 50 {
            score -= 10.0;
        }
        // A fresh bin is more attractive early in the stream or when few bins exist.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild preference for bins below mean residual (keeps residual spread balanced).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Penalize residual that is small but likely dead space.
    if post_residual > 0 {
        // waste ratio: how much of the bin is left unused relative to capacity
        let waste = (post_residual as f64) / (bin_capacity as f64);
        // dead-space penalty grows super-linearly for mid-size leftovers
        if post_residual < 10 {
            score += 15.0 * (1.0 - waste); // nearly-full bins are great, tiny penalty
        } else if post_residual <= 30 {
            score += 8.0 * waste * 10.0; // awkward medium leftover
        }
    }

    // 2-step lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item nests perfectly or well
            let leftover2 = post_residual - next_item_size;
            score -= 12.0;
            score -= (leftover2 as f64) * 0.3;
        } else if next_item_size == post_residual {
            score -= 20.0; // exact match: perfect chain
        } else {
            // next item won't fit here; if post_residual is small this is fine,
            // if it's large we're leaving exploitable space
            let miss = (next_item_size - post_residual) as f64;
            if post_residual >= 20 {
                score += miss * 0.15;
            }
        }
    }

    // Compare against mean residual across open bins.
    // Bins with residual far below mean are the "tight" ones; prefer them.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
        if post_residual <= 5 {
            score -= 10.0; // near-perfect closure
        }
    }

    // New empty bin candidate: make it unattractive unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening fresh bins is slightly less costly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If many open bins already, avoid proliferating bins
        score += (open_bins_count as f64) * 1.5;
    }

    // Reward closing bins exactly (item perfectly fills the bin).
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits perfectly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: any placement is fine, prefer tight fit only.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin is badly fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, relaxed late in the stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        score += 30.0 - 10.0 * progress - pressure.min(20.0);
        // If item is large, new bin keeps flexibility; reduce penalty.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual far below mean (consolidating fragmented bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress) * fit;

    // Penalize dead space relative to mean residual of open bins
    score += 10.0 * (norm_pr - mean_residual / cap).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - ((pr - nxt) / cap).abs() - 0.5).abs().min(1.0) * (0.5 + progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "small-item friendly" classes (multiples of 10) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Penalize dead space that is too small to host typical future items
    // (residual below the minimum item size is pure waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - frac);
    }

    // Harmonic class bonus: post_residual divisible by 10 keeps clean packing.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Modulo-4 class of post_residual: finer granularity preference.
    let m = post_residual % 4;
    score += match m { 0 => -2.0, 2 => -1.0, _ => 1.0 };

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post residual can host the next item,
    // scaled by how tight the fit would be.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits the bin now but not after this placement: mild penalty
        // for blocking the next item.
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large and open bins are mostly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / cap;
        let big_item = item_size as f64 / cap;
        // Score of a fresh bin: its post residual, adjusted by context.
        score = pr + 40.0 * (1.0 - avg_fullness) + 20.0 * big_item * (1.0 - progress);
        if post_residual % 10 == 0 { score -= 5.0; }
    }

    // Prefer packing into bins tighter than the current mean residual
    // (best-fit flavor relative to fleet state).
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= 3.0 * (diff / cap).min(1.0);
    } else {
        score += 2.0 * ((-diff) / cap).min(1.0);
    }

    // Small global pressure: many open bins encourages consolidation.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward tight fits: small but usable residual
    if post_residual > 0 && post_residual <= 20 {
        score -= 10.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: penalize adding to many open bins unless fit is tight
    let pressure = open_bins_count as f64 * 2.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (compact consolidation)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // more attractive if item is large and existing bins are fragmented
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Early stream: slight preference to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match between post_residual and next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly full after next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer post_residual just above next_item_size (tight fit leaves small usable gap)
            score += slack * 0.35;
            if slack <= 10.0 {
                score -= 8.0; // near-exact match bonus
            }
        } else {
            // next item cannot fit here either way; leftover is dead-ish space
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // last item: reward filling bin as tightly as possible
        score -= (bin_capacity as f64 - post_residual as f64) * 0.01;
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.10;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins could fit.
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += base + 20.0;
        } else {
            score += base * 0.2; // no alternative: opening a bin is fine
        }
        // early in stream, allow more bins to spread load
        if step_index < total_items / 10 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter overall fit (waste ratio).
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized waste after placement.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit leaves almost-dead space, good
    }

    // Penalize leaving large but awkward residuals (dead space that few items can use).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 10.0; // residual smaller than likely next demands
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.3 * slack;
        } else {
            // next item won't fit here anyway; slight penalty for blocking residual
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If many bins fit the item, opening a new one is wasteful.
        score += 8.0 * (fitting_bins_count.saturating_sub(1)) as f64;
        // If mean residual across open bins is large, prefer using open bins.
        score += 0.4 * mean_residual;
        // Late in the stream, avoid opening new bins (fewer chances to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // Big items relative to capacity benefit from a fresh bin early on.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 20.0;
        }
    } else {
        // Reward reusing bins that are already partially filled (consolidation).
        let used = (bin_capacity - bin_residual) as f64;
        score -= 0.15 * used;
        // Slight bonus for picking the fullest bin among equals (best-fit consolidation).
        score -= 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
            * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty when many bins are open and mean residual is small (fragmentation risk).
    if open_bins_count > 3 && mean_residual < 15.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = post;

    // Smooth polynomial coupling: penalize mid-range dead space more as stream progresses
    let quad = x * (1.0 - x); // peaks at x=0.5 (worst dead-space zone)
    score += 30.0 * quad * (0.5 + progress);

    // Cubic term: strongly reward near-zero residuals, mildly tolerate large residuals
    score -= 12.0 * x * x * x * (1.0 - progress);

    // Mean-residual coupling: if this bin is much emptier than average, slight penalty
    let dev = (mean_residual - post) / cap;
    score += 8.0 * dev * dev.abs();

    // Lookahead: if next item could use the post residual, reward leaving useful space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let util = nx / post;
            score -= 15.0 * util * (1.0 - progress);
        } else {
            score += 5.0 * (1.0 - (cap - nx) / cap) * progress;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Spread items across bins when many fit
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: prefer opening a new bin early, or when residual is very tight
    if bin_residual == bin_capacity {
        let open_bonus = 10.0 * (1.0 - progress) + (open_bins_count as f64) * 0.5;
        score = cap as f64 * 0.9 - open_bonus + post * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space quality by residue class
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let mut bonus = 0.0;

    if pr == 0 {
        bonus -= 40.0; // perfect closure
    } else if pr <= 10 {
        bonus -= 18.0; // near-perfect fill, tiny dead space
    } else {
        // modulo-16 harmonic classes of post_residual
        let m = (pr % 16) as f64;
        bonus -= (8.0 - m).abs() * 0.6; // favor residues near multiples of 8
        // integer-division thresholds: how many "next item" slots fit
        if next_item_size > 0 {
            let slots = pr / next_item_size.max(1);
            bonus -= (slots.min(4) as f64) * 6.0;
            // penalize residual just barely below next item (dead space trap)
            if pr < next_item_size {
                bonus += 12.0;
            } else if pr - (pr / next_item_size) * next_item_size < 8 {
                bonus += 3.0; // awkward leftover after next fit
            }
        }
    }

    // capacity-fraction thresholds
    let frac = post_residual as f64 / cap;
    if frac > 0.75 {
        bonus += 10.0; // large residual: wasteful to leave
    } else if frac < 0.25 && pr > 0 {
        bonus -= 6.0; // small residual: compact bins preferred
    }

    // last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        bonus -= 15.0;
    }

    // new-bin candidate: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if avg > cap * 0.4 && next_item_size > 0 && next_item_size > avg {
            bonus += 25.0; // prefer fresh bin when existing space is unusable
        } else {
            bonus += 45.0; // generally discourage opening new bins
        }
    }

    // stream progression: tighten late
    let progress = step_index as f64 / total_items.max(1) as f64;
    bonus -= progress * (mean_residual - post_residual as f64).max(0.0) * 0.15;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers that no item (>=1) can use
    // are worthless; medium leftovers (1..=15) are likely dead space given
    // typical item sizes, so penalize them super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - pr) * 12.0; // dead-space spike
    } else if post_residual > 15 && post_residual <= 40 {
        score += pr * 0.35; // moderate waste penalty
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    }

    // Reward tight fits relative to item size (small waste fraction).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins below mean residual (consolidation toward fuller bins).
    score += (pr - mean_residual) * 0.4;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large (poor fit elsewhere likely) or many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = item_frac * 30.0 + (open_bins_count as f64) * 0.8 + progress * 10.0;
        score += 45.0 - pressure; // default penalty, reduced under pressure
        // If lookahead item could use this bin's leftover, discourage new bin.
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 8.0;
        }
    } else if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        // Leaving room for the next item is valuable.
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits comfortably into post residual: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Bonus proportional to how snugly the next item fits.
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item would NOT fit here: penalize leaving large dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Penalize tiny unusable residuals relative to the smallest possible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 20.0;
        // Early in the stream, opening bins is cheap (more future items to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If many bins are open, prefer using one of them instead.
        score += 3.0 * open_bins_count as f64;
        // If the next item is large and this item is small, stacking small item on
        // existing residual may waste space; opening fresh bin slightly favored.
        if next_item_size > 0 && next_item_size > item_size && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Late in the stream, tighten packing: dead space is costly since fewer items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect chain: item + next item exactly fills residual
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 10.0 * tightness;
    }

    // Time horizon: early in stream, be more willing to open new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late
        score += 4.0 * (1.0 - progress) - 6.0 * progress;
        if open_bins_count < 2 {
            score -= 10.0;
        }
        // Opening new bin is fine if no open bin fits well
        if fitting_bins_count > 0 {
            let best_alt = mean_residual;
            if best_alt < (item_size as f64) * 1.2 {
                score += 8.0;
            }
        }
    }

    // Prefer bins with residual above mean (keeps diversity), avoid over-fragmentation
    score += 0.08 * open_bins_count as f64;
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev.abs();

    // Mild preference for bins with larger residual when item is large
    if item_size > 50 {
        score += 0.03 * (bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear dead-space penalty: small post_residual is bad unless it's a near-perfect fit.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness.powi(3) * cap * 0.1; // reward tight fits

    // Penalize residuals too small for typical future items (dead space), smooth polynomial.
    let dead = (cap * 0.25 - post / cap.max(1.0)).max(0.0);
    score += 6.0 * dead.powi(2);

    // Lookahead: reward if next item fits exactly in post_residual (perfect chaining).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = post - nx;
            score -= 10.0 * (1.0 - gap / cap).powi(2);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 2.0 * ((nx - post) / cap).powi(2);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when mean residual across open bins is still large.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress) + 3.0 * (mean_residual / cap);
    }

    // Mild preference for consolidating into bins below mean residual (balance).
    score += 1.5 * ((post - mean_residual) / cap).abs();

    // Smooth progress coupling: late in stream, prefer filling bins more tightly.
    score *= 1.0 + 0.3 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes on post_residual
    let pr = post_residual as i64;
    let cls = pr % 10;

    // Penalize leftovers in "dead" classes (hard to fill later)
    let dead_penalty = match cls {
        1 | 2 | 3 => 12.0,   // tiny unusable slivers
        4 | 6 | 7 => 4.0,    // awkward middling gaps
        5 => -2.0,           // half-filled: decent future fit
        8 | 9 => -4.0,       // nearly reusable chunks
        _ => 0.0,            // exact fit (cls 0): best
    };
    score += dead_penalty;

    // Exact fit is golden
    if post_residual == 0 {
        score -= 50.0;
    }

    // Perfect harmonic split: residual equals capacity fraction
    for k in 2..=5 {
        if post_residual as f64 == cap / k as f64 {
            score -= 8.0;
        }
    }

    // Lookahead: does next item fit the leftover? Reward harmony between classes
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward, more if it nearly fills the gap
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
            if (post_residual as i64 - next_item_size as i64).rem_euclid(10) == 0 {
                score -= 5.0; // harmonic pair
            }
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New empty bin candidate: only attractive when current bin is very full already
    if bin_residual == bin_capacity {
        score = cap * 0.85 + (open_bins_count as f64) * 0.5
              - if post_residual >= 40 { 25.0 } else { 0.0 };
    }

    // Slight preference for tighter bins overall
    score += (mean_residual - post_residual as f64) * 0.05;

    // Mild stream-progress tilt: later in stream, consolidate more aggressively
    if total_items > 0 {
        score += (step_index as f64 / total_items as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, or too small
    // for the next item) are "dead" — penalize them heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 15.0 * progress; // dead space relative to lookahead
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= 40.0 * (item_size as f64 / bin_capacity as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward using the last available fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins;
    // penalize opening a new bin (bin_residual == bin_capacity) more
    // as the number of open bins grows.
    if bin_residual == bin_capacity {
        score += 45.0 + 6.0 * open_bins_count as f64;
    } else {
        score -= 10.0;
    }

    // Mild bonus for bins tighter than the current mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (small post_residual is already the base).

    // Perfect-fill bonus: waste nothing.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead matching: if the next item fits exactly into this
    // bin's post_residual, this is a chain of two perfect placements.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mildly good, scaled by how much
            // slack remains after the hypothetical second placement.
            let second_residual = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - second_residual / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize leaving a dead gap that
            // is smaller than the next item but too small to be useful.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 60.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // already "used up"; finishing them off is good. Bins far above the
    // mean are fresh; wasting them on a loose fit is bad.
    let mean_gap = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 40.0 * mean_gap;

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize new-bin candidates unless the current fit is very loose
    // (large post_residual) — a fresh empty bin should only win when the
    // item would leave big unusable slack in an existing bin.
    if bin_residual == bin_capacity {
        score += 200.0;
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 250.0;
        }
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // closing bins with small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Penalize dead space: post residual that cannot fit a typical future item.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
            // If next item would fit exactly in post residual, extra reward.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline penalty,
    // but is allowed to win when existing fit would be very poor.
    if bin_residual == bin_capacity {
        let poor_fit_threshold = 35.0;
        let existing_fit_quality = post_residual as f64; // for new bin this equals capacity - item
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else {
            score += 18.0;
            // If placing in an existing bin would waste a lot, allow new bin.
            if existing_fit_quality > poor_fit_threshold {
                score -= 10.0;
            }
        }
    }

    // Time horizon: early in the stream, prefer consolidation; late, tolerate new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Global state: many open bins with high mean residual -> encourage filling them.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0;
    }
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score -= 3.0;
    }

    // Slight preference for bins with larger residual when item is large.
    if item_size > 50 {
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    let mut score = pr;

    // Smooth coupling: quadratic/cubic terms in x modulated by progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 20.0 * (x * x) * (0.5 + progress);
    score -= 15.0 * (x * x * x) * (1.0 - progress);
    score += 8.0 * p2 * (1.0 - x);

    // Reward tight fits (small x) more strongly as stream progresses.
    score -= (1.0 - x) * (1.0 - x) * 10.0 * (0.3 + p3);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Penalize opening new bins early; allow later in stream.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) * (1.0 + x);
    }

    // Dead-space penalty: residuals too small for typical future items.
    let dead = (x - 0.1).max(0.0).min(0.1) / 0.1; // peak near x=0.1..0.2 zone
    score += 6.0 * dead * (1.0 - p2);

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let fit_quality = 1.0 - (pr as f64 - nxt) / cap;
            score -= 14.0 * fit_quality * fit_quality;
        } else {
            score += 5.0;
        }
    }

    // Mild pressure toward consolidating residuals near the mean.
    score += 0.05 * (pr as f64 - mean_residual).abs();

    // Slight penalty for too many open bins relative to progress.
    score += open_bins_count as f64 * 0.02 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual (mod-10 classes) ---
    // Dead space: residual too small to hold even the smallest item (size 1..)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // severe dead-space penalty
    }
    // Reward residuals in "round" harmonic classes (multiples of 10) that
    // remain reusable by typical item sizes; penalize awkward classes.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.4; // awkward leftover class penalty

    // --- Lookahead (k=2): reward bins whose post_residual fits next item ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 10.0 + 4.0 * (1.0 - (post_residual as f64 - nx) / cap);
        } else {
            let gap = nx - post_residual as f64;
            score += gap.min(25.0); // near-miss penalty
        }
    }

    // --- Last-chance bin: strong reward to avoid opening a new bin needlessly ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // baseline: slightly worse than a perfect fit into an open bin
        score = cap * 1.2;
        if fitting_bins_count == 0 {
            // no open bin can fit: must open a new bin
            score -= cap;
        } else {
            // open a fresh bin for large items or when open bins are fragmented
            if item_size >= 50 {
                score -= 35.0;
            }
            if mean_residual < item_size as f64 {
                score -= 12.0;
            }
            // early in stream: cheap to open bins for flexibility
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 20.0 * (1.0 - progress);
            // if next item is huge, a fresh bin keeps pairing options open
            if next_item_size >= 60 {
                score -= 15.0;
            }
        }
    }

    // --- Slight global preference for tight fills (low post_residual) ---
    score += 0.05 * (cap - post_residual as f64).min(cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: zero waste
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count.min(20) as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are attractive targets.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream urgency: close out bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly host the next item (chained perfect packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        if chain == 0 {
            score -= 90.0;
        } else {
            score -= 30.0 * (next_item_size as f64 / post_residual.max(1) as f64);
            score += chain as f64 * 0.35; // penalize leftover dead space after chain
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; slight penalty for stranding it.
        score += 10.0;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // loose bins should absorb the item.
    if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 8.0;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Late in the stream, close out bins aggressively (prefer tighter fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // chain bonus if next item also leaves a small remainder
            let chain_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // penalize leaving dead space the next item cannot use
            score += 5.0 + 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far from mean residual (prefer balanced exploitation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in the stream: keep bins open, discourage fragmenting many bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * open_bins_count as f64;

    // Late in stream: prefer minimizing post_residual aggressively
    score += progress * 0.15 * post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_can_fit_well = fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.6;
        if open_can_fit_well {
            score += 35.0; // prefer existing bins
        } else {
            score -= 10.0; // opening fresh bin is reasonable
        }
        // late stream: avoid spawning extra bins unless necessary
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual more strongly).
    // Late: dead space is sunk cost, soften the penalty.
    let progress_coupling = 1.0 - 0.6 * progress * progress;
    score += 0.8 * progress_coupling * (post * post) / cap;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_quality = 1.0 - (post / cap);
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Penalize wasted residual relative to mean residual (dead-space creation).
    score += 0.3 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // Next item cannot use leftover; penalize proportionally to leftover size.
        score += 4.0 * (post / cap) * (post / cap);
    }

    // Mild pressure to consolidate into fewer bins as open bin count grows.
    score += 0.15 * open_bins_count as f64 * (post / cap);

    // Slight preference for opening a new bin early when residual is large.
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress) * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals that are "friendly"
    // (multiples of small classes) are more reusable than odd dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always great
    } else {
        // class by integer division thresholds
        if pr <= 5 {
            score += 25.0; // tiny dead space, nearly unusable
        } else if pr <= 15 {
            score += 12.0;
        } else if pr <= 30 {
            score -= 5.0; // sweet spot: fits mid-size items
        } else if pr <= 60 {
            score -= 10.0; // very reusable
        }
        // modulo harmony: residuals divisible by 10 or 5 align with typical sizes
        if pr % 10 == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0 * ((pr % 5) as f64);
        }
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here; reward tighter coupling when it nearly fills
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + 12.0 * (slack / 100.0);
        } else {
            // next item won't fit after this placement; penalize
            score += 6.0 + 0.1 * ((next_item_size - pr) as f64);
        }
    } else {
        // last item: prefer closing bins out completely
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are crowded (low mean residual relative to capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        score = 45.0 + 40.0 * progress - 30.0 * crowding;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.05 * next_item_size as f64; // slight penalty if next item could go here too
        }
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when an existing one is the only fit
        }
    }

    // Mild preference to consolidate across many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual tightly matches the item (waste ratio penalty).
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 15.0 * waste_ratio;
    }

    // Lookahead: if next item fits the post residual, reward keeping this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that nothing (next item) can use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline plus pressure cost, slightly relaxed by mean residual.
        score = bin_capacity as f64 * 0.9 + pressure - 0.1 * mean_residual;
        // If no existing bin fits well, allow new bin more readily.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bins get a mild bonus scaled by open-bin pressure.
        score -= pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to waste.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize unless it enables a better 2-step chain
    // than any existing bin could.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 {
            let chain = item_size as f64 + next_item_size as f64;
            if chain >= bin_capacity as f64 {
                score -= 120.0; // opening a bin for a tight pair is fine
            }
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
    }

    // Mild penalty for leaving large awkward residuals (> 50) that few items fit.
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
