        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
        // If next item exactly fills post-residual, big reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Prefer using bins with smaller residuals overall (pack fuller bins first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more aggressive about filling bins tightly
    // and less willing to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins more as stream progresses,
        // and when many bins are already open.
        score += 30.0 * progress + 1.5 * open_bins_count as f64;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Smooth base: post residual normalized
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // cubic interaction: small residuals penalized more later in stream
    score += p * (x * x * x) * 2.0;
    score -= (1.0 - p) * (x * x) * 0.5;

    // Reward tight fits smoothly (low post residual) with a saturating term
    score -= (1.0 - x).powi(3) * (1.0 + fit_ratio) * 0.8;

    // Last-chance bonus (smooth gating via fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - fit_ratio);
    }

    // Penalize opening new bins when plenty of residual exists elsewhere
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * (mean_residual / cap).min(1.0);
        score -= 0.3 * p;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (nx - x).abs();
        score += 0.5 * gap * gap;
        // reward if next item fits exactly-ish in post residual
        if x >= nx {
            score -= 0.4 * (1.0 - (x - nx));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "dead space" classes (small, hard-to-fill remainders) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Class A: post_residual in [1..=10] -> nearly dead space, strong penalty.
    if post_residual <= 10 {
        score += 40.0 * (1.0 - frac);
    }
    // Class B: post_residual in 11..=30 -> awkward zone, mild penalty
    // unless next item can fit into it.
    else if post_residual <= 30 {
        if next_item_size > post_residual && next_item_size > 0 {
            score += 12.0;
        } else {
            score -= 6.0;
        }
    }
    // Class C: post_residual in 31..=60 -> sweet spot for mid items.
    else if post_residual <= 60 {
        score -= 10.0;
        // Harmonic bonus if next item divides nicely into the remainder.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }
    // Class D: post_residual in 61..=99 -> large leftover, good.
    else {
        score -= 15.0;
    }

    // Perfect fit reward: post_residual is a multiple of common item classes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // Modulo-16 harmonic classes on post_residual: certain residues are
    // statistically harder to fill; penalize them.
    let residue_class = post_residual % 16;
    score -= match residue_class {
        0 => 6.0,
        1 | 2 | 3 => -2.0, // small odd remainders sometimes still usable
        4..=7 => 1.5,
        8..=11 => -1.0,
        _ => 2.5,
    };

    // Integer-division threshold: how many "typical" items (~25) still fit.
    let typical_fits = post_residual / 25;
    score -= 4.0 * typical_fits as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score += 55.0 - 20.0 * fragmentation - 10.0 * pressure.min(3.0);
        if item_size >= 70 && mean_residual < 0.4 * cap {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 15.0; // next item can't fit empty-bin logic anyway
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward strongly (chain placement).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    // Stream progression: later in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (frac - 0.5);

    // Mean residual alignment: prefer bins close to the mean residual
    // (keeps bin population homogeneous).
    score += 0.15 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).max(1.0).sqrt());
    score += pressure * 3.0;

    // New-bin candidate: make it unattractive unless the item is large
    // and would leave a big residual elsewhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 40.0 - 30.0 * large_item;
        if post_residual >= 30 {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
        score -= 4.0;
    }

    // Mild preference for bins tighter than the mean residual.
    score += ((mean_residual - bin_residual as f64) / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size {
            // Dead space that next item cannot use; penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean are more "precious" to fill.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only open a new bin when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, opening new bins is cheaper to avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: usually undesirable unless it's early or bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        score += 25.0 + 20.0 * progress - 0.05 * crowding;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 3.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild time-decay pressure: later in stream, favor compacting
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 60.0 * pr_norm * pr_norm;

    // Smooth progress coupling: late in the stream, waste is more costly
    score *= 1.0 + 0.8 * progress * (1.0 - progress * 0.5);

    // Reward tight fits: post_residual near zero gets a strong smooth bonus
    let tightness = 1.0 - pr_norm;
    score -= 45.0 * tightness * tightness * tightness;

    // Interaction: post_residual vs mean residual — prefer bins deviating below mean waste
    score += 0.35 * (pr - mean_residual) + 0.15 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into the post residual, reward this placement
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 10.0 * (-gap / cap);
        }
    }

    // Penalize many open bins mildly to encourage consolidation
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: keep it attractive only when residual would be large waste
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - item_size as f64 / cap) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // mod 10 and mod 20 to detect "harmonically useful" dead space.
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;
    // Leftovers that are multiples of 10/20 are more likely reusable by future items.
    let harmonic_bonus = match (r10, r20) {
        (0, 0) => 14.0,           // perfect harmonic leftover
        (_, 0) => 8.0,            // multiple of 20 but not 10 (impossible, kept for structure)
        (0, _) => 10.0,           // multiple of 10
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space (< 10) that likely no item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly or well into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect chain fit
        } else if slack < 10 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // dead space that even the lookahead cannot exploit
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer tighter bins: closeness of fit relative to capacity.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // New-bin candidate handling: mildly discourage opening a new bin early,
    // but allow it late in the stream or when current bin leaves bad residue.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress);
        if post_residual == 0 {
            score -= 0.0; // item fills a fresh bin exactly
        }
        // If current bin would leave unusable residue, opening fresh is fine.
        if bin_residual > item_size && bin_residual - item_size < 10 {
            score -= 22.0;
        }
    }

    // Mean residual coupling: bins far below mean residual are tighter; prefer them.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals that are too small to be
    // useful for typical future items are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        } else if post_residual > 80 {
            score -= 15.0; // large leftover remains flexible
        }
    } else {
        score -= 30.0; // perfect fit: zero waste
    }

    // Bonus for fitting next item exactly into the leftover (lookahead pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // next item will seal this bin nicely
        }
    } else if next_item_size > post_residual {
        score += 8.0; // next item won't fit here; leftover may go dead
    }

    // Open-bin pressure: with many open bins, prefer tightening existing ones
    // rather than spreading; with few bins, spreading is cheaper.
    let pressure = open_bins_count as f64;
    score += pressure * (post_residual as f64) * 0.05;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure * 2.0;
    }

    // Stream progression: later in stream, waste tolerance shrinks.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (balanced packing) slightly.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness to a 2-step match
        score -= (20.0 * (-gap / 25.0).exp()).max(0.0);
        // Penalize post-residual that is too small to ever fit the next item
        if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Penalize very small dead space (unusable残) unless it's a perfect fit
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when fits exist
        score += 10.0 + 30.0 * progress + 5.0 * (fitting_bins_count as f64);
    }

    // Slight preference for fuller bins overall
    score += (1.0 - item_size as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 40.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: bonus if next item fits in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect two-item packing: residual exactly consumed by next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin would leave large unusable residual.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 3.0;
    }
    if mean_residual < item_size as f64 && bin_residual >= item_size {
        score -= 2.0;
    }

    // Mild penalty for very large residuals left over (wasted capacity).
    if post_residual > 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post residual (lower is better => tighter fit)
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress.
    // Late in the stream, waste is penalized more heavily.
    let pr_norm = pr / cap;
    let prog2 = progress * progress;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 20.0 * pr_norm * (1.0 - prog2);

    // Reward nearly-full bins (dead-space avoidance), stronger late.
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward; if it
    // barely misses, penalize leaving awkward gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual context: prefer bins whose residual deviates from mean
    // in a way that consolidates space (smooth quadratic term).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Slight penalty for spreading across too many open bins early.
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are more likely to be sealed efficiently.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes: post_residual mod 10 buckets.
    let residue_class = (post_residual % 10) as f64;
    score -= 3.0 * residue_class / 10.0; // slight reward for round-ish leftovers

    // Integer-division thresholds on post_residual: classify leftover usability.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual <= eighth {
        // Tiny dead space: excellent, bin is nearly sealed.
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 15.0;
    } else if post_residual >= half {
        // Large leftover: still useful, but don't over-reward.
        score += 10.0;
    }

    // Coupling with next item: if next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Reward tight chained fits; penalize if chain leaves awkward residue.
            if next_post <= eighth {
                score -= 25.0;
            } else if next_post > half {
                score += 8.0;
            }
        } else {
            // Next item won't fit here: bin likely closes; small penalty for waste.
            score += 0.05 * post;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Fraction of capacity used by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= 20.0 * fill_frac;

    // Progress-based mild adaptation: late in the stream, prefer sealing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post / cap);

    // Prefer bins below mean residual (tighter bins first).
    score += 0.1 * (post - mean_residual);

    // New-bin candidate: penalize mildly so it only wins when fits are awful,
    // but allow it early when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 - 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (near-zero post residual but still usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize large leftover gaps only mildly — they remain usable,
    // but a big gap wasted on a small item is still somewhat bad.
    let gap_ratio = post_residual as f64 / bin_capacity as f64;
    if gap_ratio > 0.5 {
        score += gap_ratio * 20.0;
    }

    // Last chance: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 25.0;
        } else {
            score -= 10.0 / (1.0 + slack);
        }
    }
    // If next item would NOT fit here, mild penalty for creating a
    // bin that blocks the lookahead item.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bins pressure: many open bins -> favor consolidation
    // (prefer bins with small post residual), discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: only attractive when current fit is poor
    // (large post residual) or no tight option exists. Penalize mildly
    // so consolidation wins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight nudge toward bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead fits in this bin after placement: strong reward.
            score -= 15.0 * (next_item_size as f64 / 100.0);
        } else {
            // Lookahead won't fit: penalize proportionally to wasted residual.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: slight penalty for using a poor-fit bin, encourages spreading.
    if fitting_bins_count > 2 {
        score += 3.0 * ((fitting_bins_count - 2) as f64).min(5.0);
    }

    // Time horizon: early in the stream, prefer keeping residuals balanced for future items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation * (1.0 - progress);

    // Late in stream: aggressively minimize post residual.
    score -= 10.0 * progress * tightness;

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when open bins are fragmented
        // or the item is large and residuals are tight.
        let avg_usability = mean_residual / 100.0;
        let residual_shortage = (item_size as f64 - mean_residual).max(0.0) / 100.0;
        score = 55.0
            - 30.0 * residual_shortage
            - 10.0 * (open_bins_count as f64 / 20.0).min(1.0)
            + 10.0 * avg_usability;
        // Late stream: prefer filling existing bins even imperfectly.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with progress.
    // Early in the stream: prefer tight fits strongly (waste grows costly).
    // Late in the stream: keep residual flexibility (moderate residuals OK).
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let w_early = (1.0 - progress).powi(2);
    let w_late = progress.powi(2);

    // Quadratic waste penalty, amplified early, damped late
    score += w_early * (pr_norm * pr_norm) * 60.0;
    // Cubic term: heavily penalize tiny dead space (<~15) early, mildly late
    score += w_early * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * 20.0;
    // Late stream: linear mild bonus for keeping bins balanced
    score -= w_late * pr_norm * 10.0;

    // Perfect fit reward: smooth gaussian-like bump around post_residual == 0
    let fit_quality = (-((pr as f64) / 12.0).powi(2)).exp();
    score -= fit_quality * 25.0;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 15.0 * (1.0 - slack).powi(2);
    } else if next_item_size > 0 {
        // Smooth penalty proportional to the shortfall
        let gap = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 8.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to preserve choice diversity
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Bin-count pressure: with many open bins, prefer consolidation into emptier-mean bins
    let mean_gap = (mean_residual - bin_residual as f64) / bin_capacity as f64;
    score += (open_bins_count as f64).ln().max(0.0) * mean_gap * 5.0;

    // New-bin candidate handling: neutral base so only good fits beat it
    if bin_residual == bin_capacity {
        score = 55.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residual space into capacity/10 classes
    let class_width = cap / 10.0;
    let post_class = (post_residual as f64 / class_width).floor();
    let item_class = (item_size as f64 / class_width).floor();
    let next_class = (next_item_size as f64 / class_width).floor();

    // Reward small post_residual, but with harmonic jumps at class boundaries
    score -= (10.0 - post_class) * 2.0;

    // Perfect-fit harmonic bonus: post_residual divisible by small integers (10, 20, 25, 50)
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 7.0; }
    }

    // Integer-division threshold: post_residual that can host a next item of same class
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item lands in the same harmonic class as current item
        if next_class == item_class { score -= 6.0; }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how far next item misses
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Penalize tiny unusable post_residual (dead space in (0,10))
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline, better only if current bins are crowded
    if bin_residual == bin_capacity {
        score = cap * 0.75 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight penalty for very large item in nearly-full bin creating awkward remainder
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are almost unusable
    // for items >= 10, so penalize them heavily; exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += (11 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward filling most of the bin (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this bin is already crowded
    // (low residual) or the fit here would leave a dead gap, or the next
    // item fits the fresh bin better than the post-fit residual here.
    if bin_residual == bin_capacity {
        let mut new_bin_score = 45.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            // next item can't use the leftover here; fresh bin can host it
            new_bin_score -= 20.0;
        }
        score = new_bin_score + post_residual as f64 * 0.5;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    // unless the fit is tight (handled above via fill_ratio).
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual <= 15 {
        // leftover unusable for the known next item -> dead space
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item also fits in this bin after placement: strong bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item.
        score += 10.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize leaving residuals that are small but unusable (below min item size 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin when good open bins exist and lookahead fits.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        } else if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Early in the stream, new bins are cheaper; late, they are expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Relative to mean residual: bins with much-below-average residual are scarce slots.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small to fit even the smallest item (<=1 here, so
    // instead penalize residuals unlikely to fit the lookahead item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead item can fit here: strong bonus for chaining placements.
            let chain_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 + 8.0 * chain_quality;
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Many open bins: encourage consolidating into existing bins rather than spreading.
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual.max(0.0) / (bin_capacity as f64));
    score += 0.5 * pressure * (post_residual as f64) / (bin_capacity as f64);

    // Time horizon: late in the stream, be more conservative — favor tight packing
    // of existing bins and avoid opening bins with large leftover potential waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 4.0 * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate (empty bin): only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // Cheaper to open a new bin early in the stream.
        score -= 20.0 * (1.0 - progress);
        // More expensive when many bins are already open (avoid bin proliferation).
        score += 2.0 * (open_bins_count as f64);
        // If other bins fit, opening new bin is only worth it for large items
        // that would leave awkward residues elsewhere.
        if fitting_bins_count > 0 {
            let waste_elsewhere = (bin_capacity - item_size) as f64;
            score -= 0.3 * waste_elsewhere;
            // If the lookahead item would fit perfectly in the fresh bin's residue,
            // opening a new bin becomes more attractive.
            if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
                score -= 12.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    // Reward tight fits: penalize (subtract) when post_residual is small
    let mut score = pr + 30.0 * poly;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Mean residual alignment: prefer bins near mean residual
    score += 3.0 * (mean_residual - pr).abs() / cap;

    // Slight penalty for spreading across many open bins late in stream
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes modulo capacity fractions
    let pr = post_residual;
    if pr > 0 {
        // Residuals that are "harmonic" divisors of capacity are reusable
        let harmonic = (bin_capacity % pr == 0) || (pr <= 5) || (pr == 10) || (pr == 20) || (pr == 25) || (pr == 50);
        if harmonic {
            score -= 8.0; // reward leaving reusable residual
        } else {
            score += 10.0; // penalize odd dead space
        }
        // Quadratic waste penalty for small unusable residuals
        if pr < 10 {
            score += (10 - pr) as f64 * (10 - pr) as f64 * 0.15;
        }
    } else {
        score -= 25.0; // perfect fit
    }

    // Integer-division class of the fill ratio
    let fill_class = (item_size * 4) / bin_capacity; // 0..=3 quarters
    score -= fill_class as f64 * 3.0;

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0; // chain placement possible
            // harmonic bonus when next item exactly matches residual class
            if pr % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize more if this bin was last chance
            if fitting_bins_count == 1 {
                score += 5.0;
            }
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // cheaper to open new bin late in stream when many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 15.0; // big next item benefits from fresh bin
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual (tighter packs)
    score += ((bin_residual as f64) - mean_residual) * 0.03;

    // Large items should go into tight bins
    if item_size >= 60 && bin_residual < 100 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 35.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !new_bin {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean (balanced packing).
    score += 0.4 * ((bin_residual as f64 - mean_residual).abs());

    // Early-stream mild tightening: as stream progresses, be stricter about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: small post-residual is good, but very small
    // unusable slivers are worse than an exact fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward when the next item fits exactly or well
    // into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 * (over / bin_capacity as f64).min(1.0);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large or no open bin fits well.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            // new bin can host a good 2-step chain
            score -= 20.0 * frac;
        } else {
            score += 30.0 - 20.0 * frac;
        }
    }

    // Slight preference early in the stream for consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as i64 - (next_item_size as i64).min(post_residual as i64)).max(0)
        } else {
            post_residual as i64
        };
        score += 0.6 * dead as f64;
        // Bonus when the next item exactly fills this bin afterwards.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 18.0 * (1.0 - gap as f64 / 10.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with slack: encourage consolidation into fuller bins.
    let slack = mean_residual - (post_residual as f64);
    score += 0.15 * slack * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: late in the stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 12.0 * progress * tightness;
    score += 8.0 * progress * (post_residual as f64 / cap);

    // New empty bin candidate: keep it attractive only when fits are poor
    // or no open bin is a good home.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1 - item/cap
        let threshold = 0.45 + 0.25 * progress;
        let mut nb = 30.0 * (poor_fit - threshold);
        if next_item_size > 0 && next_item_size <= post_residual {
            nb -= 6.0; // new bin can also host the next item
        }
        if fitting_bins_count == 0 {
            nb -= 60.0;
        }
        score += nb.max(-60.0).min(60.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: reward small post-residual (tight fit), superlinear so tiny residuals are strongly favored.
    let mut score = 2.0 * pr + 3.0 * fit_frac * fit_frac * cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack (future items can fill); late, demand tight packing.
    let slack_weight = 0.5 + 2.5 * progress * progress;
    score += slack_weight * fit_frac * cap;

    // Penalize dead space that is too small to be useful later (smooth logistic-style term).
    let dead_zone = fit_frac * (1.0 - fit_frac);
    score += 1.5 * dead_zone * cap * (1.0 - progress);

    // Lookahead: reward bins whose residual can still hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 1.0 * (1.0 - nx / cap);
        } else {
            score += 0.5 * (nx / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - fit_frac);
    }

    // Mild preference for bins below mean residual (consolidate slack).
    score += 0.3 * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: penalize opening a bin unless the item is large relative to capacity
    // (i.e., it would leave little slack anywhere else) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let open_penalty = 2.0 * (1.0 - size_frac) * (0.5 + progress);
        score += open_penalty + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quarter-class of capacity.
    let q = post_residual * 4 / bin_capacity; // 0..3
    // Reward near-perfect fits heavily.
    match q {
        0 => score -= 40.0,
        1 => score -= 15.0,
        2 => score -= 5.0,
        _ => {}
    }

    // Exact modulo classes: residuals that are multiples of common item sizes
    // (small harmonic divisors) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else { score += 2.0; }
    } else {
        score -= 60.0; // perfect fill
    }

    // Dead-space penalty: residual too small for typical future items.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that fit the next item exactly or well.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as f64 >= n {
            let slack = pr as f64 - n;
            if (slack as u32) % 10 == 0 {
                score -= 10.0;
            }
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 6.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave large,
    // awkward residual or few bins fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = (pr as f64) > 0.45 * cap && (pr as f64) < 0.9 * cap;
        if awkward && fitting_bins_count > 1 {
            score -= 12.0 * progress;
        } else {
            score += 30.0 + 10.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Mild preference for tighter bins when many are open.
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Anything below ~15 cannot host typical items, so punish it quadratically.
    if post_residual < 15 {
        score += (15 - post_residual) as f64 * (15 - post_residual) as f64 * 0.8;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual after placement can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Gap blocks the known next item: penalize proportionally to how "useless" it is.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; favor filling
    // existing bins and penalize opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only when current bins are crowded or mean
        // residual is too small to be useful.
        score += pressure * 10.0;
        if mean_residual < item_size as f64 * 1.5 {
            score -= 20.0;
        }
    } else {
        // Existing bin: mild reward scaling with how full it already is.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 10.0;
    }

    // Late in the stream, closing out bins tightly matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: eliminate dead space entirely.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strongly favor.
            score -= 60.0 - 1.5 * diff;
            if diff == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize leaving a gap smaller than next item.
            score += 0.5 * diff;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Penalize large leftover fragments that are unlikely usable (below min item size 1..100 heuristic: small gaps).
    let frag = post_residual as f64;
    if frag > 0.0 && frag < 25.0 {
        score += 2.0 * (25.0 - frag);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless current bin would leave huge waste.
    if bin_residual == bin_capacity {
        // New-bin candidate: score = pure waste of a fresh bin minus lookahead synergy.
        score += 50.0;
        if next_item_size > 0 && (bin_capacity as u32).saturating_sub(next_item_size) >= item_size {
            score -= 10.0;
        }
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * progress * post_residual as f64;

    // Mild penalty for bin proliferation.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = post_residual as f64 / cap;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (mild best-fit pressure).
    let fill = 1.0 - bin_residual as f64 / cap;
    score -= 6.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early on, be more willing to open new bins (explore);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses.
        score += 15.0 + 20.0 * progress;
        // But if mean residual is large and fragmented, opening a bin is fine.
        if mean_residual > cap * 0.35 {
            score -= 10.0;
        }
    } else {
        score += 10.0 * progress * (post_residual as f64 / cap);
    }

    // Global balance: if this bin's residual deviates far from mean, slight penalty.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) sharpening
    let mut score = pr + 40.0 * fit_norm * fit_norm * cap;

    // Smooth stream-progress coupling: late in the stream, tighten residual tolerance
    let late = progress * progress;
    score += 30.0 * late * fit_norm;

    // Reward tight fits smoothly (post_residual near 0 gets extra discount)
    score -= 25.0 * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - fit_norm);
    }

    // Lookahead: if next item fits into post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mean-residual coupling: penalize bins far below the mean residual (wasteful picks)
    score += 5.0 * ((mean_residual - pr) / cap).abs();

    // Slight preference for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * fit_norm * 10.0;

    // New-bin candidate: keep it neutral-to-slightly-poor unless residual savings justify
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover pairs with future items.
    // Class 0 = perfect fit; small leftovers (<=10) are near-perfect; large leftovers are wasteful.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 50 {
        score += (post_residual as f64 - 20.0) * 0.6;
    } else {
        score += (post_residual as f64 - 50.0) * 1.2;
    }

    // Modulo harmonic class: residual divisible by common item sizes (10, 20, 25, 50)
    // leaves reusable space; odd/prime-like residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 && pr < bin_capacity { score -= 5.0; }
        if pr % 10 != 0 && pr < 10 { score += 3.0; }
    }

    // Coupling with lookahead: reward if next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 18.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; leftover risk depends on its size class
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
        // Integer-division class of next item: big items (>50) prefer fresh bins
        if next_item_size > 50 && post_residual < next_item_size && post_residual < 30 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when all open residuals are small (fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual < 15.0) as i32 as f64;
        let late = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 35.0 * fragmentation - 10.0 * late;
        // If item is huge (>50), a fresh bin is often best (it pairs with nothing)
        if item_size > 50 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter existing bins relative to fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Progress-scaled tie-breaker on residual fraction.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / cap) * (10.0 + 15.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly
    if post_residual > 0 && post_residual < 10 {
