    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot use the post gap and gap is small, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < 25 {
        score += 10.0;
    }

    // Mild deviation from mean residual: prefer bins below mean (denser bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: slight penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
