    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1e-9 {
            // Perfect chain: this bin hosts item then next item exactly.
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: residual usefulness bonus, stronger for tighter chain.
            score -= 60.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            // Next item does NOT fit this bin: penalize if residual becomes dead space
            // (too small for typical items but nonzero).
            if post_residual < next_item_size {
                score += 25.0;
            }
        }
    } else {
        // Last item: strongly prefer exact fill.
        score -= 200.0;
    }

    // Compare post_residual relative to mean residual: prefer bins that end below average
    // (i.e., we used more of this bin than average), leaving fatter bins for future items.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when open bins
    // would leave a very poor fit (large post_residual waste) or few fitting bins.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let poor_fit = waste as f64 / bin_capacity as f64;
        // Opening a new bin is good if placing here would waste a lot of space
        // (post_residual large) — but a new bin leaves 100 residual, so bias:
        // favor new bin when the item fits poorly everywhere.
        score = 100.0 + poor_fit * 200.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 40.0; // new bin can host next item too
        }
        if fitting_bins_count <= 1 {
            score += 300.0; // don't abandon the only fitting bin
        }
    }

    // Mild preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer the bin that leaves the least waste.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: if the leftover cannot fit the next item,
    // that residual is likely wasted unless it is tiny.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.25;
        } else {
            // Reward residuals that can still host the lookahead item.
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when decent
    // fitting bins exist or many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 15.0;
        }
        // Early in the stream, opening bins is cheaper (spread items out).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below average (they are "tighter" than
    // the fleet); keeps many medium residuals available for future items.
    score += 0.15 * ((bin_residual as f64 - mean_residual).max(0.0));

    // Slight preference for bins that keep residual divisible into useful chunks.
    if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear amplification
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: waste matters more later
    let progress_coupling = norm_pr * (1.0 + progress * progress * 2.0);
    score += progress_coupling * cap * 0.3;

    // Penalize post-residual that can't fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && pr > 0.0 {
            score += (nx - pr) * (0.5 + progress);
        } else if pr >= nx {
            score -= 3.0 * progress; // reward leaving room for next item
        }
    } else {
        // Last item: minimize residual as tightly as possible
        score -= 5.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize mildly unless open bins have large residuals
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let avg_fit = if open_f > 0.0 { mean_residual / open_f } else { 0.0 };
        let threshold = item_size as f64 * 1.5;
        if avg_fit >= threshold {
            score -= 2.0; // open bins are fragmented; fresh bin OK
        } else {
            score += 6.0 + 8.0 * (1.0 - progress); // prefer existing bins early
        }
    }

    // Mild fragmentation penalty relative to mean residual
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit rewards: perfect and near-perfect fills are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class logic: residual mod 10 determines reusability class.
    let class = post_residual % 10;
    score += class as f64 * 0.6;
    // Residuals that are exact multiples of 10 (or 20) pair well with the
    // small-item tail of the distribution; reward them.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 6.0;
        if post_residual % 20 == 0 {
            score -= 3.0;
        }
    }
    // Dead-space penalty for awkward mid-class residuals (e.g. 11..19 mod 20).
    if post_residual > 10 && post_residual % 20 <= 9 && post_residual < bin_capacity / 2 {
        score += 4.0;
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 9.0;
            if post_residual - next_item_size <= 5 {
                score -= 6.0; // chained tight fits
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.12;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate (empty bin): keep it expensive unless the item is huge,
    // in which case seeding a fresh bin is preferable to fragmenting a bin.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 18.0 - fill_frac * 14.0;
    }

    // Coupling with mean residual: prefer bins whose post state tracks the fleet mean.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Mild stream-position term: late in the stream, consolidation matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100 unknown)
    // can use are pure waste. Penalize small non-zero gaps super-linearly.
    if post_residual > 0 {
        // gaps below ~10 are almost certainly dead space (min historical size 10)
        if post_residual < 10 {
            score += 25.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 8.0 * (20.0 - post_residual as f64);
        }
        // gentle convex pressure on all remaining gaps
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // but penalize if it leaves a gap smaller than the next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Lookahead: leaving exactly room for the next item is excellent.
    if next_item_size > 0 && post_residual == next_item_size as f64 as u32 {
        score -= 25.0;
    }
    // Leaving a gap that can't hold the next item but could hold nothing else is bad.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 6.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are still large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - progress) * 1.5;

    // Prefer bins whose residual is below the mean (consolidate small leftovers),
    // and keep large-residual bins available for large future items.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.3 * diff;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, reduced late in the stream
        score = bin_capacity as f64 - 15.0 + 20.0 * progress;
        // if a decent fitting bin exists, make new bin clearly worse
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but strongly prefer residual matching the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact 2-step completion bonus: item + next item fills bin perfectly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item cannot fit here, mild penalty for leaving large dead space.
        if next_item_size > post_residual {
            score += 0.5 * (post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize leftover.
        score += 20.0;
    }

    // Penalize bins whose residual is far below the open-bin mean (already crowded).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish score so a new bin is opened only
    // when no open bin offers a good (near-exact) fit.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 25.0;
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 35.0; // fresh bin perfectly fits next item too
        }
    }

    // Slight preference for fewer open bins late in the stream.
    score += 0.01 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness * tightness;

    // Dead-space penalty for small post-residuals that likely become unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // post-residual too small for next item: penalize proportionally
        score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).min(1.0);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones
    // over opening new bins; make the empty-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps bin states balanced and predictable for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be slightly more willing to open fresh bins
    // (plenty of future items to fill them); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress * (item_size as f64 / 100.0);
    }

    // Prefer using bins with larger residuals for large items (avoid splitting small gaps).
    if item_size > 50 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = pr_norm.powi(2) * (1.0 - pr_norm).powi(2) * 4.0;
    let mut score = pr * (1.0 + 0.5 * progress * pr_norm);
    score -= 12.0 * fit_norm * (1.0 + progress);
    let tight = 1.0 - pr / (bin_residual as f64).max(1.0);
    score -= 6.0 * tight * tight;
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }
    let lookahead_bonus = if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr { 1.0 } else { 0.0 }
    } else { 0.0 };
    score -= 5.0 * lookahead_bonus * pr_norm;
    score += 0.05 * (open_bins_count as f64) * pr_norm;
    score += (mean_residual - pr) * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the same integer-division
    // band behave similarly. Penalize classes that create "dead" slivers.
    let class = post_residual / 10; // 0..10 harmonic bands
    match class {
        0 => score += 25.0,          // tiny unusable residue -> bad
        1 => score += 12.0,          // 10..19 still mostly dead
        2 => score += 4.0,           // 20..29 marginal
        3 => score -= 2.0,           // 30..39 decent
        4 => score -= 6.0,           // 40..49 good
        5 => score -= 8.0,           // 50..59 good
        6 => score -= 5.0,           // 60..69 fine
        7 => score -= 2.0,
        _ => {}
    }

    // Perfect/near-perfect fit reward (modulo coupling).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // reward; if next item barely misses, penalize creating a near-miss.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 10.0;
            }
        } else {
            let miss = next_item_size - post_residual;
            if miss <= 10 {
                score += 8.0;
            }
        }
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are poor fits (item leaves large waste everywhere) or few options exist.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { waste - mean_residual };
        score = waste * 0.5 + pressure * 0.3 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size && waste >= 40.0 {
            score -= 15.0; // keep fresh bin for a stream of similar items
        }
        if waste <= 20.0 {
            score += 25.0; // item nearly fills a bin alone; prefer existing bins
        }
    }

    // Mild drift: early in the stream prefer tighter packing (lower score for
    // small post_residual already does this); late in stream be slightly more
    // tolerant of residual waste to avoid opening extra bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Small tie-breaker against bins far below mean residual (fragmented bins).
    score += ((mean_residual - bin_residual as f64).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fill
    } else if post_residual <= 10 {
        score += 30.0; // small dead gap: heavily penalized
    } else if post_residual <= 25 {
        score += 10.0; // moderate dead zone
    } else {
        score -= 5.0; // large residual is reusable
    }

    // Reward tight fit (waste ratio small)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Last chance: strongly favor using the only fitting bin to avoid opening a bin for one item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Prefer bins whose residual is above mean (keep balanced bins for later)
    if bin_residual as f64 > mean_residual {
        score += 4.0;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item could exactly use the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks the natural next fit
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    if bin_residual == bin_capacity {
        let early = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 50.0)) * (1.0 - early);
        score += 25.0 + 10.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        if pr == nxt {
            // Exact fit for the next item -> strongly reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: mild reward scaled by slack left after that.
            let after_next = pr - nxt;
            score -= 10.0 - (after_next / bin_capacity as f64) * 8.0;
        } else {
            // Next item cannot fit here: penalize dead space, worse when very small.
            let dead = pr / bin_capacity as f64;
            score += 15.0 * dead + 5.0;
        }
    } else {
        // Last item: just minimize waste.
        score += (bin_capacity as f64 - pr) * 0.05;
    }

    // Prefer tight fits overall: reward small post_residual relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowdedness = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        score += 30.0 - 20.0 * crowdedness;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual already does this; amplify it).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item:
    // if post_residual is small but nonzero and below next_item_size, it's wasted.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (next_item_size as f64 - post_residual as f64);
        }
        // Reward bins whose leftover can still fit the lookahead item.
        if post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: strongly prefer filling bins as completely as possible.
        score -= 40.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, grows with number of open bins
        // and mean residual (discourage hoarding open bins).
        let mut new_bin_score = 45.0 + 1.5 * open_bins_count as f64;
        // If other bins fit, opening a new bin is only attractive when the
        // existing fit is very poor (large post_residual elsewhere).
        if fitting_bins_count > 0 {
            new_bin_score += 20.0;
        }
        // Early in the stream, allow more new bins (cheap); later, penalize more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 25.0 * progress;
        // If mean residual is high, prefer reusing open bins.
        new_bin_score += 0.3 * mean_residual;
        score = new_bin_score;
    }

    // Slight preference for bins with residual close to the mean (balanced usage).
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows faster than linearly as wasted space increases.
    let mut score = pr + (pr * pr) / cap;

    // Smooth coupling of wasted-space penalty with stream progress:
    // late in the stream, dead space matters more.
    score += (pr / cap) * (progress * progress) * cap * 0.5;

    // Reward tight fits (small post_residual relative to item) more strongly.
    let tightness = 1.0 - pr / bin_residual.max(1) as f64;
    score -= tightness * tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Lookahead: bonus if the post-residual can still fit the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Penalize blocking the next item slightly, scaled by how close we are.
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * 0.15;
    }

    // Prefer bins with residual below the mean (consolidating larger gaps),
    // via a smooth sigmoid-like term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev / (1.0 + dev.abs());

    // Mild penalty for spreading across many open bins late in the stream.
    score += (open_bins_count as f64) * 0.3 * progress;

    // New-bin candidate (empty bin): keep it attractive only when the fit
    // elsewhere would be poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small sizes (10,20,25,50) are reusable.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -60.0 // perfect fill
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        5.0 // awkward leftover
    };
    score += class_bonus;

    // Penalize tiny dead space (< 10 is unusable since min item size is 10)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }

    // Coupling with next item: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            score -= 12.0;
        } else {
            score += 6.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item
    // leaves an awkward residual in every open bin and mean residual is low.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut nb = 45.0;
        // open fewer new bins when many bins already exist and are tight
        nb += open_bins_count as f64 * 1.5;
        // progress: late in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += progress * 20.0;
        // if item is large, a fresh bin is more attractive (clean fit)
        if item_size > bin_capacity / 2 {
            nb -= 12.0;
        }
        // if mean residual is small, open bins are nearly full anyway
        if mean_residual < item_size as f64 {
            nb -= 18.0;
        }
        score = nb;
    } else {
        // Tightness reward: prefer bins where the item fills a large fraction
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 15.0;
        // Prefer fuller bins (small residual) slightly
        score += (bin_residual as f64 / cap) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to be useful are penalized quadratically.
    // "Unusable" threshold: gaps below ~12 can rarely host typical items.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powi(2) * 2.5;
    } else {
        // Moderate gaps are mildly penalized relative to perfect fills.
        score += (post_residual as f64) * 0.35;
    }

    // Perfect fit reward: strongly prefer bins the item exactly fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 4 {
        score -= 25.0;
    }

    // --- Open bins pressure ---
    // When many bins are open, discourage spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item can fit into the post residual, reward this placement
    // (it preserves a usable slot for the lookahead item).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Post-residual too small for the lookahead item: mild penalty,
            // scaled by how close it is to being useful.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 20.0 {
                score += gap * 0.8;
            }
        }
    }

    // --- Mean residual context ---
    // Prefer bins whose residual is below the mean (more "committed" bins),
    // penalize dumping items into the emptiest bins.
    score += ((post_residual as f64) - mean_residual) * 0.4;

    // --- Stream progression ---
    // Late in the stream, be more conservative: tighten the fit requirement.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.5;

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a decent fit or when residuals are all nearly dead.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bins and progress.
        score += 55.0 + open_pressure * 2.0 + progress * 30.0;
        // But if the current item is large and would leave a bad gap elsewhere,
        // opening fresh can still win (score stays competitive when item is big).
        score -= (item_size as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (low post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use.
        score += (next_item_size as f64) * 0.4;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-full bin context relative to mean residual.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    // New-bin candidate: only prefer it when the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= bin_capacity * 7 / 10 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward if next item fits almost perfectly after this one.
        let chain_residual = post_residual - next_item_size;
        score -= 4.0 * (1.0 - (chain_residual as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that next item cannot use: penalize proportionally.
        score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize wasting a large bin residual on a small item when other bins exist.
    let waste = bin_residual.saturating_sub(item_size) as f64;
    if open_bins_count > 1 {
        score += 0.05 * waste;
    }

    // Prefer filling bins with above-average residual less when mean residual is low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.03 * residual_gap * (1.0 - progress);

    // Mildly discourage opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
        // But allow new bin if no open bin fits well (post_residual tiny everywhere is handled by base score).
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 4.0;
        }
    }

    // Small preference to keep many open bins balanced: penalize very low residuals early.
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear waste penalty: squared normalized post-residual, amplified late in stream.
    let norm_post = post / cap;
    score += norm_post * norm_post * cap * (0.5 + 1.5 * progress);

    // Reward tight fits: cubic decay of score with tightness.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * tightness * tightness * 20.0;

    // Last-chance bin: strong bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize if post-residual cannot fit next item but a slightly emptier bin could.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 8.0 * (1.0 - post / nxt.max(1.0));
        } else if post >= nxt {
            score -= 4.0;
        }
    }

    // Divergence from mean residual: prefer bins with residual above mean (keep big holes together).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= dev * 5.0;

    // Many open bins: discourage fragmenting; prefer filling existing bins over spreading.
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = cap as f64 - pressure + 10.0 * norm_post;
        if fitting_bins_count == 1 {
            // keep item in the last-chance existing bin rather than opening new
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer bins that end up nearly full.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Dead-space penalty: residuals that are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver, wasted
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Harmonic classes on post_residual: modulo structure of usable space.
    let pr = post_residual as i64;
    if pr > 0 {
        match pr % 10 {
            0 => score -= 5.0,   // aligns with smallest item class
            1 | 2 | 3 => score += 4.0, // awkward remainders
            _ => {}
        }
        // Integer-division thresholds: how many "small" items (<=10) still fit
        let slots = pr / 10;
        if slots >= 2 {
            score -= slots as f64 * 1.5; // residual still productive
        }
    }

    // Next-item coupling: reward residuals that can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // bonus if post_residual is a near-exact match for next item
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // residual cannot host next item: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if pressure > 0.5 && fill == 0.0 {
            // open bins are roomy; discourage opening a new one
            score += 15.0;
        } else {
            score += 10.0;
        }
    }

    // Mild stream-progress shaping: be more frugal late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the smallest
    // plausible future item are nearly worthless.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit
    // is loose, encourage consolidation.
    score += open_bins_count as f64 * 0.6;

    // Relative-fit term: prefer bins where the item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin slightly less attractive
    // than a good fit, but more attractive than a wasteful one.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score = bin_capacity as f64 + open_bins_count as f64 * 1.5;
        // If nothing else fits well, allow the new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead synergy: a fresh bin is great if next item is large.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let diff = pr - next;
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space more
            score += 15.0 * (1.0 - pr / bin_capacity as f64);
        }

        // Also reward bins where next item fits in the current residual
        // (keeps chain flexibility).
        if next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    // Compare against mean residual: placing into a bin far from the mean
    // can help balance; prefer bins with residual below mean (denser bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, especially early
    // and when open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 + 40.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        // Exception: if next item is large and current item is large,
        // a fresh bin may be attractive.
        if next_item_size > 50 && item_size > 50 {
            score -= 70.0;
        }
    }

    // Penalize very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
