    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit = mean_residual.max(0.0);
        // Penalize new bins generally, less so late in the stream or when
        // mean residual across open bins is large enough to fit the item.
        score += 20.0 - 10.0 * progress;
        if avg_fit >= item_size as f64 + 5.0 {
            score += 10.0;
        }
        // A new bin is fine if the item is huge relative to capacity (poor
        // fits everywhere anyway).
        if item_size > bin_capacity * 7 / 10 {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins with larger residuals when many bins are open.
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Slight global pressure: with many open bins, prefer denser packing.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_capacity - post_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mildly tolerant of residual; late: harshly penalize leftover space.
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward tight fits: quadratic bonus shrinking as post_residual -> 0.
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * (item_size as f64) * 0.35;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += (gap / cap) * (gap / cap) * 12.0 * (0.5 + progress);
        // Reward bins whose post-residual exactly accommodates the next item.
        if post_residual >= next_item_size {
            let fit_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= fit_tightness * fit_tightness * 6.0;
        }
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when open bins exist, scaled by how full they are.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 30.0 + 3.0 * open_bins_count as f64 * (1.0 - progress * 0.5);
        // Allow new bin late in stream if mean residual is small (bins nearly full).
        score -= (mean_residual / cap).max(0.0) * 20.0;
    }

    // Mild preference for bins below mean residual (consolidating space).
    score += ((bin_residual as f64 - mean_residual) / cap) * 2.0 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest items (1..10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class: post_residual bucketed by integer division (10-unit classes).
    let post_class = post_residual / 10;
    score += 3.0 * (post_class as f64).powi(2) * 0.5;

    // Modulo coupling: does post_residual combine with next item into a clean class?
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo = post_residual - next_item_size;
        // Reward if the combination lands exactly on a 10-boundary (harmonic class).
        if combo % 10 == 0 {
            score -= 12.0;
        }
        // Penalize leaving an awkward remainder (dead space 1..9 after the lookahead).
        if combo > 0 && combo < 10 {
            score += 10.0;
        }
        // Reward if next item fits tightly (small post-combo residual).
        score -= 0.3 * next_item_size as f64 / (1.0 + combo as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this bin's residual: mild penalty proportional to leftover.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 15.0;
        let poor_fit = post_residual > 40.0;
        if crowded || poor_fit {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Progress-scaled tightness preference: later in stream, prefer minimal post_residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 0.4 * post_residual as f64;

    // Mild fragmentation pressure relative to mean residual.
    if (post_residual as f64) > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: any unusable gap (too small for the
    // minimum plausible item) is wasted capacity. Penalize quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Penalize post-residuals that cannot host the lookahead item
    // (dead space relative to the actual near future).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins over opening new ones.
    score += 8.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins tighter than the mean residual (better fill density).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Mild late-stream tightening: as the stream progresses, favor fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e. many fitting bins means opening a new bin is wasteful).
    if bin_residual == bin_capacity {
        let waste_penalty = if fitting_bins_count > 0 {
            150.0 + 40.0 * fitting_bins_count as f64
        } else {
            0.0
        };
        score += waste_penalty;
        // A fresh bin is fine early in the stream when few bins are open.
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for the next item -> very strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // Penalize residual mismatch with the next item, scaled by remaining stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += diff * (0.4 + 0.6 * progress);
            // Next item cannot fit here: mild penalty for wasting lookahead potential.
            if post_residual < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 5.0;
    }

    // Tight fits now are good: small post_residual rewarded.
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Penalize creating dead space far below mean residual (worse than average bin).
    if (post_residual as f64) < mean_residual - 15.0 {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate: only attractive when existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the next item perfectly fills a fresh bin, allow opening it.
        if next_item_size > 0 && bin_capacity.saturating_sub(item_size) == next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Perfect chain: item + next item exactly fills the bin.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Dead space that even the next item cannot use.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more as the stream nears its end (waste matters more).
        score += 35.0 + 25.0 * progress;
        // But if the mean residual across open bins is large, opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
    }

    // Mild penalty for spreading across many bins when residuals are fragmented.
    let mean_dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_dev;

    // Slight preference for fuller bins late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, but weighted non-linearly by stream progress.
    // Late in the stream, tight fits (small post_residual) matter more,
    // so amplify the quadratic penalty on large post_residual.
    let base = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth coupling: item size vs residual — reward filling large fractions
    // of the bin with a saturating polynomial interaction.
    let fill = norm_item * (1.0 - norm_pr);
    let fill_reward = -40.0 * fill * fill * (1.0 + progress);

    // Dead-space penalty: small unusable residuals are costly, smooth via
    // a bump-like polynomial around tiny residuals.
    let dead = if norm_pr < 0.2 { (0.2 - norm_pr) * (0.2 - norm_pr) * 60.0 } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: if next item fits in post_residual, reward this placement.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -8.0 * (1.0 - (next_item_size as f64 / cap))
    } else if next_item_size > 0 {
        4.0
    } else {
        0.0
    };

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    let crowd = 0.05 * open_bins_count as f64 * (mean_residual / cap - norm_pr);

    base + fill_reward + dead + last_chance + lookahead + crowd
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space by residue class
    // modulo 10 (typical small-item quantum). Residuals near multiples of 10 are
    // reusable by future items; odd/awkward residuals are dead space.
    let pr = post_residual;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -12.0,                       // perfectly harmonious residual
        1 | 9 => 6.0,                     // awkward slivers
        2 | 8 => 2.0,
        5 => -4.0,                        // half-class is decent
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: residual buckets via pr / 10.
    // Very small buckets (< 10) are nearly dead space -> penalize proportionally.
    if pr < 10 {
        score += 15.0;
    } else if pr < 20 {
        score += 5.0;
    }

    // Lookahead coupling: reward residuals that can harmonically host the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let next_class = next_item_size % 10;
            let harmony = if pr % 10 == 0 { 10.0 } else if next_class == 0 { 6.0 } else { 3.0 };
            score -= harmony * (next_item_size as f64 / bin_capacity as f64);
            // Exact fit for next item is gold.
            if pr == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here; residual likely becomes dead space.
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: empty bin has maximal residual. Penalize opening a new bin
    // unless the item is large relative to capacity (best-fit for big items) or
    // current bins are very full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let big_item_bonus = if item_frac > 0.5 { 25.0 } else { 0.0 };
        let crowded = (mean_residual / bin_capacity as f64) < 0.2;
        score = 40.0 + big_item_bonus + 15.0 * progress
            - if crowded { 20.0 } else { 0.0 };
        // Harmonic tiebreak: an empty bin is only attractive when item harmonizes
        // with capacity classes (item % 10 == 0).
        if item_size % 10 == 0 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild pressure toward fewer open bins.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // New-bin candidate: keep it slightly attractive only when this bin would
    // leave a very small dead gap.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual > 0 && post_residual < 20 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let gap = (post_residual as f64 - next).abs();
        // Perfect chain: next item exactly fills the post-residual -> strong reward.
        if post_residual as f64 >= next {
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize leftover dead space.
            score += 0.5 * gap;
        }
        // Bonus if next item leaves a further tiny residual (2-step chain).
        if post_residual as f64 >= next && (post_residual as f64 - next) < 10.0 {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.3 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But allow a fresh bin if the item would leave a well-matching residual for the next item.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 5 {
            score -= 60.0;
        }
    }

    // Slight preference for compacting many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placement gets strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize creating small unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += post_residual as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + item_size as f64 * 0.3;
    }

    // New-bin candidate: penalize opening a new bin when many open bins exist,
    // but relax late in the stream or when mean residual is low (bins nearly full).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64;
        let mean_pressure = mean_residual / bin_capacity as f64;
        score += 25.0 + congestion * 2.0 - progress * 15.0 - mean_pressure * 20.0;
        // Large items justify a fresh bin more than small ones.
        score -= item_size as f64 * 0.4;
    }

    // Prefer filling bins that are already low on residual (consolidation).
    score += (bin_residual as f64 / bin_capacity as f64) * 12.0;

    // Mild time-horizon modulation: early on, be conservative about spreading;
    // late, prefer squeezing into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with quadratic sharpening over stream progress
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post * (0.5 + progress));

    // Non-linear coupling: dead-space penalty grows quadratically as stream advances
    let dead = norm_post * norm_post;
    score += 40.0 * dead * (0.3 + 2.0 * progress * (1.0 - progress) * 2.0);

    // Perfect / near-perfect fit reward (smooth, no hard cutoff)
    let fit_quality = 1.0 - norm_post;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * (1.0 + progress);

    // Last-chance bin: strongly reward using it (smoothly, scaled by fit quality)
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + fit_quality) * (0.5 + progress);
    }

    // Many open bins: penalize spreading residuals; encourage consolidation
    let open_pressure = (open_bins_count as f64).ln() / 10.0;
    score += open_pressure * post * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, mild reward for filling it
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 8.0 * dev * (1.0 - fit_quality);

    // Lookahead: if next item could use this post-residual exactly-ish, reward leaving it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = 1.0 - ((post - nx) / cap).abs();
        if match_term > 0.0 {
            score -= 20.0 * match_term * match_term * match_term;
        } else {
            // next item can't use leftover: penalize large leftovers mildly
            score += 6.0 * norm_post * norm_post;
        }
    }

    // New-bin candidate: keep it neutral-slightly-penalized so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress - 6.0 * (1.0 - fit_quality);
        // but if existing fits are all poor (large post residual elsewhere), new bin looks better
        score -= 12.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" is the leftover space?
    // Class 0: post_residual == 0 -> perfect fit, heavily reward.
    // Class 1: post_residual < 10 -> near-perfect, dead space negligible.
    // Class 2: post_residual in [10, 30] -> still usable by most future items.
    // Class 3+: large leftovers -> penalize proportionally (wasted potential).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0;
    } else if pr < 10 {
        score -= 30.0;
    } else if pr <= 30 {
        score -= 10.0;
    } else {
        // superlinear penalty on large dead space
        let frac = pr as f64 / cap;
        score += 20.0 * frac * frac;
    }

    // Modulo-style harmonic classes: leftover that is a multiple of small
    // granularity (e.g. divisible by 10) tends to be filled exactly later.
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a golden chain placement -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // next item fits: leftover remains usable
            let new_pr = pr - next_item_size;
            score -= (new_pr as f64).min(15.0) * 0.8;
        } else {
            // next item cannot use this leftover: penalize proportional to waste
            score += (next_item_size as f64 - pr as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // base cost of opening a bin; offset by tight fits elsewhere
        score += 15.0;
        if post_residual == 0 {
            // item == capacity, must open new bin
            score -= 200.0;
        } else if pr <= 10 {
            score -= 10.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // many open bins with slack -> avoid new bins
        if mean_residual > item_size as f64 {
            score += 8.0;
        }
    }

    // Mild preference for fuller bins (small residual before placement).
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Penalize "awkward" gaps that fit only tiny items but not typical ones.
    if post_residual > 0 && post_residual < 25 {
        score += 20.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead synergy: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it cannot fit, penalize dead space creation.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual < next_item_size {
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a
    // decent fit; otherwise pressure toward consolidation.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 35.0;
        } else if post_residual >= 10 {
            score += 15.0 + open_bins_count as f64 * 0.5;
        } else {
            score += 45.0;
        }
    }

    // Open-bins pressure: mild reward for filling already-open bins as the
    // number of open bins grows, encouraging consolidation.
    score += open_bins_count as f64 * 0.3;

    // Slight preference for using bins with smaller residuals (tighter fits).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits with small slack left.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use the remainder.
        score += 8.0 + post_residual as f64 * 0.1;
    }

    // Prefer tighter fits relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing fits are poor,
    // but more acceptable late in the stream or when mean residual is low.
    if bin_residual == bin_capacity {
        score += 30.0 - (mean_residual * 0.2) - (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for filling fuller bins early.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let nx = next_item_size as f64;

    // Base: prefer minimal post-residual (tight fit).
    let mut score = pr;

    // Reward placements whose leftover can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (nx / cap) * 12.0;
        } else {
            // Dead space that cannot serve the next item is penalized harder.
            score += (pr / cap) * 6.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 0.5 * it;
    }

    // Penalize bins far below mean residual (fragmentation spreading),
    // mildly favor bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in the stream, tighten packing: penalize wasted space more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr / cap) * 8.0;

    // Many open bins: prefer consolidating into existing bins over new ones.
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        score += 3.0 + 0.15 * open_bins_count as f64;
        // But allow new bin if all fits are terrible (large unavoidable leftover).
        if fitting_bins_count > 0 {
            let avg_fit_leftover = mean_residual - it;
            if avg_fit_leftover > 40.0 {
                score -= 20.0;
            }
        }
    } else {
        // Existing bin that fits: slight bonus to keep bin count low.
        score -= 1.0;
    }

    // Prefer bins whose residual is closest to item size (best-fit coupling).
    score += 0.02 * (bin_residual as f64 - it).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post_residual, with polynomial smoothing
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Stream progress coupling: later in stream, tighten residual preference more aggressively
    score += 20.0 * progress * prn * (1.0 - prn);

    // Dead-space penalty: residual too small to be useful for typical items
    let dead = (prn - 0.1).max(0.0) * (0.25 - prn).max(0.0);
    score -= 30.0 * dead * (1.0 + progress);

    // Last-chance bonus: only one fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward bins whose post_residual can still fit the next item
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > post_residual {
        score += 4.0 * (1.0 - progress);
    }

    // Mean residual context: if this bin is far below mean residual, it's tighter — prefer it
    score -= 3.0 * (mean_residual - pr).max(0.0) / cap;

    // Mild penalty for proliferating open bins
    score += 0.5 * (open_bins_count as f64).sqrt();

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small sizes) are more valuable.
    let r = post_residual;
    if r == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if r % 10 == 0 {
        // Leftover aligned to common item granularity -> reusable.
        score -= 12.0;
    } else if r % 5 == 0 {
        score -= 6.0;
    } else if r < 10 {
        // Tiny dead space that nothing (min size 1..100 mix) may use.
        score += 8.0;
    }

    // Dead-space threshold: integer-division classes on post_residual.
    let dead_class = r / 20; // 0..5
    score += dead_class as f64 * 4.0;

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Next item can be co-packed: reward proportionally.
            let fit_frac = next_item_size as f64 / bin_capacity as f64;
            score -= 15.0 + 25.0 * fit_frac;
            // Harmonic match: next item exactly fills residue class.
            if r % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: penalize slightly, scaled by
            // how much wasted potential this bin has.
            score += 5.0 + 0.1 * r as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent
    // fits exist, scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let decent_fit_exists = fitting_bins_count > 0
            && (bin_residual.saturating_sub(item_size)) >= (item_size / 2).max(5);
        if decent_fit_exists {
            score += 25.0 + 20.0 * (1.0 - progress);
        } else {
            score -= 10.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 10.0 * progress;
    }

    // Mild preference for filling bins below mean residual (balance).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Congestion: many open bins -> favor tighter packing to close bins.
    if open_bins_count > 8 {
        score += 0.15 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose leftover can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // leftover likely dead for the next item
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor consolidation.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += pressure * (post_residual as f64 * 0.5);

    // New-bin candidate: make it unattractive unless it's the only viable option.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 2.0;
        // If no open bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    }

    // Mild preference for tighter fits relative to mean residual.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near match: next item fits with small slack afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 20.0 - slack as f64;
        } else {
            score -= (10.0 - slack as f64 * 0.3).max(0.0);
        }
    }

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < next_item_size.max(1) {
        score += 12.0; // next item cannot follow into this bin
    }

    // Compare against mean residual: bins below mean residual are more "used up";
    // favor filling them further when fit is good.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If lookahead matches a fresh bin perfectly, allow it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Late in stream, tighten packing (avoid opening bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 40.0; // small dead space is nearly a perfect fit
    }

    // Penalize dead space in the "unusable gap" zone (1..10 excluded above).
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead coupling: if next item can use the post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // Extra reward if next item nearly fills the leftover space.
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score -= 25.0;
            }
        } else {
            // Leftover space too small for the next item: penalize proportionally.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin wastes the average residual
    // of all open bins. Penalize unless this bin is the only option or fits are bad.
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open a new bin
        } else {
            // Opening a new bin only attractive if existing residuals are small
            // relative to the item (poor fits everywhere).
            let poor_fits = (fitting_bins_count as f64).ln() + 1.0;
            score += 150.0 * poor_fits + waste * 0.5;
            // Late in the stream, avoid opening bins unless really needed.
            score += 60.0 * progress;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer bins with residual close to the item (best-fit core), scaled by global state.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    // Mild preference for bins below mean residual (consolidate emptier bins' usage).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage filling existing ones rather than spreading.
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * progress;
    score += 10.0 * poly;

    // Penalize large dead space more as stream progresses
    score += 0.05 * pr * pr / cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth falloff
    score -= 15.0 * (-pr / 20.0).exp() * (1.0 - 0.3 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let fit_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs();
        score -= 8.0 * fit_next * (-gap / 25.0).exp();
        score += 3.0 * (1.0 - fit_next) * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress) / (1.0 + mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 8 harmonic classes

    // Reward tight fits (small post_residual), with harmonic class bonuses
    match class {
        0 => score -= 30.0,                 // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 2.0,
        5 => score += 6.0,
        6 => score += 10.0,
        _ => score += 14.0,                 // large dead space
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes are more reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 20 == 0 { score -= 8.0; }
        else { score += 2.0; }
    }

    // Lookahead coupling: does the residual fit the next item exactly / well?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 25.0;              // perfect two-item chain
            } else if next_post <= 10 {
                score -= 15.0;
            } else if next_post <= 25 {
                score -= 8.0;
            } else {
                score -= 2.0;
            }
        } else {
            score += 8.0;                   // next item won't fit here
        }
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize spreading across many bins when mean residual is low
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 5.0 * (1.0 - progress);
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when open bins are genuinely poor fits
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 6.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Reward leaving a gap that the lookahead item can exactly reuse.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score += 8.0; // gap barely above next item: likely dead space
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit.
        score = 25.0 + pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can serve the lookahead too
        }
    } else {
        score += pressure * 0.05;
    }

    // Prefer bins below mean residual (keeps residuals balanced).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step match: chain two items
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item won't fit here: penalize dead space growth
            score += 10.0;
        }
    }

    // Penalize post_residual that is unusably small relative to min item size
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill is great
    } else if post_residual < 20 {
        score += 5.0; // awkward small gap
    }

    // Compare against mean residual: prefer bins that get tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; becomes attractive only if item is large
        score = 100.0 - 0.5 * item_size as f64;
        if fitting_bins_count <= 2 {
            score -= 20.0; // few alternatives: new bin is reasonable
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // pair next item into this fresh bin
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Perfect fit is almost free.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize creating dead space that nothing can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large leftovers mildly
            score += 5.0 * tightness;
        }
    }

    // Time horizon: early in stream, be conservative (keep residuals flexible);
    // late in stream, be greedy about filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);

    // Prefer bins with below-mean residual (consolidate space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no good fit exists or item is huge.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 40);
        if poor_alternatives {
            score -= 20.0;
        } else {
            score += 35.0; // discourage opening new bins when fits exist
        }
        // Big items are fine in a fresh bin.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Mild penalty when many bins are open — encourage consolidation.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let rn = r / c;

    // Base: minimize post residual, smoothed by stream progress
    let mut score = r * (1.0 + 0.5 * progress * rn);

    // Non-linear coupling: tight fits matter more late in the stream
    score -= 8.0 * (1.0 - rn) * (1.0 - rn) * (1.0 + progress);

    // Penalize dead space that no plausible item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if r < nxt && nxt <= bin_residual as f64 {
            score += 6.0 * (1.0 - progress);
        }
        if nxt <= r {
            score -= 3.0 * (nxt / c) * (1.0 - rn);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - rn);
    }

    // Mild penalty when bin residual deviates from mean residual (imbalance)
    score += 0.05 * (r - mean_residual).abs();

    // New-bin candidate: penalize proportional to remaining stream
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse granularity via integer division thresholds.
    let item_class = item_size / 10;                       // 1..=10
    let next_class = if next_item_size > 0 { next_item_size / 10 } else { 0 };

    // Reward near-perfect fits strongly (post_residual in a harmonic residue band).
    let r = post_residual;
    if r == 0 {
        score -= 60.0;                                     // perfect fill
    } else if r <= 5 {
        score -= 30.0;
    } else if r <= 10 {
        score -= 15.0;
    } else {
        // Penalize dead space that cannot plausibly host small items (sizes >= 10).
        if r < 10 {
            score += 25.0;                                 // unusable sliver
        } else {
            // Modular logic: residual modulo 10 predicts future fit quality.
            let m = r % 10;
            score += (10 - m) as f64 * 0.8;                // prefer residuals aligned to item grid
        }
    }

    // Lookahead coupling: does the residual still host the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if residual lands in the next item's harmonic class band.
            if post_residual / 10 == next_class {
                score -= 12.0;
            }
            score -= 5.0;
        } else {
            // Next item can't use this bin's leftover: penalize proportionally.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits (avoid opening new bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Base new-bin cost, discounted early in the stream or when mean residual is low.
        score += 18.0 - 10.0 * progress - congestion.min(10.0);
        // Opening a bin is good if item is large and next item is also large (needs fresh space).
        if item_class >= 6 && next_class >= 6 {
            score -= 15.0;
        }
    }

    // Mild pressure against scattering across many bins when mean residual is already large.
    if mean_residual > 40.0 && bin_residual < bin_capacity {
        score += (mean_residual - 40.0) * 0.15;
    }

    // Tie-breaker: prefer fuller bins (smaller residual) slightly.
    score += (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to fit even the smallest plausible item (1..100 range).
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // nearly unusable
        } else if post_residual < 35 {
            score += 8.0; // awkward gap
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover < 10 {
            score -= 30.0; // post_residual anticipates next item perfectly
        } else if leftover < 25 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // gap blocks the lookahead item
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.4 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is poor
    // and few bins are open; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64;
        if poor_fit && open_bins_count > 0 {
            score -= 18.0; // opening a fresh bin beats wasting space
        } else {
            score += 15.0; // default: keep filling existing bins
        }
    }

    // Mild alignment with mean residual: prefer bins below-average residual
    // (larger fill) to keep tight bins tight.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Late-stream consolidation: as stream progresses, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= 2.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is a perfect chain — reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        if slack == 0.0 {
            score -= 10.0; // exact two-item match
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what's left.
        score += 4.0 + 0.05 * post_residual as f64;
    }

    // Penalize leaving residual far from mean (fragmentation signal).
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit_open = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        // Prefer a new bin when few bins fit the item and open bins look fragmented.
        score += 8.0 - 4.0 * (fitting_bins_count as f64).min(4.0) / 4.0
                     + 5.0 * bad_fit_open
                     - 2.0 * (1.0 - progress);
    }

    // Slight preference for denser packing as stream progresses.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, be more tolerant of spreading load.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * (1.0 - progress) * (1.0 - fit_ratio);

    // Global state: if many open bins with slack, favor filling existing bins.
    if open_bins_count > 2 {
        let slack = (mean_residual - post_residual as f64).abs();
        score += 0.05 * slack;
        score -= 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // New-bin candidate: only attractive when the item is large and no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0 && fit_ratio > 0.8;
        if good_fit_exists {
            score += 60.0; // keep existing bin
        } else {
            score += 5.0 + 0.2 * post_residual as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // 0..1 residual fraction after placement
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) sharpening
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: late in the stream, punish leftover
    // space more aggressively (dead space is less likely to be filled later).
    score += 30.0 * norm_pr * norm_pr * progress;

    // Reward tight fits: interaction of item size with post-residual
    score -= 20.0 * norm_item * (1.0 - norm_pr);

    // Penalize bins far from mean residual (fragmentation avoidance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Lookahead: if next item fits exactly into post-residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 25.0 * fit_quality * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_item);
    }

    // New-bin candidate handling: empty bin gets a smooth penalty that shrinks
    // as the stream progresses (early on, spreading is cheaper).
    if bin_residual == bin_capacity {
        let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score = cap * (1.2 - 0.5 * progress) + 20.0 * open_norm;
        // If no open bin fits well, allow the new bin more readily
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with a superlinear penalty on dead space.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Harmonic class of post_residual: residual buckets mod 10.
    // Residuals in [1..10] are "almost perfect" — strongly reward them.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score -= 25.0;
    } else if pr > 50 {
        // Large residual means we wasted a big bin on a small item; mild penalty
        // unless the bin was fresh.
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: residual class continuity reward, scaled by how well it fills.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill_ratio;
        } else {
            // Next item cannot use this residual: penalize leaving a gap that
            // the known successor cannot fill.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only when current bins fit poorly.
        // Perfect-fit placement into an existing bin (post_residual small) should
        // beat the new bin.
        if post_residual <= 15 {
            score += 30.0; // discourage new bin when a near-perfect fit exists
        }
        // Encourage new bin when the stream is early or many bins are open with
        // fragmented residuals (high mean residual spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > 40.0 {
            score -= 5.0 * progress;
        }
        // Slight baseline bias so new bin is chosen only on genuinely bad fits.
        score += 12.0;
    }

    // Congestion term: many open bins with high mean residual → prefer filling
    // existing bins rather than spreading.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 4.0;
    }

    // Integer-division threshold on post_residual vs next item: harmonic pairing.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        // Residual can host the next item twice — very valuable.
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Dead space that cannot fit the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward using bins that are already quite full (small residual before placement).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: if open bins are generally full, favor this bin more.
    score -= 0.3 * mean_residual;

    // New-bin candidate: mostly discourage unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0
            + 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);
        if fitting_bins_count == 1 {
            score -= 55.0; // allow new bin if it's the only fitting one anyway
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    }

    // Late in stream: tighten packing, avoid leaving fragments.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item leaves minimal dead space.
    let perfect_fit_threshold = 3.0;
    if (post_residual as f64) <= perfect_fit_threshold {
        score -= 40.0;
    } else {
        // Tightness bonus: quadratic penalty on leftover space (wasted capacity).
        score += (post_residual as f64) * (post_residual as f64) / 200.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 2.0 {
            // Next item chains perfectly into this bin: very desirable.
            score -= 35.0;
        } else {
            // Penalize mismatch between post-residual and the lookahead item.
            score += gap / 4.0;
        }
        // If the next item would NOT fit anywhere else, prefer leaving room for it.
        if next_item_size as f64 > post_residual as f64 {
            score += 8.0; // this bin can't chain; slight penalty vs. bins that can
        }
    } else {
        // Last item in stream: just minimize leftover space.
        score += 5.0;
    }

    // Relative-to-mean residual coupling: prefer bins whose residual deviates usefully.
    let residual_f = bin_residual as f64;
    let deviation = residual_f - mean_residual;
    if deviation < 0.0 {
        // Bins tighter than average: filling them reduces fragmentation.
        score -= deviation.abs() * 0.3;
    } else {
        // Bins looser than average: mild penalty to keep average residual low.
        score += deviation * 0.15;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no open bin
    // offers a good fit. Penalize the empty-bin candidate, scaled by how many open bins fit.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        let open_scale = (open_bins_count as f64).max(1.0);
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: new bins are cheap; late stream: prefer squeezing into open bins.
        let progress_discount = 20.0 * (1.0 - progress);
        score += base_penalty + open_scale * 2.0 - progress_discount;
    }

    // Mild preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    // Small noise-free tiebreaker on item size: larger items benefit from tighter bins.
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space relative to smallest plausible future item.
    let dead_penalty = (post_residual as f64 / 10.0).powi(2);
    score += dead_penalty * 0.5;

    // Lookahead coupling: if next item fits in the post-residual, reward;
    // if next item is large and this bin would be wasted on it, penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            let waste = (next_item_size as f64 - post_residual as f64).min(20.0);
            score += waste * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual < item_size as f64 {
        score -= 6.0 * (open_bins_count as f64).ln().max(1.0) * (0.5 + progress);
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 20.0 } else if fitting_bins_count == 1 { 5.0 } else { 0.0 };
        let big_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 30.0 - scarcity - big_item_bonus - 10.0 * (1.0 - progress);
    }

    // Prefer bins with less residual overall (best-fit flavor), scaled by stream progress.
    score += (bin_residual as f64 / bin_capacity as f64) * (2.0 + 6.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling of post_residual with stream progress:
    // early on, small residuals are mildly penalized (keep bins flexible);
    // late in the stream, tight fits are rewarded more aggressively.
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let progress_coupling = progress * (1.0 - norm_pr) * (1.0 - norm_pr)
        - (1.0 - progress) * norm_pr * norm_pr;
    score -= 12.0 * progress_coupling;

    // Smooth quadratic penalty for very small dead space (wasted capacity),
    // scaled by how much slack the average open bin has.
    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 8.0 * dead * (1.0 + mean_residual / bin_capacity as f64);

    // Reward last-chance bins smoothly (avoid hard piecewise switch).
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 6.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: if next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
        score -= 4.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via integer division thresholds.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -30.0 // perfect fit: strongly reward
    } else if pr <= 10 {
        0.0 // tiny residue, harmless
    } else if pr < 20 {
        6.0 // awkward small gap
    } else if pr < 34 {
        10.0 // dead zone: few item sizes (1..34) can reuse, but many can't
    } else if pr < 50 {
        4.0 // half-class: still reusable by mid items
    } else if pr < 67 {
        8.0
    } else {
        2.0 // large residual: most items fit, keep flexible
    };
    score += class;

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward tighter chains, especially when next item nearly fills residue
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack * 0.15;
        } else {
            // next item won't chain: penalize residues just below next_item_size (worst dead space)
            let gap = (next_item_size - pr) as f64;
            score += 4.0 + gap * 0.1;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // penalize new bin normally, but discount when mean residual is low (bins nearly full)
        let mut penalty = 14.0 + open_bins_count as f64 * 0.5;
        if mean_residual < item_size as f64 * 0.6 {
            penalty -= 10.0; // existing bins too full -> new bin reasonable
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            penalty -= 6.0; // pairing opportunity with big next item
        }
        if progress > 0.9 {
            penalty += 3.0; // near end, avoid opening bins
        }
        score += penalty;
        let _ = fragmentation;
    }

    // Mild preference for tighter existing bins (smaller residual before placement).
    score += bin_residual as f64 * 0.05;

    // Modulo harmonic texture on post_residual: residues near multiples of capacity fractions
    // (e.g. 100/2=50, 100/3≈33, 100/4=25) are more reusable.
    let harmonics = [(50u32, -2.0), (33, -1.5), (25, -1.0), (20, -0.8)];
    for (h, w) in harmonics.iter() {
        let d = (pr as i64 - *h as i64).abs() as f64;
        score += *w * (1.0 - d / 10.0).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of residual consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer packing into existing bins when many are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // Penalize leaving a gap that the next item nearly fits but wastes.
    if next_item_size > post_residual && post_residual > 0 && next_item_size - post_residual <= 10 {
        score += 15.0;
    }

    // Mild preference for bins below mean residual (keeps balance).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when existing bins would waste space badly.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // ideal: next item fills this bin perfectly
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proximity to a perfect two-item packing
            score -= 40.0 * (-slack / 25.0).exp();
        } else {
            // next item cannot fit here: dead space penalty grows as post_residual shrinks
            let dead = next_item_size as f64 - post_residual as f64;
            score += 10.0 + dead * 0.5;
            // tiny post_residual is unusable waste
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average (compact them),
    // penalize dipping far below mean (fragmentation risk).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.3 * dev; // tighter than average -> good
    } else {
        score += 0.15 * (-dev); // looser than average -> mild penalty
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless item is large relative to capacity
    // (packing big items fresh leaves flexible residuals for future small items).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 45.0 - 40.0 * fill; // big items: mild penalty; small items: strong penalty
        // late in the stream, opening bins is cheaper (less future to serve)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that nothing else is likely to use
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly useless
    } else {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover; penalize proportionally
        score += 6.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global state coupling: prefer filling bins when many bins are open
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in stream, be picky about waste; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 5.0;

    // Mean residual coupling: if mean residual is high, prefer the emptiest-ish bins too
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: make empty bin mildly attractive only when current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.9;
        if poor_fit {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    let mut score = r;

    // Smooth non-linear polynomial coupling with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += norm_r * norm_r * (30.0 + 60.0 * progress) - norm_r * (10.0 * prog2 + 20.0 * prog3);

    // Reward tight fits, amplified later in the stream
    let tightness = 1.0 - norm_r;
    score -= tightness * tightness * (item_size as f64) * (0.5 + 1.5 * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    }

    // Penalize bins whose residual deviates badly from mean residual
    let dev = (r - mean_residual) / cap;
    score += dev * dev * 40.0;

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if r >= nx {
            let gap = (r - nx) / cap;
            score -= (1.0 - gap) * 12.0 * (1.0 - progress);
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many open bins early
    score += (open_bins_count as f64).sqrt() * (1.0 - progress) * 2.0;

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - tightness) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // (>= 10, the smallest plausible item) are rewarded; tiny slivers penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // dead space sliver
    } else {
        // modulo classes of post_residual: leftovers that are multiples of
        // common item sizes are more likely to be filled later.
        let pr = post_residual;
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 40, 50] {
            if pr % m == 0 {
                bonus += 8.0;
            }
        }
        score -= bonus;

        // leftover that can host the lookahead item is very valuable
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 10.0;
        }
    }

    // Tight fit reward: penalize large post_residual relative to capacity fraction
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 30.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins
    // are fragmented (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score = 55.0 - pressure * 12.0 + (post_residual as f64);
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 20.0; // next item won't fit a fresh bin anyway
        }
        if next_item_size > 0 && bin_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Integer-division threshold on item_size: large items prefer exact fits
    if item_size >= bin_capacity / 2 && post_residual < item_size / 2 {
        score -= 12.0;
    }

    // Late in the stream, prefer closing bins out (reduce waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual == 0) as i32 as f64 * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible item become unusable "dead space" -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 50.0;
    }

    // Non-linear dead-space penalty: small residuals (1..=10) are hard to fill.
    let pr = post_residual as f64;
    if post_residual >= 1 && post_residual <= 10 {
        score += 25.0 * (11.0 - pr) / 10.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0 * (21.0 - pr) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // If the lookahead item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If lookahead item would NOT fit in post residual but would fit in a
    // fresh bin, penalize wasting this bin's future usability mildly.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (next_item_size as f64 - pr) / 100.0;
    }

    // Open-bins pressure: many open bins -> prefer tighter packing (larger
    // fill fraction), fewer open bins -> tolerate spreading.
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score -= pressure * fill_frac * 5.0;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is the "tightest" bin -> prefer it when many bins are open.
    let res_gap = mean_residual - pr;
    if open_bins_count > 2 && res_gap > 0.0 {
        score -= res_gap * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate handling: an empty bin has full residual; only allow
    // it to win when current bins would leave large dead space or the item
    // barely fits there. Penalize new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let fit_tightness = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            // Opening a new bin when other bins fit: require strong reason.
            score += 20.0 + 10.0 * (1.0 - fit_tightness);
            if next_item_size > 0 && next_item_size > bin_residual - item_size {
                score -= 18.0; // lookahead needs fresh space
            }
        } else {
            // No open bin fits: new bin is the only option; slight base score.
            score -= 5.0;
        }
        // Early stream: allow more bins; late stream: discourage sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress) * if fitting_bins_count > 0 { 0.5 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remainder.
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                score -= 25.0 + 0.3 * next_item_size as f64;
            }
            // Extra reward if the chain leaves a still-usable remainder (>= 10).
            if post_residual - next_item_size >= 10 {
                score -= 8.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize dead space,
            // worse when the leftover is small (unusable sliver).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0;
            } else {
                score += 0.15 * dead;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins could fit (new-bin candidate).
    if bin_residual == bin_capacity {
        score += 35.0 + 0.2 * open_bins_count as f64;
        // But allow a new bin if the current bin set is very tight on average.
        if mean_residual < 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight stream-progression tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste * waste;

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slight reward proportional to how well the leftover matches the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space that cannot host the next item is penalized.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer zero residual exactly.
        score -= 4.0 * (post_residual == 0) as i32 as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 + 5.0;
        let mut penalty = 8.0;
        if crowded {
            penalty -= 6.0;
        }
        if open_bins_count == 0 {
            penalty = -10.0;
        }
        // Slightly cheaper to open new bins late in the stream (fewer future pairings lost).
        penalty -= 2.0 * progress;
        score += penalty;
    }

    // Prefer bins whose residual is far below the mean (already fragmented, use them up).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.5 * diff.min(20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly * cap;

    // Cubic dead-space penalty: strongly punish tiny residuals, smoothly
    let tiny = (1.0 - norm_pr).powi(3);
    score += 6.0 * tiny * (1.0 + progress);

    // Reward tight fits more as stream progresses
    score -= 10.0 * (1.0 - norm_pr) * norm_pr * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 12.0 * (1.0 - diff / cap).max(0.0);
        // Penalize if next item cannot fit but residual is large-ish waste
        if next_item_size as f64 > pr {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mild penalty for proliferating bins with large residuals left
    score += 0.5 * open_c * norm_pr * (1.0 - progress);

    // Mean-residual coupling: prefer bins close to mean residual (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 3.0 * dev * (1.0 - progress);

    // New-bin candidate: only attractive when it enables a good future pairing
    if bin_residual == bin_capacity {
        let pairing = if next_item_size > 0 {
            (item_size + next_item_size) as f64
        } else {
            item_size as f64
        };
        // new bin attractive if current item + next item nearly fill capacity
        score = cap - pr + (cap - pairing).abs();
        if fitting_bins_count > 0 {
            score += 10.0 + 20.0 * progress; // discourage opening when open bins fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (divisible by common small item sizes) are favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: post_residual divisible by 10 (harmonious with 10..80 grid)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    } else {
        score += 3.0; // odd dead space penalty
    }

    // Integer-division thresholds on post_residual: small leftovers are dead space
    let dead_class = post_residual / 10; // 0..10
    match dead_class {
        0 => score += 25.0,          // <10: nearly unusable
        1 => score += 14.0,          // 10..19: only tiny items fit
        2 => score += 7.0,           // 20..29
        3 => score += 3.0,
        4 | 5 => score -= 2.0,       // 40..59: sweet spot
        6 | 7 => score -= 3.5,
        _ => {}                       // large leftover: fine
    }

    // Fraction of capacity filled: reward high fill ratio non-linearly
    let fill = 1.0 - post / cap;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            if npost % 10 == 0 {
                score -= 8.0;
            }
            score += (npost as f64) * 0.15;
        } else {
            // next item won't fit here: leftover becomes terminal dead space
            score += post * 0.10;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize so we only open when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * (open_bins_count as f64);
        // but if current item is huge relative to mean residual, opening is OK
        if (item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Stream progression: early on, be pickier (keep bins tidy); later, just fill
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    // Mild tie-break toward fewer open bins
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // Gap too small for any item (min size 1..100, but tiny gaps are waste).
        score += (10.0 - pr) * 6.0;
    } else if pr >= 10.0 && pr < 25.0 {
        // Gap usable only by very small items: moderate dead-space penalty.
        score += (25.0 - pr) * 2.5;
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 30.0;
    }

    // Tight fit bonus: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 20.0 * (fill_ratio - 0.8) / 0.2;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use the gap: penalize proportionally.
            score += (next_item_size as f64 - pr) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: penalize opening a fresh bin unless residuals are large
    // (i.e., existing bins are nearly full / fragmented).
    if bin_residual == bin_capacity {
        let avg = mean_residual;
        if avg < 25.0 {
            score -= 10.0; // existing bins too full, opening new bin is fine
        } else {
            score += avg * 0.8; // existing bins still have room, avoid new bin
        }
    }

    // Prefer bins whose residual is close to the item (minimal waste).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: less post_residual is better (already base score).
    // Perfect-fit bonus: strongly favor leaving (near) zero residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if the next item exactly fills or fits well in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // prefer chains that leave small slack
            score -= 30.0 * (slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next == 0 {
                score -= 15.0;
            }
        } else {
            // next item does NOT fit here: penalize leaving large unusable residue
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.3 * wasted;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers far below mean
    // (fragmentation) but also avoid hogging bins with large residuals.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.5 {
            score += 8.0 * (0.5 - ratio); // creating a tiny-residual bin is wasteful
        } else if ratio > 1.5 {
            score -= 4.0 * (ratio - 1.5).min(2.0); // using a roomy bin is good
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current fit is very poor
    // (large dead space) or the item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline for new bin; make it slightly unattractive unless fit elsewhere is bad
        score += 10.0;
        if item_size >= 70 {
            score -= 5.0; // big items: fresh bin can be reasonable
        }
    }

    // Late in the stream, consolidate more aggressively (avoid leaving many half-full bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize tiny dead space that nothing can use (items >= 1, so any residual
    // below the smallest plausible item is wasted; weight by how unusable it is).
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize proportionally to wasted potential.
            score += (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Compare residual against mean residual of open bins: keep balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Time horizon: early in the stream, be more willing to open/spread bins;
    // late in the stream, prefer packing tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    // Many open bins: discourage opening yet another; encourage consolidation.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    } else {
        score -= 2.0 * open_bins_count as f64 * progress;
    }

    // Mild bonus for bins whose residual is large enough to still be useful.
    if post_residual >= 50 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: reward tight fits (low post_residual), more aggressively later in stream.
    let mut score = pr * (1.0 - 0.5 * progress) + 30.0 * norm_pr * p3;

    // Dead-space penalty: quadratic in normalized post residual, scaled by progress.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Lookahead: if next item fits exactly in post_residual, reward this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - gap / cap) * (1.0 - 0.3 * progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Slight penalty for opening new bins when many bins already open and residual is high.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * norm_pr * (1.0 - progress) + 0.05 * open_bins_count as f64;
    } else {
        // Reward using bins whose residual deviates from mean (consolidation).
        let dev = (mean_residual - pr).abs() / cap;
        score -= 8.0 * dev * (1.0 - p2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual in low bands is nearly dead space
    let pr = post_residual;
    if pr > 0 {
        let cls = pr / 10; // integer division class 0..9
        let deadness = match cls {
            0 => 60.0,                 // 1..9 unusable for min-size items
            1 => 35.0,
            2 => 20.0,
            3 => 12.0,
            4 => 6.0,
            _ => 0.0,
        };
        score += deadness;
        // modulo-5 harmonic penalty: odd remainders pair poorly
        if pr % 5 != 0 { score += (pr % 5) as f64 * 2.0; }
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size <= pr {
            score -= (next_item_size as f64) * 2.0;
            // penalty if next item leaves another dead class
            let nr = pr - next_item_size;
            if nr < 10 && nr > 0 { score += 25.0; }
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += ((next_item_size - pr) as f64).min(30.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: keep it attractive only when fits are poor
    if bin_residual == bin_capacity {
        // base neutral; penalize slightly so tight fits win, but reward when
        // existing residuals are all bad (high mean residual dispersion)
        let mean_post = (mean_residual - item_size as f64).max(0.0);
        if mean_post > 0.0 && mean_post < 10.0 {
            score -= 80.0; // open bins are nearly dead, prefer fresh bin
        } else {
            score += 40.0; // prefer filling existing bins when reasonable
        }
        score += open_bins_count as f64 * 1.5;
    }

    // Prefer packing into emptier bins early, tighter bins later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - bin_residual as f64) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small post_residual gaps that likely can't fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 15.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item does NOT fit into post_residual but would fit a fresh bin, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Compare against mean residual: bins far below mean are better targets to drain.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize moderately so it's only chosen when all open bins are bad.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Slight late-stream conservatism: keep residual usable as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space after placement.
    let cap = bin_capacity as f64;
    if post_residual > 0 {
        score += 0.35 * (post_residual as f64).powf(1.3);
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits: reward tight chain fit
            let chain_tightness = 1.0 - ((post_residual as f64 - nxt) / cap);
            score -= 12.0 * chain_tightness;
            if (post_residual as u32) == next_item_size {
                score -= 15.0; // perfect 2-step fill
            }
        } else if post_residual > 0 {
            // next item cannot fit here: penalize proportionally to wasted gap
            score += 0.25 * (post_residual as f64);
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.5 * (post_residual as f64);
    }

    // Relative to mean residual: prefer bins tighter than average when it's a good fit.
    let fit_quality = 1.0 - ((post_residual as f64) / cap);
    score -= 4.0 * fit_quality * (mean_residual / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Early in stream: be more willing to open fresh bins for large items (keep big residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size >= 50 {
        score += 6.0 * (1.0 - progress);
    }

    // Slight preference for existing bins over opening new ones late in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize leftover dead space nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize post-residual that is too small to be reusable (dead space < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here would break the chain for next item; mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Global state: many open bins with high mean residual -> favor consolidation.
    if open_bins_count > 2 {
        score -= 0.05 * mean_residual;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 25.0;
        // Large items are fine to start a new bin with.
        if item_size > 60 {
            score -= 20.0;
        }
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
        // If this is the last chance, opening new bin is acceptable fallback.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Early stream: allow more bins to be opened for flexibility.
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to item size (perfect packing).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic post-residual modulated by stream progress.
    // Late in the stream, dead space is penalized more aggressively.
    score += norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap * 0.05;

    // Cubic interaction term: small residuals near stream end are very bad (wasted capacity).
    score += norm_pr.powi(3) * (progress * progress) * cap * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = pr - ns;
        if diff >= 0.0 {
            score -= (diff / cap) * 8.0 * (1.0 - progress);
        } else {
            score += 6.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    let mean_norm = mean_residual / cap;
    score -= (mean_norm - norm_pr) * 10.0;

    // Mild penalty for spreading across too many open bins early.
    score += (open_bins_count as f64) * 0.02 * (1.0 - progress);

    // New-bin candidate: only attractive when residual is large and no tight fit exists.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 8ths
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor() as i32; // 0..8

    // Dead-space penalty grows superlinearly in the lowest classes
    if class == 0 {
        score += 0.0; // perfect fit
    } else if class == 1 {
        score += 6.0 * (1.0 - frac * 8.0); // small unusable sliver
    } else if class == 2 {
        score += 4.0;
    } else {
        score -= 2.0; // large residual is reusable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // chain of perfect fits
        } else {
            score -= 12.0 * (1.0 - slack as f64 / cap);
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; mild penalty proportional to waste
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / cap.max(1.0);
        // open new bin only if existing bins are >70% full on average
        score = 40.0 - 30.0 * avg_fullness;
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Progress-based tightness: late in the stream, avoid leaving mid-size gaps
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual % 10) as f64 * 0.3;

    // Reward filling bins that are already more than half full
    if bin_residual <= bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item are pure waste — penalize them quadratically.
    if post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 15.0;
    } else if post_residual < 25 {
        // Small, likely-unusable gaps get a moderate nonlinear penalty.
        score += ((25 - post_residual) as f64).powi(2) * 0.35;
    }

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual <= 15 {
        score -= (15 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are still healthy; encourage closing out bins with small residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (3.0 + 4.0 * progress);

    // Prefer bins whose residual deviates favorably from the mean: placing into
    // a bin with residual below mean reduces fragmentation of large gaps.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Lookahead: if the next item fits snugly in the post-residual, reward this
    // placement (leaves a useful gap); otherwise penalize blocking the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 12.0 {
                score -= 25.0; // next item nearly fills the gap: excellent
            } else {
                score -= 8.0;
            }
        } else {
            score += 12.0; // leaves a gap the next item cannot use
        }
    }

    // New-bin candidate handling: an empty bin is attractive early (builds
    // flexible capacity) but wasteful late or when a decent fit exists.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        score = 55.0 + open_bins_count as f64 * 5.0 - early * 25.0;
        // If this bin is the last chance, opening a new bin is justified.
        if fitting_bins_count == 1 {
            score -= 70.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize more when residual is small/dead.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 8.0 * (overshoot / 100.0).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish baseline; discourage unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Allow opening a new bin early in the stream when many bins already open.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize unusable dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: slight penalty to keep good bins for later items.
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // Lookahead coupling: reward leaving a residual that fits the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize wasting the lookahead opportunity slightly.
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation_pressure = (open_bins_count as f64 / 20.0).min(1.0)
        * (mean_residual / (bin_capacity as f64)).min(1.0);
    score -= 10.0 * consolidation_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: opening a bin is costly; only attractive when item is huge
    // relative to open-bin residuals or late in the stream.
    if bin_residual == bin_capacity {
        let best_open_fit = (mean_residual - item_size as f64).max(0.0);
        let openness_cost = 55.0
            - 25.0 * (item_size as f64 / bin_capacity as f64)
            - 20.0 * progress;
        score = openness_cost + best_open_fit * 0.3;
    }

    // Small noise-free deterministic tie-breaker based on bin identity (residual hash).
    score += ((bin_residual as f64 * 0.0173) % 0.5) - 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress
    let mut score = post;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let poly = 2.0 * x * x - 1.5 * x * x * x;
    score += poly * (50.0 + 150.0 * progress);

    // Tight fits rewarded (small post_residual), amplified late in stream
    score -= (1.0 - x) * (1.0 - x) * 40.0 * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 60.0 + 80.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 30.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Penalize bins far from mean residual (prefer homogeneity), smooth coupling
    score += 0.3 * (post - mean_residual).abs();

    // Mild penalty for many open bins, encouraging consolidation
    score += 2.0 * open_bins_count as f64 * progress;

    // New-bin candidate: make it unattractive unless post residual is large
    if bin_residual == bin_capacity {
        score = post + 25.0 + 100.0 * progress - 20.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "compatibility classes" with typical item granularities.
    let post = post_residual;
    let class = post % 10;

    // Dead-space penalty: residuals that are too small for the smallest
    // item (1..10) are wasted. Penalize residues in (0, 10) proportionally.
    if post > 0 && post < 10 {
        score += (10 - post) as f64 * 2.0;
    }

    // Reward exact fills strongly.
    if post == 0 {
        score -= 50.0;
    }

    // Harmonic class bonus: if post_residual is a multiple of 10, it can
    // accommodate round-sized future items well.
    if class == 0 && post > 0 {
        score -= 8.0;
    }
    // Odd/awkward classes get a mild penalty.
    if class == 5 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 && post >= next_item_size {
        let gap = post - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 15.0;
        } else {
            // Partial reward scaled by how much of the gap the next item consumes.
            score -= 10.0 * (next_item_size as f64 / post as f64);
        }
    } else if next_item_size > 0 && post > 0 {
        // Next item cannot fit here: this bin becomes dead space for the lookahead.
        score += (next_item_size as f64 - post as f64).min(20.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is poor (large post_residual).
    if bin_residual == bin_capacity {
        // Neutralize the raw post_residual advantage of an empty bin,
        // then judge by how wasteful the placement in an open bin would be.
        score = (post_residual as f64) * 0.9;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits, must open new bin
        }
        // Prefer opening a new bin early in the stream (more future items to pack).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (denser bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild preference to keep few bins open (consolidation pressure).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // future item (min item size = 1, but practically small gaps < ~10) are
    // heavily penalized as unusable dead space.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - post_residual as f64) / 10.0;
        }
    }

    // Reward very tight fits (post_residual near zero but not dead).
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is excellent; new empty bins get a mild penalty so we prefer
    // reusing open bins with good fits.
    score += open_bins_count as f64 * 0.35;

    // New-bin candidate: penalize opening a new bin, but less when current
    // open bins would leave large dead space (poor fits).
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the item fits perfectly in a fresh bin and current mean residual
        // is small (open bins are nearly full), allow opening a new bin.
        if (bin_capacity - item_size) == 0 {
            score -= 55.0;
        }
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit,
    // avoiding a forced new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up pair.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
        // If next item cannot fit in post_residual and post_residual is dead
        // space for it, add penalty proportional to stream progress (late
        // dead space is more costly since fewer chances remain).
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > post_residual && post_residual < 10 {
            score += 20.0 * progress;
        }
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size -> chain fills exactly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nx).abs();

        if diff < 0.5 {
            score -= 60.0; // exact match: reserve space perfectly
        } else if pr > nx {
            // leftover after next item: penalize proportionally to unusable remainder
            let leftover = pr - nx;
            score += 0.4 * leftover;
            // bonus if leftover is small (tight-ish chain)
            if leftover <= 10.0 {
                score -= 15.0;
            }
        } else {
            // next item cannot follow in this bin: dead space penalty grows with gap
            score += 0.8 * (nx - pr);
        }

        // Relative-to-mean residual coupling: bins with residual far below mean are precious; keep them for tight fits
        let dev = pr - mean_residual;
        score += 0.15 * dev;
        if dev < -10.0 && diff > 20.0 {
            score += 10.0; // don't waste an unusually small bin on a bad chain
        }

        // Last-chance bin: strong reward to use it rather than open a new bin
        if fitting_bins_count == 1 && post_residual <= bin_residual {
            score -= 25.0;
        }
    } else {
        // Last item: minimize post residual
        score += 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: neutral-ish baseline, only attractive when fits are terrible
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && (post_residual as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 70.0; // fresh bin enables perfect chain
        }
    }

    // Slight preference early in stream to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize very small post residuals that become dead space unless near zero.
    let frac = post_residual as f64 / bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - frac * 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= 12.0 / (1.0 + (post_residual as f64 / item_size.max(1) as f64));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Competition: slight penalty scaled by number of alternatives.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward if next item exactly complements post_residual.
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // Penalize leaving a residual that wastes space relative to next item.
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            if post_residual < next_item_size {
                score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
            let _ = waste;
        }
    }

    // New-bin candidate handling: default penalize, but allow opening when current
    // bins are crowded and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 0.6;
        let large_item = item_size > bin_capacity / 2;
        if (crowded && fitting_bins_count <= 2) || (large_item && mean_residual < item_size as f64) {
            score -= 30.0 + 10.0 * progress;
        } else {
            score += 20.0 + 8.0 * (1.0 - progress);
        }
    }

    // Mild preference for placing into bins with below-average residual
    // (consolidate fullness, keep emptier bins flexible).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Time horizon: late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual, with non-linear penalty growth.
    let mut score = pr + 0.35 * (pr / cap).powi(2) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are more reusable; later, waste is penalized harder.
    let norm_pr = pr / cap;
    score += progress * 40.0 * norm_pr * (1.0 - norm_pr).powi(2);
    score -= (1.0 - progress) * 25.0 * norm_pr * norm_pr;

    // Tight fits reward: item filling most of the bin.
    let fill = it / bin_residual.max(1) as f64;
    score -= 18.0 * fill * fill;

    // Penalize dead space below the smallest plausible item (non-linear).
    if pr > 0.0 {
        score += 6.0 * (-pr / 20.0).exp() * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to use it instead of opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nfit = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - nfit) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // New-bin candidate: mildly discourage unless residual spread is bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Class boundaries: dead space (< 10) is nearly unusable -> penalize slightly above base.
    if post_residual < 10 {
        score += 4.0; // dead space class
    } else if post_residual < 20 {
        score -= 2.0; // small but potentially usable by tiny items
    } else if post_residual < 35 {
        score -= 5.0; // mid class: good match for typical small items
    } else if post_residual < 60 {
        score -= 8.0; // large useful residual
    } else {
        score -= 10.0; // half-full or more left: very reusable
    }

    // Integer-division harmonic classes on post_residual (buckets of 12).
    let bucket = post_residual / 12;
    score -= (bucket as f64) * 1.5;

    // Lookahead coupling: reward residuals that can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Exact modular match: post_residual is a harmonic multiple class of next item.
        if post_residual % next_item_size.max(1) == 0 {
            score -= 3.0;
        }
        // Penalize if leftover falls in the awkward gap: next item won't fit but class is small.
    } else if next_item_size > 0 {
        score += 3.0; // next item must go elsewhere
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Tight fit reward: relative slack of the placement.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 5.0;

    // New-bin candidate handling: only attractive when no good open option exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; modulate by stream progress and congestion.
        score += 55.0;
        score -= (open_bins_count as f64).min(10.0) * 2.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If the item leaves the new bin in a harmonic-friendly class, slight discount.
        let pb = post_residual / 12;
        score -= (pb as f64) * 0.8;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += mean_residual * 0.35;
        // Last chance override: opening a bin should lose to the only fitting bin.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Mild congestion term: prefer spreading load when many bins are open and mean residual is low.
    if open_bins_count > 3 && mean_residual < 15.0 && bin_residual > item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
