    // Open-bin pressure: penalize adding to spread of many open bins.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: favor bins below mean (denser bins).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current placement creates large dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But allow new bin if lookahead item would benefit from fresh capacity.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score -= 35.0;
