    // Lookahead synergy: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }

    // Stream progression: mild tightening pressure over time.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
