pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 4.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }
    // If many bins fit, prefer the tightest one; slight penalty spread.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item can still go here: mild reward, scaled by snugness
            let snug = 1.0 - ((post_residual as f64) - nxt) / cap;
            score -= 5.0 * snug;
        } else if post_residual > 0 && (post_residual as f64) < nxt {
            // next item won't fit here: penalize leaving awkward gap
            score += 3.0 * (1.0 - (post_residual as f64) / nxt);
        }
        // If next item exactly matches post_residual, jackpot.
        if next_item_size == post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate logic: opening a new bin is attractive only when
    // the item is large relative to capacity or fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_ratio = item_size as f64 / cap;
        // Base penalty for wasting a fresh bin; relaxed for large items.
        let mut penalty = 18.0 - 14.0 * item_ratio;
        // If the current bin would leave a big gap, opening a new bin is fine.
        if (bin_residual as f64) - (item_size as f64) > 0.4 * cap {
            penalty -= 10.0;
        }
        // Early in stream, keep bins consolidated; late, spread is ok.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 8.0 * (1.0 - progress);
        // If no existing bin fits at all, new bin must be chosen.
        if fitting_bins_count == 0 {
            penalty = -100.0;
        }
        score += penalty;
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps residuals homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with more residual among equals when
    // many bins are open (consolidation pressure).
    score -= 0.01 * (bin_residual as f64) / (open_bins_count.max(1) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);

    let mut score = pr - 12.0 * poly * cap;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 + 3.0 * progress) * 8.0;

    // Penalize dead space: small residuals unlikely to be used
    if norm_pr < 0.15 {
        score += (0.15 - norm_pr) * cap * (1.0 + progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += (next_item_size as f64 - pr).max(0.0) * 0.2;
        }
    }

    // Mild preference for consolidating into fewer bins early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Deviation from mean residual
    score += (pr - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals in "friendly" classes
    // (multiples of common item sizes) that future items can still fill.
    let pr = post_residual;
    let friendly = (pr > 0
        && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0)) as f64;
    score -= 12.0 * friendly;

    // Penalize dead space that no realistic item (>=1) can use well:
    // very small residuals are almost unusable.
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64 / 10.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            score -= 8.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 5.0 * pr as f64 / cap;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer tighter bins overall (relative fill).
    score -= 10.0 * (1.0 - bin_residual as f64 / cap);

    // Early in stream: encourage opening bins to spread load; late: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only when existing residuals are large
        // or it's early and mean residual is high.
        score += 15.0 + 20.0 * progress - 0.15 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    } else {
        // Modulo threshold on integer division of residual by quarter capacity.
        let quarter = pr / 25;
        score -= match quarter {
            0 => 6.0,
            1 => 2.0,
            2 => 0.0,
            _ => -3.0,
        };
    }

    // Mild penalty for proliferating bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // (items >= 1, so any gap < 10 is dead space; gaps < 20 are risky).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard dead-space penalty
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits superlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit: perfect placement.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // residuals elsewhere could serve future items.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, avoid a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0 + 0.1 * bin_residual as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // next item can still use this bin
    }

    // Prefer bins below mean residual (tighter bins first) mildly.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate: only attractive when it beats a poor fit late in
    // the stream or when open bins are numerous; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_elsewhere = (post_residual as f64 > 25.0) as f64;
        score += 45.0 - 20.0 * progress - 10.0 * poor_fit_elsewhere + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Slack after also placing the next item; smaller slack is better.
            let slack_after_next = post_residual as f64 - nxt;
            score -= 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
            // Perfect chain bonus: next item exactly fills the bin.
            if slack_after_next == 0.0 {
                score -= 12.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to wasted capacity.
            let unusable = nxt - post_residual as f64;
            score += 2.5 * (unusable / bin_capacity as f64) * (unusable / bin_capacity as f64) * 100.0;
        }
    }

    // Penalize creating tiny dead space that almost nothing can use (dead-space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Reward tight fits relative to the current item.
    let fit_tightness = item_size as f64 / bin_residual as f64;
    score -= 4.0 * fit_tightness;

    // Compare against mean residual: bins with residual well below mean are "efficient" targets.
    score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Discard nearly-full bins slightly less aggressively (they are almost done anyway).
    if post_residual == 0 {
        score -= 10.0;
    }

    // Mild encouragement to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 1.5 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    // New-bin candidate: make it unattractive unless it would be nearly perfect for the pair.
    if bin_residual == bin_capacity {
        let pair_waste = bin_capacity as f64 - item_size as f64 - next_item_size as f64;
        if next_item_size > 0 && pair_waste >= 0.0 && pair_waste <= 5.0 {
            score -= 7.0; // opening a fresh bin is great if the pair almost fills it
        } else {
            score += 15.0; // default: prefer reusing open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: penalize if post_residual cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // bin remains useful for the lookahead item
        } else {
            score += 8.0; // dead space relative to the known future demand
        }
        // Exact chain fit: this bin fits both current and next item perfectly.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else {
        // End of stream: prefer filling bins as completely as possible.
        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).ln().max(1.0));
    score += 0.05 * pressure * (post_residual as f64) / (bin_capacity as f64);

    // Global residual context: if mean residual is high, prefer bins below the mean
    // (consume the cluttered bins first).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Time horizon: early in the stream, be conservative about wasting space;
    // late in the stream, prioritize closing out bins (favor larger items into
    // larger residuals).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 0.15 * (post_residual as f64);
    score -= t * 4.0 * tightness;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; adjusted by stream position and
        // how poorly existing bins would fit.
        let poor_fit_elsewhere = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score = 0.5 * (bin_capacity as f64) + 10.0 - t * 5.0 - poor_fit_elsewhere;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // fresh bin can absorb future items flexibly
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - (pr / cap);

    let mut score = pr;

    // Smooth non-linear coupling: reward tight fits with cubic term
    score -= 24.0 * tightness * tightness * tightness;

    // Interaction of fit ratio with stream progress: later in stream, prefer filling bins more fully
    score -= 18.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize leaving residuals that waste space, amplified by number of open bins
    let waste = pr / cap;
    score += 12.0 * waste * waste * (1.0 + open_bins_count as f64 * 0.05);

    // Lookahead: if next item fits in post residual, reward this bin
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let nx = next_item_size as f64 / cap;
        score -= 15.0 * nx * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins deviating from mean residual when mean is low
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless residual of it is perfect and stream is early
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * progress - 20.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are precious.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residual classes: residual in {0,25,50,75} leaves divisible space.
    let class_bonus = match post_residual % 25 {
        0 => 60.0,
        1..=5 => 25.0,
        20..=24 => 15.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize small unusable dead space (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 70.0;
        if post_residual % next_item_size == 0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty proportional to waste ratio.
        score += 10.0 * (next_item_size as f64 - post) / cap;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: prefer it only when current residual is very small or huge.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 30.0;
        // Prefer new bin if existing residuals are fragmented (high mean residual but poor fit).
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 45.0;
        }
        // Mid-stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items justify a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Tight-fill bonus: using most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 30.0 * (fill_ratio - 0.8);
    }

    // Mild penalty for spreading across too many bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (>=1) can use are pure waste;
    // gaps below the minimum item size are catastrophic.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual < 10 {
        score += 60.0; // unusable dead space
    } else {
        // reward small usable gaps slightly (tight fit)
        score -= 10.0 * (1.0 - post_residual as f64 / 40.0);
    }

    // Prefer bins whose post residual can still host a typical next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // keeps chain alive
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // dead space relative to lookahead
        }
    }

    // Last-chance pressure: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // but if no open bin fits well, allow opening: soften when mean residual is tight
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else if mean_residual > bin_capacity as f64 * 0.5 {
        // bins are collectively full-ish: favor using existing space
        score -= 5.0;
    }

    // mild tie-break: prefer fuller bins (smaller residual)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item exactly fits the post residual,
    // this is an ideal chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward chains leaving small slack after the next item.
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit after this placement: penalize proportionally.
            let overflow = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * overflow;
        }
    }

    // Compare against mean residual: bins tighter than average are precious.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well
    // (i.e., this item leaves a large post residual in every existing bin).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + 10.0;
        if fitting_bins_count == 0 {
            score = 0.0; // forced: no open bin fits
        } else {
            // Allow a new bin only if the best existing fit would be terrible.
            let item_f = item_size as f64;
            if item_f > 0.85 * bin_capacity as f64 {
                // Huge item: a fresh bin is reasonable.
                score = bin_capacity as f64 - item_f - 5.0;
            }
        }
    }

    // Mild late-stream tightening: prefer compacting as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 60.0 * tight;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving post_residual that fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // dead space that next item cannot use
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
        // combo: item + next item exactly fills bin
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Penalize opening new bins when many bins are already open and fragmented
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: cost grows with open bins and mean fragmentation
        score += 18.0 + 2.0 * open_bins_count as f64;
        score += 0.5 * mean_residual;
        // early in stream, new bins are cheaper; late, avoid them
        score += 20.0 * (1.0 - progress);
    } else {
        // favor using existing bins more as stream progresses
        score -= 8.0 * progress;
        // prefer bins with residual above mean (balanced usage)
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference for filling bins with larger residual when item is large
    if item_size > bin_capacity / 2 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with non-linear penalty for mid-range dead space.
    let mut score = pr as f64;
    score += 12.0 * x * (1.0 - x) * (1.0 + 2.0 * progress);

    // Polynomial coupling of post residual with stream progress:
    // later in the stream, waste becomes more costly; smooth cubic in progress.
    score += pr * (progress * progress * (3.0 - 2.0 * progress)) * 0.8;

    // Reward using bins when few bins can fit the item (last-chance bonus).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if next item fits exactly in post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Prefer bins with residual below mean (tighter bins first) — smooth coupling.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Encourage consolidation when many bins are open (smooth in open count).
    score -= 0.3 * (open_bins_count as f64).ln() * (1.0 - x);

    // New-bin candidate: penalize opening a new bin, more so early in stream.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize post_residuals that are "awkward": small but nonzero, hard to fill later.
    if post_residual > 0 {
        // class 1..=10: nearly-full bin, tiny dead space -> excellent, reward
        if post_residual <= 10 {
            score -= 18.0;
        } else if post_residual <= 25 {
            // small-medium gap: penalize unless next item can use it
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 6.0;
            } else {
                score += 14.0;
            }
        } else if post_residual <= 50 {
            // medium gap: good if next item fits tightly
            if next_item_size > 0 && next_item_size <= post_residual {
                let tight = (post_residual - next_item_size) as f64;
                score -= 4.0 + 8.0 * (1.0 - tight / 25.0);
            } else {
                score += 5.0;
            }
        }
    } else {
        // perfect fill
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual vs common item sizes (harmonic classes mod 10)
    let pr = post_residual as usize;
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0; // gap aligns with decimal-class item sizes
    }
    if pr % 7 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Integer-division thresholds: reward leaving gaps in "usable" bands
    let band = pr / 10;
    score -= (band as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when current bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / 8.0;
        let bad_fit = if next_item_size > 0 && next_item_size > post_residual { 10.0 } else { 0.0 };
        score += 12.0 - 8.0 * progress - crowded - bad_fit;
        // penalize opening new bin when item is small (waste of capacity)
        if item_size <= 30 {
            score += 15.0;
        }
    }

    // Prefer bins tighter than average (best-fit flavor)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild pressure to keep few open bins
    score += 0.3 * open_bins_count as f64;

    // Lookahead: if next item exactly matches post_residual, huge reward
    if next_item_size == post_residual && post_residual > 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=9 here)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score -= 30.0 / (1.0 + tightness);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 5.0;
    } else {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item can use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Early in stream, be slightly more willing to consolidate (higher open-bin penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
