}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) but avoid useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty: sliver unusable for min-size items
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // or closely accommodates the next item (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            // Perfect two-item chain: strongly subtract.
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            if slack < 10.0 {
                score -= 30.0; // near-perfect chain bonus
            }
        } else {
            // Next item won't fit here afterwards: penalize proportionally.
            score += 15.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Compare against mean residual: prefer filling below-average-residual bins
    // (consolidation), penalize dumping into already-loose bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 10.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 10.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when the
    // current item is large and would leave a well-usable residual, or when
    // open bins are nearly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Reward opening a bin for large items (good residual left).
        score -= 55.0 * item_frac;
        // Penalize opening bins when existing bins still have room.
        score += 45.0 * (mean_residual / bin_capacity as f64);
        // Slightly discourage proliferation late in the stream.
        score += 20.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 10.0));
    }

    // Mild preference for bins that are already well loaded.
    score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high relative waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residual too small to be useful later (min item 1, typical >= 10).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize if we consumed a scarce bin.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (item_size as f64 / bin_capacity as f64) * 0.5 + crowded * 0.5;
        score = 20.0 + 60.0 * (1.0 - pressure) - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Slight decay of openness late in the stream: consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * t * (open_bins_count as f64 / (fitting_bins_count.max(1) as f64)).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth coupling: small residuals become more valuable as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize near-full-but-wasteful outcomes smoothly (dead space that nothing fits)
    let waste = pr_norm - (next_item_size as f64 / cap);
    let waste_term = if waste > 0.0 { waste * waste } else { 0.0 };
    score += 40.0 * waste_term * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Prefer bins below mean residual slightly (balance load), smooth quadratic
    score += 0.15 * (bin_residual as f64 - mean_residual).powi(2) / (cap * cap) * 10.0;

    // Mild preference for keeping open-bin count low early, relaxing later
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Lookahead: if next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // New-bin candidate: make empty bin attractive only when current fits are poor
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 15.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

