    }

    // Slight preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.05 * (0.5 + progress);

    // Discourage accumulating many half-empty bins.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to fit even the minimum item size (1..100 range,
    // but practically gaps below ~12 are nearly dead weight) is penalized hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // Soft penalty ramp for small-but-usable gaps to prefer fuller packing.
    if post_residual >= 12 && post_residual < 25 {
        score += 0.8 * (25 - post_residual) as f64;
    }

    // Perfect fit reward: strongly favor bins that end up (almost) empty.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // and encourage closing existing bins out.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Candidate new bin: penalize more when many bins already open.
        score += 8.0 + 1.5 * pressure;
        // But if no open bin fits well (this is a last-resort situation),
        // ease the penalty so we don't fragment a tight bin.
        if fitting_bins_count == 1 && post_residual < 12 {
            score -= 30.0;
        }
    } else {
        // Existing bin: slight reward for using it, stronger when many bins open.
        score -= 0.4 * pressure;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.5 * slack.min(20.0);
    }
    // If next item would be blocked by the post residual, mild penalty when gap is tiny.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Late-stream tightening: as the stream progresses, favor tighter fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (100.0 - post_residual as f64).max(0.0) / 100.0;

    // Mean residual coupling: if this bin's post residual deviates far below the
    // mean, it's an efficient use; reward slightly.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (dead space minimization).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = post_residual - next_item_size;
        if lookahead_gap == 0 {
            // Perfect chain: this placement sets up an exact fit for the next item.
            score -= 150.0;
        } else if lookahead_gap < 10 {
            score -= 60.0;
        } else {
            // Mild penalty proportional to leftover after the lookahead fit.
            score += 0.5 * lookahead_gap as f64;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin after placement: penalize relative
        // to how badly it misses, but soften near end of stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let miss = (next_item_size - post_residual) as f64;
        score += 0.3 * miss * (1.0 - 0.5 * progress);
    }

    // Reward bins tighter than the mean residual (good fits pack dense bins).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for spreading across many open bins when residual is large.
    if open_bins_count > 4 && post_residual > 40 {
        score += 0.2 * (post_residual - 40) as f64;
    }

    // New-bin candidate: prefer opening a new bin only when item is large
    // relative to capacity (poor fit anywhere) or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 50.0;
        } else {
            score += 30.0;
        }
    }

    score
}
